&lt;li&gt;&lt;a href=&quot;#_adım_1_graphifyi_kurun_ve_knowledge_graphi_çıkarın&quot;&gt;Adım 1: Graphify&amp;#8217;i kurun ve Knowledge Graph&amp;#8217;i çıkarın&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
