&lt;li&gt;&lt;a href=&quot;#_render_kuralları&quot;&gt;Render kuralları&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_adım_3_günlük_kullanım&quot;&gt;Adım 3 : Günlük kullanım&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_diagramme_complet&quot;&gt;Diagramme complet&lt;/a&gt;&lt;/li&gt;
