&lt;li&gt;&lt;a href=&quot;#_pourquoi_cest_déterministe_et_pourquoi_ça_compte&quot;&gt;Pourquoi c&amp;#8217;est déterministe (et pourquoi ça compte)&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_diagrammes_du_pipeline_lui_même&quot;&gt;Diagrammes du pipeline lui-même&lt;/a&gt;&lt;/li&gt;
