&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_mimari_vizyon&quot;&gt;Mimari Vizyon&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_yönlendiren_ilke&quot;&gt;Yönlendiren ilke&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Mimarisi &lt;strong&gt;ilgilin ayrımı&lt;/strong&gt; prensibe:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;İçerik&lt;/strong&gt; : Yapılandırılmış AsciiDoc dosyaları zengin meta verilerle&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Sunum&lt;/strong&gt; : yeniden kullanılabilir Thymeleaf şablonları&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Veriler&lt;/strong&gt; : JBake tarafından AsciiDoc özniteliklerinden otomatik olarak çıkarılan model&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Style&lt;/strong&gt; : Bootstrap 5 görsel tutarlılık için&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_stratejik_seçim_portföy_için_asciidoc&quot;&gt;Stratejik seçim: Portföy için AsciiDoc&lt;/h3&gt;
&lt;table class=&quot;tableblock frame-all grid-all stretch&quot;&gt;
&lt;caption class=&quot;title&quot;&gt;Table 1. AsciiDoc neden ?&lt;/caption&gt;
&lt;colgroup&gt;
&lt;col style=&quot;width: 33.3333%;&quot;&gt;
&lt;col style=&quot;width: 66.6667%;&quot;&gt;
&lt;/colgroup&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;Kritér&lt;/th&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;avantaj&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;Tutarlılık&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;Blog makaleleriyle aynı format&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;Metaveriler&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;Yapılandırılmış ve genişletilebilir özellikler (&lt;code&gt;project-*&lt;/code&gt;)&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;Bakım kolaylığı&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;Basit metin düzenleme, Git ile sürüm kontrolü yapılabilir&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;Esneklik&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;Zengin içerik (tablolar, kod, resimler) içerebilir&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;şablonlama&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;JBake Thymeleaf için öznitelikleri otomatik olarak çıkarır&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_veri_modeli&quot;&gt;Veri modeli&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Her portföy projesi bir AsciiDoc belgesidir:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Üstbilgi meta verileri&lt;/strong&gt; : yapılandırılmış bilgiler (müşteri, süre, teknolojiler, vb.)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Belge gövdesi&lt;/strong&gt; : anarşif betimleme, zorluklar, çözümler, sonuçlar&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Özel özellikler&lt;/strong&gt; : önekli`project-*`otomatik çıkarma için&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam handwritten false

class ProjetAsciiDoc {
  +titre: String
  +jbake-type: &quot;proje&quot;
  +jbake-status: published|draft
  +jbake-date: Date
  +jbake-tags: List&amp;lt;String&amp;gt;
  --
  +project-category: String
  +project-client: String
  +project-duration: String
  +project-role: String
  +project-thumbnail: String
  +project-gallery: List&amp;lt;String&amp;gt;
  +project-tech-stack: String
  +project-highlights: List&amp;lt;String&amp;gt;
  +project-demo-url: String
  +project-github-url: String
  --
  +body: HTML (converti)
}

class JBakeEngine {
  +parse(asciidoc)
  +extractMetadata()
  +convertToHTML()
}

class ThymeleafTemplate {
  +portfolio.html
  +project.html
  +partials/project-card.html
}

class PortfolioPage {
  +published_projects: List
  +filtres: categories
}

ProjetAsciiDoc --&amp;gt; JBakeEngine : parse
JBakeEngine --&amp;gt; ThymeleafTemplate : fournit données
ThymeleafTemplate --&amp;gt; PortfolioPage : génère
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_detaylı_kullanım_senaryoları&quot;&gt;Detaylı Kullanım Senaryoları&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_uc1_portföye_bir_öğe_eklemek&quot;&gt;UC1 : Portföye bir öğe eklemek&lt;/h3&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_nominal_akış&quot;&gt;Nominal akış&lt;/h4&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
actor Développeur as dev
participant &quot;Düzenleyici
Metin&quot; as editor
participant &quot;Dosya\nAsciiDoc&quot; as file
participant &quot;JBake\nMotor&quot; as jbake
participant &quot;statik
site&quot; as site

dev -&amp;gt; editor : Créer nouveau fichier
activate editor
editor -&amp;gt; file : portfolio/nouveau-projet.adoc
activate file

dev -&amp;gt; editor : Rédiger en-tête avec métadonnées\n(titre, type=project, status=published,\nattributs project-*)
dev -&amp;gt; editor : Rédiger contenu narratif\n(contexte, défis, solutions)
dev -&amp;gt; editor : Ajouter images dans assets/img/portfolio/

editor -&amp;gt; file : Sauvegarder
deactivate editor

dev -&amp;gt; jbake : Lancer build (jbake -b)
activate jbake
jbake -&amp;gt; file : Lire et parser
jbake -&amp;gt; jbake : Extraire métadonnées
jbake -&amp;gt; jbake : Convertir AsciiDoc → HTML
jbake -&amp;gt; jbake : Appliquer template project.html
jbake -&amp;gt; jbake : Ajouter à la liste portfolio.html
jbake -&amp;gt; site : Générer pages statiques
deactivate jbake

dev -&amp;gt; site : Vérifier résultat
activate site
site --&amp;gt; dev : Afficher projet
deactivate site
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_oluşturulacak_dosya_şablonu&quot;&gt;Oluşturulacak dosya şablonu&lt;/h4&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Geliştirici oluşturur`content/portfolio/nom-projet.adoc`standartlaştırılmış bir yapıyla :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Tüm gerekli özniteliklere sahip başlık&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Normalleştirilmiş bölümler (Bağlam, Zorluklar, Çözümler, Sonuçlar)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Görüntüler için tutarlı adlandırma&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_doğrulama_puanları&quot;&gt;Doğrulama puanları&lt;/h4&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Zorunlu öznitelikler mevcut (&lt;code&gt;jbake-type&lt;/code&gt;, &lt;code&gt;jbake-status&lt;/code&gt;, &lt;code&gt;project-thumbnail&lt;/code&gt;)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Bağlantı verilen görüntüler içinde bulunur`assets/img/portfolio/`&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;JBake derlemesi hatasız olarak başarılı olur&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Proje, portföy sayfasında görünür.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Bireysel proje sayfası doğru şekilde görüntüleniyor.&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_uc2_portföyden_bir_öğeyi_sil&quot;&gt;UC2 : Portföyden bir öğeyi sil&lt;/h3&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_nominal_akış_2&quot;&gt;Nominal akış&lt;/h4&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
actor Développeur as dev
participant &quot;Sistem
Dosyalar&quot; as fs
participant &quot;JBake\nMotor&quot; as jbake
participant &quot;site
statik&quot; as site
database &quot;Önbellek
JBake&quot; as cache

dev -&amp;gt; fs : Supprimer portfolio/projet-ancien.adoc
activate fs
fs --&amp;gt; dev : Fichier supprimé
deactivate fs

dev -&amp;gt; fs : (Optionnel) Supprimer images associées\nassets/img/portfolio/projet-ancien-*
activate fs
fs --&amp;gt; dev : Images supprimées
deactivate fs

dev -&amp;gt; cache : Nettoyer cache JBake
activate cache
cache --&amp;gt; dev : Cache vidé
deactivate cache

dev -&amp;gt; jbake : Rebuild complet (jbake -b)
activate jbake
jbake -&amp;gt; jbake : Scanner content/portfolio/
jbake -&amp;gt; jbake : Projet absent → non généré
jbake -&amp;gt; jbake : Régénérer portfolio.html\n(sans le projet supprimé)
jbake -&amp;gt; site : Déployer nouveau build
deactivate jbake

dev -&amp;gt; site : Vérifier
activate site
site --&amp;gt; dev : Projet absent de la liste
deactivate site
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_alternatif_strateji_arşivleme&quot;&gt;Alternatif strateji: arşivleme&lt;/h4&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Kalıcı olarak silmek yerine, bir klasör oluşturma olanağı`content/portfolio/archive/`:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Dosyayı silmek yerine taşı&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Kolayca geri yüklemeye izin verir&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Git geçmişini daha açık tut&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_kaynak_temizliği&quot;&gt;Kaynak temizliği&lt;/h4&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Yetim görüntülerde kontrol et`assets/img/portfolio/`&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Başka projeler tarafından referans alınmayan görüntüleri sil&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;JBake önbelleğini temizleyerek hayalet referanslardan kaçının&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_uc3_yayınlanmamış_taslak_yap&quot;&gt;UC3: Yayınlanmamış (taslak) yap&lt;/h3&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_nominal_akış_3&quot;&gt;nominal akış&lt;/h4&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
actor Développeur as dev
participant &quot;Dosya\nAsciiDoc&quot; as file
participant &quot;JBake
Engine&quot; as jbake
participant &quot;Site
Statik&quot; as site

dev -&amp;gt; file : Ouvrir portfolio/projet.adoc
activate file

dev -&amp;gt; file : Modifier attribut\n:jbake-status: published\n↓\n:jbake-status: draft

file --&amp;gt; dev : Sauvegardé
deactivate file

dev -&amp;gt; jbake : Rebuild (jbake -b)
activate jbake
jbake -&amp;gt; file : Parser le fichier
jbake -&amp;gt; jbake : Détecter status=draft
jbake -&amp;gt; jbake : Exclure de published_projects
jbake -&amp;gt; jbake : Ne pas créer page publique
note right
  Le projet existe toujours
  mais n&#39;est pas publié
end note
jbake -&amp;gt; site : Générer site (sans ce projet)
deactivate jbake

dev -&amp;gt; site : Vérifier portfolio
activate site
site --&amp;gt; dev : Projet absent de la liste publique
deactivate site
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_olası_durumlar&quot;&gt;Olası durumlar&lt;/h4&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

[*] --&amp;gt; Draft : Création initiale
Draft --&amp;gt; Published : Validation et publication
Published --&amp;gt; Draft : Retrait temporaire
Draft --&amp;gt; Archived : Projet abandonné
Published --&amp;gt; Archived : Projet obsolète
Archived --&amp;gt; [*] : Suppression définitive
Published --&amp;gt; Published : Mises à jour

note right of Draft
  :jbake-status: draft
  Non visible publiquement
  Utile pour projets en cours
end note

note right of Published
  :jbake-status: published
  Visible sur le portfolio
  Indexé par JBake
end note

note right of Archived
  Déplacé dans archive/
  ou jbake-status: archived
  Non publié mais conservé
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_tipik_kullanım_durumları&quot;&gt;Tipik kullanım durumları&lt;/h4&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Taslak aşamasında proje&lt;/strong&gt; : taslak olarak oluştur, hazır olduğunda yayınla&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Geçici gizli proje&lt;/strong&gt; : Müşteri onay süresi boyunca drafta geçmek&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Ana güncelleme&lt;/strong&gt; : taslağa geçmek, düzenlemek, yeniden yayınlamak&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;A/B testing&lt;/strong&gt; : taslakta kopyala, test et, en iyi versiyonu yayınla&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_templating_mimarisi&quot;&gt;Templating mimarisi&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_yeniden_kullanılabilir_şablon_stratejisi&quot;&gt;Yeniden kullanılabilir şablon stratejisi&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam componentStyle rectangle

package &quot;Thymeleaf şablonları&quot; {
  component [index.html] as index
  component [portfolio.html] as portfolio
  component [project.html] as project

  package &quot;Kısımlar&quot; {
    component [header.html] as header
    component [footer.html] as footer
    component [project-card.html] as card
    component [tech-badge.html] as badge
    component [gallery.html] as gallery
  }
}

package &quot;veriler JBake&quot; {
  database &quot;yayınlanmış_projeler&quot; as data
  database &quot;içerik (proje)&quot; as content
}

index --&amp;gt; header
index --&amp;gt; footer

portfolio --&amp;gt; header
portfolio --&amp;gt; footer
portfolio --&amp;gt; card
data --&amp;gt; portfolio : itération

project --&amp;gt; header
project --&amp;gt; footer
project --&amp;gt; badge
project --&amp;gt; gallery
content --&amp;gt; project : projet individuel

note right of card
  Fragment réutilisable
  pour afficher une carte
  de projet avec :
  - thumbnail
  - titre
  - tags
  - highlights
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_veri_çıkarma_deseni&quot;&gt;Veri çıkarma deseni&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;JBake, AsciiDoc özelliklerini Thymeleaf içinde erişilebilir özelliklere otomatik olarak dönüştürür:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

rectangle &quot;AsciiDoc Belgesi&quot; {
  (&quot;:project-client: Acme Corp&quot;) as attr1
  (&quot;:project-duration: 6 ay&quot;) as attr2
  (&quot;:project-tags: java, react&quot;) as attr3
}

rectangle &quot;JBake modeli&quot; {
  (content[&#39;project-client&#39;]) as prop1
  (content[&#39;project-duration&#39;]) as prop2
  (content.tags) as prop3
}

rectangle &quot;Şablon Thymeleaf&quot; {
  (th:text=&quot;${project[&#39;project-client&#39;]}&quot;) as tmpl1
  (th:text=&quot;${project[&#39;project-duration&#39;]}&quot;) as tmpl2
  (th:each=&quot;etiket : ${project.tags}&quot;) as tmpl3
}

attr1 --&amp;gt; prop1 : parsing
attr2 --&amp;gt; prop2 : parsing
attr3 --&amp;gt; prop3 : parsing

prop1 --&amp;gt; tmpl1 : binding
prop2 --&amp;gt; tmpl2 : binding
prop3 --&amp;gt; tmpl3 : binding
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_adlandırma_kuralları&quot;&gt;Adlandırma kuralları&lt;/h3&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Proje Özellikleri&lt;/strong&gt; : önek`project-*` (ex: &lt;code&gt;project-client&lt;/code&gt;, &lt;code&gt;project-tech-stack&lt;/code&gt;)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Dosyalar&lt;/strong&gt; : kebab-case (ex:`ecommerce-platform.adoc`)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Resimler&lt;/strong&gt;: proje adı öneki (örnek:`ecommerce-platform-thumb.jpg`)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Templates&lt;/strong&gt; : fonksiyonel isim (örnek:`project-card.html`, &lt;code&gt;tech-badge.html&lt;/code&gt;)&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_yayımlama_i̇ş_akışı&quot;&gt;Yayımlama İş Akışı&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_geliştirme_hattı&quot;&gt;Geliştirme hattı&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam handwritten false

class ProjetAsciiDoc {
  +titre: String
  +jbake-type: &quot;proje&quot;
  +jbake-status: published|draft
  +jbake-date: Date
  +jbake-tags: List&amp;lt;String&amp;gt;
  __
  +project-category: String
  +project-client: String
  +project-duration: String
  +project-role: String
  +project-thumbnail: String
  +project-gallery: List&amp;lt;String&amp;gt;
  +project-tech-stack: String
  +project-highlights: List&amp;lt;String&amp;gt;
  +project-demo-url: String
  +project-github-url: String
  __
  +body: HTML (converti)
}

class JBakeEngine {
  +parse(asciidoc)
  +extractMetadata()
  +convertToHTML()
}

class ThymeleafTemplate {
  +portfolio.html
  +project.html
  +partials/project-card.html
}

class PortfolioPage {
  +published_projects: List
  +filtres: categories
}

ProjetAsciiDoc --&amp;gt; JBakeEngine : parse
JBakeEngine --&amp;gt; ThymeleafTemplate : fournit données
ThymeleafTemplate --&amp;gt; PortfolioPage : génère
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_ortamlar&quot;&gt;Ortamlar&lt;/h3&gt;
&lt;table class=&quot;tableblock frame-all grid-all stretch&quot;&gt;
&lt;colgroup&gt;
&lt;col style=&quot;width: 20%;&quot;&gt;
&lt;col style=&quot;width: 40%;&quot;&gt;
&lt;col style=&quot;width: 40%;&quot;&gt;
&lt;/colgroup&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;Çevre&lt;/th&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;Kullanım&lt;/th&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;Kabul Edilen Durum&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;yerel&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;Geliştirme ve ön izleme&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;draft, published&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;Sahneleme&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;Ön üretim doğrulama&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;published sadece&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;Üretim&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;Site public&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;published uniquement&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_extensibilité&quot;&gt;Extensibilité&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_ajout_de_nouveaux_attributs&quot;&gt;Ajout de nouveaux attributs&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Pour enrichir le modèle de données, simplement ajouter de nouveaux attributs préfixés &lt;code&gt;project-*&lt;/code&gt; :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;project-awards&lt;/code&gt;: Prix et reconnaissances&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;project-testimonial&lt;/code&gt;: Citation client&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;project-team-size&lt;/code&gt;: Taille équipe&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;project-budget-range&lt;/code&gt;: Fourchette budgétaire&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Ces attributs deviennent automatiquement disponibles dans les templates sans modification du moteur JBake.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_catégorisation_avancée&quot;&gt;Catégorisation avancée&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

object Projet {
  project-category = &quot;web&quot;
  project-subcategory = &quot;ecommerce&quot;
  project-industry = &quot;retail&quot;
  project-complexity = &quot;high&quot;
}

object Taxonomie {
  categories : [web, mobile, data, devops]
  subcategories : Map&amp;lt;category, List&amp;gt;
  industries : [retail, finance, healthcare, ...]
  complexities : [low, medium, high]
}

Projet --&amp;gt; Taxonomie : classifié selon

note right of Taxonomie
  Permet filtrage multi-critères
  dans le template portfolio.html
  via JavaScript ou côté serveur
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_bonnes_pratiques&quot;&gt;Bonnes Pratiques&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_organisation_des_fichiers&quot;&gt;Organisation des fichiers&lt;/h3&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Un fichier = un projet&lt;/strong&gt; : éviter de mélanger plusieurs projets&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Images dans dossier dédié&lt;/strong&gt; : &lt;code&gt;assets/img/portfolio/nom-projet/&lt;/code&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Nomenclature cohérente&lt;/strong&gt; : facilite recherche et maintenance&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Versioning Git&lt;/strong&gt; : tracking complet des modifications&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_i̇çerik_yönetimi&quot;&gt;İçerik yönetimi&lt;/h3&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Statut draft par défaut&lt;/strong&gt; : publier seulement quand prêt&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Review avant publication&lt;/strong&gt; : validation qualité et confidentialité&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Métadonnées complètes&lt;/strong&gt; : remplir tous les champs pertinents&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Contenu narratif riche&lt;/strong&gt; : ne pas se limiter aux métadonnées&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_performance&quot;&gt;Performance&lt;/h3&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Optimiser images&lt;/strong&gt; : compression avant commit&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Pagination si nécessaire&lt;/strong&gt; : si &amp;gt;20 projets&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Lazy loading&lt;/strong&gt; : images des galeries chargées à la demande&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Cache navigateur&lt;/strong&gt; : headers appropriés pour assets&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_sonuç&quot;&gt;Sonuç&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Cette architecture permet :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Simplicité d&amp;#8217;usage&lt;/strong&gt; : ajouter un projet = créer un fichier texte&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Flexibilité&lt;/strong&gt; : extensible via nouveaux attributs&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Maintenabilité&lt;/strong&gt; : séparation contenu/présentation&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Traçabilité&lt;/strong&gt; : versioning Git complet&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Automatisation&lt;/strong&gt; : build et déploiement continus possibles&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Le choix d&amp;#8217;AsciiDoc assure la cohérence avec le reste du site tout en offrant la richesse des métadonnées nécessaires à un portfolio professionnel.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;preamble&quot;&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;div class=&quot;title&quot;&gt;temps de lecture : 12 minutes&lt;/div&gt;
&lt;p&gt;Plutôt que de choisir entre la simplicité de Supabase et la puissance de Spring Boot, pourquoi ne pas combiner les deux ? Découvrez une architecture hybride qui exploite le meilleur de chaque technologie.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;dlist&quot;&gt;
&lt;dl&gt;
&lt;dt class=&quot;hdlist1&quot;&gt;toc&lt;/dt&gt;
&lt;dd&gt;
&lt;p&gt;[]&lt;/p&gt;
&lt;/dd&gt;
&lt;/dl&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_le_faux_dilemme_de_larchitecture_moderne&quot;&gt;Le Faux Dilemme de l&amp;#8217;Architecture Moderne&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Lorsqu&amp;#8217;on construit une application moderne avec un frontend statique, on se retrouve souvent face à un choix binaire :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Tout miser sur une solution Backend-as-a-Service&lt;/strong&gt; (Supabase, Firebase) - simple mais limitée&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Construire un backend complet&lt;/strong&gt; (Spring Boot, Node.js) - puissant mais complexe&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Ce choix est un faux dilemme. L&amp;#8217;architecture hybride propose une troisième voie : &lt;strong&gt;utiliser chaque technologie là où elle excelle&lt;/strong&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_vision_architecturale&quot;&gt;Vision Architecturale&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_larchitecture_traditionnelle_monolithique&quot;&gt;L&amp;#8217;Architecture Traditionnelle : Monolithique&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam componentStyle rectangle

package &quot;Architecture Traditionnelle&quot; {
  actor Utilisateur as user
  component &quot;Frontend&quot; as frontend #LightBlue
  component &quot;Backend Monolithique&quot; as backend #LightCoral {
    [Authentification]
    [CRUD]
    [Logique Métier]
    [Jobs]
    [APIs Tierces]
  }
  database &quot;Base de Données&quot; as db #LightGray

  user --&amp;gt; frontend
  frontend --&amp;gt; backend : Toutes les requêtes
  backend --&amp;gt; db
}

note right of backend
  Tout passe par le backend
  même les opérations simples

  ⚠️ Point de congestion unique
  ⚠️ Complexité dès le départ
  ⚠️ Couplage fort
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Dans cette approche, même les opérations les plus simples (lecture d&amp;#8217;un article, création d&amp;#8217;un commentaire) doivent transiter par votre backend. Vous payez le coût de la complexité dès le premier jour.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_larchitecture_baas_tout_délégué&quot;&gt;L&amp;#8217;Architecture BaaS : Tout Délégué&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam componentStyle rectangle

package &quot;Architecture BaaS Pure&quot; {
  actor Utilisateur as user
  component &quot;Frontend&quot; as frontend #LightBlue
  cloud &quot;Supabase / Firebase&quot; as baas #LightGreen {
    [Auth]
    [Database]
    [Storage]
    [Edge Functions]
  }

  user --&amp;gt; frontend
  frontend --&amp;gt; baas : Toutes les opérations
}

note right of baas
  Développement rapide
  Pas de serveur à gérer

  ⚠️ Limité pour logique complexe
  ⚠️ Vendor lock-in
  ⚠️ Edge Functions contraintes
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;À l&amp;#8217;opposé, tout déléguer à un BaaS est séduisant au début mais montre rapidement ses limites dès que la logique métier se complexifie.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_larchitecture_hybride_séparation_des_responsabilités&quot;&gt;L&amp;#8217;Architecture Hybride : Séparation des Responsabilités&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam componentStyle rectangle

actor Utilisateur as user #LightBlue

package &quot;Couche Frontend&quot; {
  component &quot;Site Statique JBake&quot; as frontend #SkyBlue
}

package &quot;Couche Simple (Supabase)&quot; #LightGreen {
  component &quot;Authentification&quot; as auth
  component &quot;CRUD Basique&quot; as crud
  component &quot;Stockage Fichiers&quot; as storage
  component &quot;Temps Réel&quot; as realtime
}

package &quot;Couche Métier (Spring Boot)&quot; #Coral {
  component &quot;Logique Complexe&quot; as logic
  component &quot;Orchestration&quot; as orchestration
  component &quot;Jobs Planifiés&quot; as jobs
  component &quot;Intégrations&quot; as integrations
}

database &quot;PostgreSQL Partagé&quot; as db #LightGray

user --&amp;gt; frontend

frontend --&amp;gt; auth : OAuth2, JWT
frontend --&amp;gt; crud : Articles, Profils
frontend --&amp;gt; storage : Images, Fichiers
frontend --&amp;gt; realtime : Notifications

frontend --&amp;gt; logic : Calculs, Rapports
frontend --&amp;gt; orchestration : Workflows
logic --&amp;gt; integrations : Stripe, APIs
orchestration --&amp;gt; db
jobs --&amp;gt; db

crud --&amp;gt; db
auth --&amp;gt; db

note bottom of db
  **Une seule source de vérité**
  Partagée entre Supabase et Spring Boot
end note

note right of auth
  **Gratuit jusqu&#39;à 50k users**
  Configuration en quelques clics
  OAuth2 multi-providers
end note

note right of logic
  **Activé seulement si nécessaire**
  Kotlin + Coroutines
  Transactions complexes
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;L&amp;#8217;architecture hybride sépare clairement les responsabilités selon la complexité et la nature des opérations.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_principes_de_conception&quot;&gt;Principes de Conception&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_principe_1_commencer_simple_évoluer_intelligemment&quot;&gt;Principe 1 : Commencer Simple, Évoluer Intelligemment&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

rectangle &quot;**Phase 1 : MVP**&quot; #LightGreen {
  component &quot;JBake + Supabase&quot; as mvp
  note right
    ✓ Développement en jours
    ✓ Coût : 0€
    ✓ Validation concept
  end note
}

rectangle &quot;**Phase 2 : Croissance**&quot; #LightYellow {
  component &quot;JBake + Supabase\n+ Spring Boot (optionnel)&quot; as growth
  note right
    ✓ Logique métier émerge
    ✓ Premiers jobs planifiés
    ✓ Intégrations tierces
  end note
}

rectangle &quot;**Phase 3 : Scale**&quot; #LightCoral {
  component &quot;Architecture Complète&quot; as scale
  note right
    ✓ Orchestration complexe
    ✓ Performances optimisées
    ✓ Cache distribué
  end note
}

mvp -down-&amp;gt; growth : Quand la complexité\nle justifie
growth -down-&amp;gt; scale : Optimisation\ncontinue
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Ne construisez pas Spring Boot si vous n&amp;#8217;en avez pas besoin.&lt;/strong&gt; Démarrez avec Supabase, ajoutez Spring Boot quand la complexité le justifie.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_principe_2_séparation_par_nature_dopération&quot;&gt;Principe 2 : Séparation par Nature d&amp;#8217;Opération&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startmindmap
skinparam backgroundColor #FEFEFE
* Opérations\nApplicatives

left side

** Opérations Simples\n(Supabase)
***_ CRUD Standard
****_ Lecture
****_ Création
****_ Mise à jour
****_ Suppression
***_ Authentification
****_ Login/Logout
****_ OAuth2
****_ Gestion session
***_ Stockage
****_ Upload fichiers
****_ CDN automatique
***_ Temps Réel
****_ WebSocket
****_ Notifications

right side

** Opérations Complexes\n(Spring Boot)
***_ Logique Métier
****_ Calculs complexes
****_ Règles métier
****_ Validations avancées
***_ Orchestration
****_ Multi-services
****_ Transactions distribuées
****_ Saga patterns
***_ Tâches Planifiées
****_ Rapports périodiques
****_ Synchronisations
****_ Nettoyages
***_ Intégrations
****_ Paiements (Stripe)
****_ APIs tierces
****_ Services ML/AI

@endmindmap&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_principe_3_une_seule_source_de_vérité&quot;&gt;Principe 3 : Une Seule Source de Vérité&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

database &quot;PostgreSQL&quot; as db #LightGray {
  package &quot;Schema: auth (Supabase)&quot; #LightGreen {
    [users]
    [sessions]
    [identities]
  }

  package &quot;Schema: public (Partagé)&quot; #SkyBlue {
    [articles]
    [comments]
    [profiles]
  }

  package &quot;Schema: business (Spring Boot)&quot; #Coral {
    [orders]
    [payments]
    [reports]
  }
}

component &quot;Supabase&quot; as supabase #LightGreen
component &quot;Spring Boot&quot; as spring #Coral

supabase -down-&amp;gt; users : Gère
supabase -down-&amp;gt; sessions : Gère
supabase -down-&amp;gt; articles : Accède
supabase -down-&amp;gt; comments : Accède
supabase -down-&amp;gt; profiles : Accède

spring -down-&amp;gt; articles : Accède
spring -down-&amp;gt; profiles : Accède
spring -down-&amp;gt; orders : Gère
spring -down-&amp;gt; payments : Gère
spring -down-&amp;gt; reports : Gère

note right of db
  **Avantages :**
  • Pas de synchronisation complexe
  • JOINs possibles entre tables
  • Cohérence garantie
  • Migrations unifiées
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;En partageant la même instance PostgreSQL, Supabase et Spring Boot travaillent sur les mêmes données sans synchronisation complexe.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_orchestration_des_flux&quot;&gt;Orchestration des Flux&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_flux_1_authentification_centralisée&quot;&gt;Flux 1 : Authentification Centralisée&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
autonumber

actor &quot;Utilisateur&quot; as user
participant &quot;JBake&quot; as jbake
participant &quot;Supabase Auth&quot; as auth
participant &quot;Spring Boot&quot; as spring
database &quot;PostgreSQL&quot; as db

== Authentification ==
user -&amp;gt; jbake : Clique &quot;Se connecter&quot;
jbake -&amp;gt; auth : Redirect OAuth2 (Google/GitHub)
auth -&amp;gt; user : Consent screen
user -&amp;gt; auth : Autorise
auth -&amp;gt; auth : Génère JWT
auth -&amp;gt; jbake : Retourne JWT + Refresh Token
jbake -&amp;gt; jbake : Stocke tokens (sessionStorage)

== Accès aux Ressources ==
group Opération Simple (CRUD)
  user -&amp;gt; jbake : Crée un article
  jbake -&amp;gt; db : POST avec JWT
  note right: Supabase Row Level Security\nvérifie le JWT automatiquement
  db -&amp;gt; jbake : Article créé
end

group Opération Complexe (Métier)
  user -&amp;gt; jbake : Génère un rapport
  jbake -&amp;gt; spring : POST /api/reports\navec JWT
  spring -&amp;gt; spring : Valide JWT Supabase
  spring -&amp;gt; spring : Extrait claims (user_id, roles)
  spring -&amp;gt; db : Requêtes complexes
  spring -&amp;gt; jbake : Rapport généré
end

note over auth, spring
  **Le JWT est universel**
  Valide par Supabase ET Spring Boot
  Pas de double authentification
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Point clé&lt;/strong&gt; : Un seul processus d&amp;#8217;authentification, un seul JWT, utilisable partout.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_flux_2_orchestration_dun_processus_métier_complexe&quot;&gt;Flux 2 : Orchestration d&amp;#8217;un Processus Métier Complexe&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
autonumber

actor &quot;Client&quot; as user
participant &quot;JBake&quot; as jbake
participant &quot;Spring Boot&quot; as spring
participant &quot;Supabase DB&quot; as supadb
participant &quot;Stripe API&quot; as stripe
participant &quot;Inventory Service&quot; as inventory
participant &quot;Email Service&quot; as email
database &quot;PostgreSQL&quot; as db

user -&amp;gt; jbake : Passe commande
jbake -&amp;gt; spring : POST /api/orders/create

== Orchestration Spring Boot ==
spring -&amp;gt; db : BEGIN TRANSACTION

par Vérifications Parallèles
  spring -&amp;gt; inventory : Vérifier stock
  inventory -&amp;gt; spring : Stock OK
else
  spring -&amp;gt; db : Vérifier profil client
  db -&amp;gt; spring : Client vérifié
end

spring -&amp;gt; stripe : Créer Payment Intent
stripe -&amp;gt; spring : Intent créé (ID: pi_xxx)

spring -&amp;gt; db : Créer Order (status: PENDING)
db -&amp;gt; spring : Order créé

spring -&amp;gt; stripe : Confirmer paiement
stripe -&amp;gt; spring : Paiement confirmé

spring -&amp;gt; db : Update Order (status: PAID)
spring -&amp;gt; inventory : Décrémenter stock
spring -&amp;gt; db : COMMIT TRANSACTION

par Notifications Asynchrones
  spring -&amp;gt; email : Email confirmation
else
  spring -&amp;gt; supadb : Insert notification
  note right: Notification temps réel\nvia Supabase Realtime
end

spring -&amp;gt; jbake : Order confirmé
jbake -&amp;gt; user : Affiche confirmation

note over spring
  **Responsabilités Spring Boot :**
  • Transaction ACID
  • Orchestration multi-services
  • Rollback automatique si erreur
  • Gestion des cas limites
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Ce que Spring Boot apporte&lt;/strong&gt; : Orchestration fiable de processus complexes impliquant plusieurs systèmes avec garantie transactionnelle.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_flux_3_jobs_planifiés_et_synchronisations&quot;&gt;Flux 3 : Jobs Planifiés et Synchronisations&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

participant &quot;Scheduler\n(Spring Boot)&quot; as scheduler
participant &quot;Report Service&quot; as report
participant &quot;PostgreSQL&quot; as db
participant &quot;External API&quot; as api
participant &quot;Email Service&quot; as email
participant &quot;Supabase Storage&quot; as storage

== Job Quotidien : 2h00 ==
activate scheduler
scheduler -&amp;gt; report : Déclenche génération rapport

activate report
report -&amp;gt; db : Récupère données\ndes dernières 24h
db -&amp;gt; report : Dataset

report -&amp;gt; report : Calculs &amp;amp; Agrégations
report -&amp;gt; report : Génération PDF

report -&amp;gt; storage : Upload PDF
storage -&amp;gt; report : URL publique

report -&amp;gt; email : Envoie aux admins\navec lien PDF
deactivate report

== Job Hebdomadaire : Dimanche 3h00 ==
scheduler -&amp;gt; report : Synchronisation externe

activate report
report -&amp;gt; api : Fetch données externes
api -&amp;gt; report : Nouvelles données

report -&amp;gt; db : Mise à jour tables
report -&amp;gt; db : Nettoyage données obsolètes
deactivate report

== Job Mensuel : 1er du mois ==
scheduler -&amp;gt; report : Facturation

activate report
report -&amp;gt; db : Liste clients actifs
report -&amp;gt; report : Calcul montants
report -&amp;gt; api : Génération factures (Stripe)
report -&amp;gt; email : Envoi factures
deactivate report

deactivate scheduler

note right of scheduler
  **Impossible avec Supabase seul**
  Edge Functions non adaptées
  pour jobs longs et récurrents
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Ce que Spring Boot apporte&lt;/strong&gt; : Jobs planifiés fiables avec gestion d&amp;#8217;état, retry automatique, et exécution garantie.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_matrice_de_décision&quot;&gt;Matrice de Décision&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_quand_utiliser_supabase&quot;&gt;Quand Utiliser Supabase ?&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

start

:Nouvelle fonctionnalité à implémenter;

if (CRUD simple ?) then (oui)
  :✅ **Supabase**;
  stop
else (non)
  if (Authentification ?) then (oui)
    :✅ **Supabase Auth**;
    stop
  else (non)
    if (Upload fichiers ?) then (oui)
      :✅ **Supabase Storage**;
      stop
    else (non)
      if (Temps réel ?) then (oui)
        :✅ **Supabase Realtime**;
        stop
      else (non)
        if (Row Level Security\nsuffisante ?) then (oui)
          :✅ **Supabase + Policies**;
          stop
        else (non)
          :⚠️ **Considérer Spring Boot**;
          #Coral:Passer à l&#39;arbre\nde décision Spring Boot;
          stop
        endif
      endif
    endif
  endif
endif

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_quand_utiliser_spring_boot&quot;&gt;Quand Utiliser Spring Boot ?&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

start

:Nouvelle fonctionnalité complexe;

if (Orchestration\nmulti-services ?) then (oui)
  :✅ **Spring Boot**;
  stop
else (non)
  if (Transaction ACID\ncritique ?) then (oui)
    :✅ **Spring Boot**;
    stop
  else (non)
    if (Job planifié ?) then (oui)
      :✅ **Spring Boot Scheduler**;
      stop
    else (non)
      if (Intégration API\ntierce complexe ?) then (oui)
        :✅ **Spring Boot**;
        stop
      else (non)
        if (Calculs lourds\n&amp;gt; 10 secondes ?) then (oui)
          :✅ **Spring Boot**;
          stop
        else (non)
          if (Cache distribué\nnécessaire ?) then (oui)
            :✅ **Spring Boot + Redis**;
            stop
          else (non)
            :⚠️ **Probablement Supabase**;
            #LightGreen:Revenir à l&#39;arbre\nde décision Supabase;
            stop
          endif
        endif
      endif
    endif
  endif
endif

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_exemples_darchitecture_par_type_de_projet&quot;&gt;Exemples d&amp;#8217;Architecture par Type de Projet&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_blog_portfolio&quot;&gt;Blog / Portfolio&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam componentStyle rectangle

package &quot;Blog Personnel - 95% Supabase&quot; {
  component &quot;JBake&quot; as jbake #SkyBlue

  package &quot;Supabase (Gratuit)&quot; #LightGreen {
    [Auth: OAuth2 Google]
    [Articles (CRUD)]
    [Commentaires]
    [Images (Storage)]
    [Notifications Realtime]
  }

  package &quot;Spring Boot (Optionnel)&quot; #LightCoral {
    [Newsletter Mensuelle]
    note bottom: Job planifié uniquement
  }

  database &quot;PostgreSQL&quot; as db

  jbake --&amp;gt; [Auth: OAuth2 Google]
  jbake --&amp;gt; [Articles (CRUD)]
  jbake --&amp;gt; [Commentaires]
  jbake --&amp;gt; [Images (Storage)]
  jbake --&amp;gt; [Notifications Realtime]

  [Articles (CRUD)] --&amp;gt; db
  [Commentaires] --&amp;gt; db
  [Newsletter Mensuelle] --&amp;gt; db
}

note bottom of &quot;Spring Boot (Optionnel)&quot;
  **Spring Boot pas obligatoire**
  Newsletter peut être gérée
  par un service tiers (Mailchimp)
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Verdict&lt;/strong&gt; : 100% Supabase suffit largement.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_application_saas&quot;&gt;Application SaaS&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam componentStyle rectangle

package &quot;Application SaaS - Architecture Hybride&quot; {
  component &quot;JBake / React&quot; as frontend #SkyBlue

  package &quot;Supabase&quot; #LightGreen {
    [Auth Multi-tenant]
    [Profils Utilisateurs]
    [Données Simples]
    [Storage Documents]
  }

  package &quot;Spring Boot&quot; #Coral {
    [Facturation (Stripe)]
    [Analytics Avancées]
    [Rapports Mensuels]
    [Quotas &amp;amp; Limites]
    [Webhooks Stripe]
  }

  cloud &quot;Services Externes&quot; {
    [Stripe API]
    [SendGrid Email]
  }

  database &quot;PostgreSQL Partagé&quot; as db

  frontend --&amp;gt; [Auth Multi-tenant]
  frontend --&amp;gt; [Profils Utilisateurs]
  frontend --&amp;gt; [Données Simples]
  frontend --&amp;gt; [Facturation (Stripe)]
  frontend --&amp;gt; [Analytics Avancées]

  [Auth Multi-tenant] --&amp;gt; db
  [Profils Utilisateurs] --&amp;gt; db
  [Données Simples] --&amp;gt; db

  [Facturation (Stripe)] --&amp;gt; db
  [Facturation (Stripe)] --&amp;gt; [Stripe API]
  [Analytics Avancées] --&amp;gt; db
  [Rapports Mensuels] --&amp;gt; db
  [Rapports Mensuels] --&amp;gt; [SendGrid Email]
  [Webhooks Stripe] ..&amp;gt; [Stripe API] : Écoute
}

note right of &quot;Spring Boot&quot;
  **Nécessaire pour :**
  • Gestion abonnements
  • Facturation récurrente
  • Quotas dynamiques
  • Analytics complexes
  • Webhooks fiables
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Verdict&lt;/strong&gt; : Architecture hybride nécessaire. Supabase pour l&amp;#8217;essentiel, Spring Boot pour la partie critique (paiements, facturation).&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_e_commerce&quot;&gt;E-commerce&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam componentStyle rectangle

package &quot;E-commerce - 70% Spring Boot&quot; {
  component &quot;Storefront (JBake/React)&quot; as frontend #SkyBlue

  package &quot;Supabase&quot; #LightGreen {
    [Auth Clients]
    [Catalogue Produits\n(lecture seule)]
    [Images Produits]
  }

  package &quot;Spring Boot (Cœur Métier)&quot; #Coral {
    [Gestion Commandes]
    [Paiements Stripe]
    [Gestion Stock]
    [Calcul Frais Port]
    [Génération Factures]
    [Synchronisation ERP]
    [Emails Transactionnels]
  }

  cloud &quot;Intégrations&quot; {
    [Stripe]
    [Transporteur API]
    [ERP Externe]
  }

  database &quot;PostgreSQL&quot; as db

  frontend --&amp;gt; [Auth Clients]
  frontend --&amp;gt; [Catalogue Produits\n(lecture seule)]
  frontend --&amp;gt; [Gestion Commandes]

  [Auth Clients] --&amp;gt; db
  [Catalogue Produits\n(lecture seule)] --&amp;gt; db

  [Gestion Commandes] --&amp;gt; db
  [Paiements Stripe] --&amp;gt; [Stripe]
  [Gestion Stock] --&amp;gt; db
  [Calcul Frais Port] --&amp;gt; [Transporteur API]
  [Génération Factures] --&amp;gt; db
  [Synchronisation ERP] --&amp;gt; [ERP Externe]
  [Synchronisation ERP] --&amp;gt; db
}

note right of &quot;Spring Boot (Cœur Métier)&quot;
  **Spring Boot indispensable :**
  • Transactions critiques
  • Orchestration complexe
  • Intégrations multiples
  • Conformité légale
  • Jobs de synchronisation
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Verdict&lt;/strong&gt; : Spring Boot indispensable. Supabase pour auth et catalogue uniquement.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_stratégie_de_migration_progressive&quot;&gt;Stratégie de Migration Progressive&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

|Semaine 1-2|
start
:Créer projet Supabase;
:Configurer Auth (Google, GitHub);
:Définir schéma PostgreSQL initial;
:Implémenter CRUD de base sur JBake;
:Déployer MVP sur GitHub Pages;
note right
  **Livrable :** Application fonctionnelle
  **Coût :** 0€
  **Temps :** 1-2 semaines
end note

|Semaine 3-4|
:Observer utilisation réelle;
:Identifier limitations;

|Décision|
if (Logique complexe\némerge ?) then (non)
  |Supabase|
  :Continuer avec Supabase seul;
  :Ajouter Edge Functions si besoin;
  stop
else (oui)
  |Spring Boot|
  :Créer projet Spring Boot;
  :Configurer validation JWT Supabase;
  :Migrer logique complexe vers Spring Boot;
  note right
    **Migration sélective**
    Seulement ce qui est complexe
  end note
endif

|Semaines suivantes|
:Déployer Spring Boot (Cloud Run, EC2);
:Connecter à PostgreSQL Supabase;
:Implémenter premiers jobs planifiés;
:Intégrer APIs tierces;

stop

note right
  **Architecture finale hybride**
  Supabase + Spring Boot
  en parfaite harmonie
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_coûts_et_considérations_opérationnelles&quot;&gt;Coûts et Considérations Opérationnelles&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_structure_des_coûts&quot;&gt;Structure des Coûts&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

package &quot;Coûts Mensuels Estimés&quot; {

  rectangle &quot;Phase MVP\n(0-1000 users)&quot; #LightGreen {
    [JBake (GitHub Pages): 0€]
    [Supabase: 0€]
    [Spring Boot: N/A]
    note bottom: **Total: 0€/mois**
  }

  rectangle &quot;Phase Croissance\n(1k-10k users)&quot; #LightYellow {
    [JBake (GitHub Pages): 0€]
    [Supabase: 0€]
    [Spring Boot (Cloud Run): 20-50€]
    [PostgreSQL (si séparé): 0-30€]
    note bottom: **Total: 20-80€/mois**
  }

  rectangle &quot;Phase Scale\n(10k-100k users)&quot; #LightCoral {
    [JBake (Netlify Pro): 19€]
    [Supabase Pro: 25€]
    [Spring Boot (instances multiples): 100-300€]
    [Redis Cache: 20-50€]
    [Monitoring: 20€]
    note bottom: **Total: 184-414€/mois**
  }
}

note right of &quot;Phase Scale\n(10k-100k users)&quot;
  À ce stade, les revenus
  justifient largement les coûts
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_responsabilités_opérationnelles&quot;&gt;Responsabilités Opérationnelles&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

package &quot;Qui Gère Quoi ?&quot; {

  rectangle &quot;Géré par Supabase (0 effort)&quot; #LightGreen {
    [Authentification]
    [Base de données]
    [Backups automatiques]
    [Scaling automatique]
    [Monitoring DB]
    [Sécurité DB]
  }

  rectangle &quot;Géré par GitHub (0 effort)&quot; #SkyBlue {
    [Hébergement site statique]
    [HTTPS/SSL]
    [CDN global]
    [Déploiement automatique]
  }

  rectangle &quot;À Gérer (Spring Boot)&quot; #LightCoral {
    [Déploiement application]
    [Monitoring APM]
    [Logs centralisés]
    [Scaling horizontal]
    [Mises à jour sécurité]
  }
}

note bottom of &quot;À Gérer (Spring Boot)&quot;
  **Minimisable avec :**
  • Cloud Run (serverless)
  • Kubernetes (si nécessaire)
  • Services managés (RDS, etc.)
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_conclusion_léquilibre_parfait&quot;&gt;Conclusion : L&amp;#8217;Équilibre Parfait&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;L&amp;#8217;architecture hybride Supabase + Spring Boot n&amp;#8217;est pas un compromis, c&amp;#8217;est une &lt;strong&gt;synergie&lt;/strong&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_les_principes_à_retenir&quot;&gt;Les Principes à Retenir&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startmindmap
skinparam backgroundColor #FEFEFE
* Architecture\nHybride

** Commencer Simple
***_ MVP avec Supabase
***_ 0€ de coût initial
***_ Validation rapide

** Évoluer Intelligemment
***_ Ajouter Spring Boot\nsi nécessaire
***_ Migration progressive
***_ Pas de refonte totale

** Exploiter les Forces
***_ Supabase: Simplicité
***_ Spring Boot: Puissance
***_ PostgreSQL: Source unique

** Minimiser la Complexité
***_ Pas de synchronisation
***_ Pas de duplication
***_ Architecture claire

** Optimiser les Coûts
***_ Gratuit au départ
***_ Scaling progressif
***_ ROI évident

@endmindmap&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_quand_choisir_cette_architecture&quot;&gt;Quand Choisir Cette Architecture ?&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;✅ Cette architecture est idéale si :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Vous voulez démarrer rapidement (MVP en jours, pas en mois)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Vous anticipez une croissance de la complexité métier&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Vous voulez minimiser les coûts initiaux&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Vous aimez PostgreSQL et voulez une source de vérité unique&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Vous appréciez Kotlin et les Coroutines pour le code métier&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Vous voulez éviter le vendor lock-in total&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;❌ Cette architecture n&amp;#8217;est PAS adaptée si :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Votre projet est simple et le restera (blog personnel → 100% Supabase suffit)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Vous avez déjà une stack backend établie que vous maîtrisez&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Vous préférez un monolithe traditionnel&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Vous avez besoin de .NET, Python, ou autre langage côté backend&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_vision_densemble_finale&quot;&gt;Vision d&amp;#8217;Ensemble Finale&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

package &quot;Architecture Hybride Complète&quot; {

  actor &quot;Utilisateurs&quot; as users

  rectangle &quot;Frontend (Statique)&quot; #SkyBlue {
    [JBake / GitHub Pages]
    note right: Gratuit, CDN global
  }

  rectangle &quot;Backend Simple (Supabase)&quot; #LightGreen {
    [Auth OAuth2]
    [CRUD APIs]
    [Storage]
    [Realtime]
    note right
      Gratuit jusqu&#39;à 50k users
      Zéro configuration serveur
    end note
  }

  rectangle &quot;Backend Métier (Spring Boot)&quot; #Coral {
    [Orchestration]
    [Jobs Planifiés]
    [Intégrations]
    [Transactions]
    note right
      Activé uniquement
      si nécessaire
    end note
  }

  database &quot;PostgreSQL\nSource Unique de Vérité&quot; as db #LightGray

  users --&amp;gt; [JBake / GitHub Pages]

  [JBake / GitHub Pages] --&amp;gt; [Auth OAuth2]
  [JBake / GitHub Pages] --&amp;gt; [CRUD APIs]
  [JBake / GitHub Pages] --&amp;gt; [Storage]
  [JBake / GitHub Pages] --&amp;gt; [Realtime]
  [JBake / GitHub Pages] --&amp;gt; [Orchestration]

  [Auth OAuth2] --&amp;gt; db
  [CRUD APIs] --&amp;gt; db
  [Orchestration] --&amp;gt; db
  [Jobs Planifiés] --&amp;gt; db
  [Intégrations] --&amp;gt; db
}

note bottom of db
  **Une seule base, deux consommateurs**
  • Supabase pour le simple
  • Spring Boot pour le complexe
  • Aucune synchronisation requise
end note

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_le_meilleur_des_deux_mondes&quot;&gt;Le Meilleur des Deux Mondes&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Cette architecture vous donne :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;🚀 La Vélocité de Supabase&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Démarrage en heures, pas en semaines&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Authentification OAuth2 en quelques clics&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;APIs REST générées automatiquement&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Zéro configuration de serveur&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;💪 La Puissance de Spring Boot&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Kotlin et Coroutines pour code asynchrone élégant&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Orchestration de processus métier complexes&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Jobs planifiés fiables&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Transactions ACID garanties&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Écosystème Spring complet&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;💰 L&amp;#8217;Économie Progressive&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;0€ pour démarrer et valider&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Coûts qui suivent la croissance&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Pas de sur-engineering prématuré&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;🎯 La Flexibilité Architecturale&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Migration progressive sans refonte&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Ajout de Spring Boot seulement si nécessaire&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Pas de vendor lock-in total&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Architecture évolutive&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_pour_aller_plus_loin&quot;&gt;Pour Aller Plus Loin&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_ressources_techniques&quot;&gt;Ressources Techniques&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Documentation Supabase :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://supabase.com/docs/guides/auth&quot;&gt;Guide d&amp;#8217;Authentification&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://supabase.com/docs/guides/database/postgres/row-level-security&quot;&gt;Row Level Security&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://supabase.com/docs/guides/api&quot;&gt;Auto-generated APIs&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Documentation Spring Boot :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://spring.io/guides/tutorials/spring-boot-kotlin/&quot;&gt;Spring Boot avec Kotlin&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://spring.io/blog/2019/04/12/going-reactive-with-spring-coroutines-and-kotlin-flow&quot;&gt;Coroutines et Spring&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://docs.spring.io/spring-security/reference/servlet/oauth2/resource-server/jwt.html&quot;&gt;JWT Resource Server&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Articles Complémentaires :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Sécurisation des APIs avec JWT&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Optimisation des performances PostgreSQL&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Patterns de migration progressive&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Gestion des erreurs en architecture distribuée&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_cas_dusage_réels&quot;&gt;Cas d&amp;#8217;Usage Réels&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Cette architecture hybride est utilisée avec succès dans :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;SaaS B2B&lt;/strong&gt; : Authentification Supabase, facturation Spring Boot&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Marketplaces&lt;/strong&gt; : Catalogue Supabase, transactions Spring Boot&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Plateformes de contenu&lt;/strong&gt; : Articles Supabase, analytics Spring Boot&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Outils internes&lt;/strong&gt; : CRUD Supabase, workflows Spring Boot&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_checklist_de_démarrage&quot;&gt;Checklist de Démarrage&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Phase 1 - Fondations (Semaine 1)&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist checklist&quot;&gt;
&lt;ul class=&quot;checklist&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;i class=&quot;fa fa-square-o&quot;&gt;&lt;/i&gt; Créer compte Supabase - [ ] Configurer projet PostgreSQL - [ ] Activer Auth (Google, GitHub) - [ ] Définir schéma initial - [ ] Configurer Row Level Security - [ ] Tester APIs depuis JBake&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Phase 2 - MVP (Semaine 2-3)&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist checklist&quot;&gt;
&lt;ul class=&quot;checklist&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;i class=&quot;fa fa-square-o&quot;&gt;&lt;/i&gt; Implémenter pages principales - [ ] Intégrer authentification OAuth2 - [ ] Créer formulaires CRUD - [ ] Configurer Storage pour fichiers - [ ] Déployer sur GitHub Pages - [ ] Tester en conditions réelles&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Phase 3 - Évolution (Selon besoins)&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist checklist&quot;&gt;
&lt;ul class=&quot;checklist&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;i class=&quot;fa fa-square-o&quot;&gt;&lt;/i&gt; Identifier besoins de logique complexe - [ ] Créer projet Spring Boot si nécessaire - [ ] Configurer validation JWT Supabase - [ ] Connecter à PostgreSQL Supabase - [ ] Migrer fonctionnalités complexes - [ ] Implémenter jobs planifiés - [ ] Déployer Spring Boot (Cloud Run, etc.)&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_anti_patterns_à_éviter&quot;&gt;Anti-Patterns à Éviter&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;❌ Ne pas faire :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Dupliquer les données entre Supabase et Spring Boot&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Créer deux bases PostgreSQL séparées&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Coder l&amp;#8217;authentification vous-même&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Utiliser Spring Boot pour du CRUD simple&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Sur-architecturer dès le départ&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Ignorer Row Level Security de Supabase&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;✅ Faire plutôt :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Partager une seule base PostgreSQL&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Laisser Supabase gérer l&amp;#8217;authentification&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Utiliser Spring Boot seulement pour la complexité&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Commencer simple, évoluer progressivement&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Exploiter les forces de chaque technologie&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Sécuriser avec RLS au niveau base de données&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_perspectives_dévolution&quot;&gt;Perspectives d&amp;#8217;Évolution&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_ajout_de_nouvelles_capacités&quot;&gt;Ajout de Nouvelles Capacités&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

rectangle &quot;Architecture Actuelle&quot; #SkyBlue {
  [JBake]
  [Supabase]
  [Spring Boot]
}

rectangle &quot;Évolutions Possibles&quot; #LightYellow {

  package &quot;Performance&quot; {
    [Redis Cache]
    [CDN pour Assets]
    [PostgreSQL Replicas]
  }

  package &quot;Monitoring&quot; {
    [Grafana]
    [Prometheus]
    [Sentry]
  }

  package &quot;CI/CD&quot; {
    [GitHub Actions]
    [Tests Automatisés]
    [Déploiement Continu]
  }

  package &quot;Fonctionnalités&quot; {
    [Search (ElasticSearch)]
    [Queue (RabbitMQ)]
    [Event Sourcing]
  }
}

[Spring Boot] .down.&amp;gt; [Redis Cache] : Peut ajouter
[Spring Boot] .down.&amp;gt; [Queue (RabbitMQ)] : Peut ajouter
[Spring Boot] .down.&amp;gt; [Search (ElasticSearch)] : Peut ajouter

[Supabase] .down.&amp;gt; [PostgreSQL Replicas] : Peut ajouter

note bottom
  **Architecture extensible**
  Chaque ajout est indépendant
  Pas de refonte globale nécessaire
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_scaling_horizontal&quot;&gt;Scaling Horizontal&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Lorsque votre application grandit, l&amp;#8217;architecture hybride scale naturellement :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Supabase :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Scale automatiquement jusqu&amp;#8217;à des millions d&amp;#8217;opérations&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Read replicas pour performances lecture&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Point-in-time recovery pour sécurité&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Spring Boot :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Multiple instances derrière load balancer&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Stateless design facilite le scaling horizontal&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Kubernetes pour orchestration si nécessaire&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;PostgreSQL :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Partitioning pour tables volumineuses&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Connection pooling (PgBouncer)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Sharding si vraiment nécessaire (rare)&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_témoignages_architecturaux&quot;&gt;Témoignages Architecturaux&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_startup_saas_50k_utilisateurs&quot;&gt;Startup SaaS (50k utilisateurs)&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;em&gt;&lt;em&gt;_ Nous avons démarré 100% Supabase. À 5k utilisateurs, nous avons ajouté Spring Boot uniquement pour la facturation Stripe et les rapports mensuels. Un an plus tard, 80% de nos opérations passent toujours par Supabase. Spring Boot gère seulement la partie critique. Cette séparation nous a permis de scaler sans refonte. &lt;/em&gt;_&lt;/em&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_plateforme_e_learning_10k_utilisateurs&quot;&gt;Plateforme E-learning (10k utilisateurs)&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;em&gt;&lt;em&gt;_ L&amp;#8217;authentification OAuth2 de Supabase nous a fait gagner 3 semaines de développement. Les APIs auto-générées gèrent tout notre catalogue de cours. Spring Boot ne sert que pour les certificats PDF et les emails de progression. Architecture simple, maintenable, évolutive. &lt;/em&gt;_&lt;/em&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_marketplace_b2b_3k_utilisateurs&quot;&gt;Marketplace B2B (3k utilisateurs)&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;em&gt;&lt;em&gt;_ Spring Boot gère les transactions entre acheteurs et vendeurs (critique). Supabase gère tout le reste : profils, messagerie temps réel, documents. Le fait qu&amp;#8217;ils partagent la même base PostgreSQL nous évite toute synchronisation complexe. Meilleur choix architectural que nous ayons fait. &lt;/em&gt;_&lt;/em&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_synthèse_un_paradigme_architectural_moderne&quot;&gt;Synthèse : Un Paradigme Architectural Moderne&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;L&amp;#8217;architecture hybride Supabase + Spring Boot représente un nouveau paradigme : &lt;strong&gt;la spécialisation architecturale&lt;/strong&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

rectangle &quot;Ancien Paradigme&quot; #LightCoral {
  card &quot;Tout dans le Backend&quot; {
    [Auth]
    [CRUD]
    [Logique Métier]
    [Jobs]
    [Storage]
    [Realtime]
  }
  note bottom
    Complexité maximale
    dès le jour 1
  end note
}

rectangle &quot;Nouveau Paradigme&quot; #LightGreen {
  card &quot;Supabase\n(Commodité)&quot; {
    [Auth]
    [CRUD Simple]
    [Storage]
    [Realtime]
  }

  card &quot;Spring Boot\n(Différenciation)&quot; {
    [Logique Métier]
    [Jobs]
    [Intégrations]
  }

  note bottom
    Complexité progressive
    ajoutée seulement si nécessaire
  end note
}

[Ancien Paradigme] -right-&amp;gt; [Nouveau Paradigme] : Évolution

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Le principe fondamental :&lt;/strong&gt; Ne construisez pas ce qui existe déjà sous forme de service. Concentrez-vous sur ce qui différencie votre application.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_la_règle_des_8020&quot;&gt;La Règle des 80/20&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Dans la plupart des applications :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;80% des opérations&lt;/strong&gt; sont du CRUD standard → Supabase&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;20% des opérations&lt;/strong&gt; nécessitent de la logique métier → Spring Boot&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Cette règle naturelle justifie l&amp;#8217;architecture hybride.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

package &quot;Distribution des Opérations&quot; {

  rectangle &quot;80% - Opérations Standards&quot; #LightGreen {
    [Lecture de données]
    [Création d&#39;entités]
    [Mise à jour simple]
    [Suppression]
    [Upload fichiers]
    [Authentification]

    note bottom: **Géré par Supabase**
  }

  rectangle &quot;20% - Logique Métier&quot; #Coral {
    [Calculs complexes]
    [Workflows multi-étapes]
    [Transactions critiques]
    [Intégrations tierces]
    [Jobs planifiés]

    note bottom: **Géré par Spring Boot**
  }
}

note right
  **Focus optimal :**
  Votre temps de développement
  concentré sur les 20% qui
  différencient votre produit
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_conclusion_finale&quot;&gt;Conclusion Finale&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;L&amp;#8217;architecture hybride n&amp;#8217;est pas un compromis technique, c&amp;#8217;est une &lt;strong&gt;décision stratégique&lt;/strong&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Elle vous permet de :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;✅ Démarrer rapidement avec un MVP fonctionnel&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;✅ Valider votre marché sans investissement lourd&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;✅ Évoluer progressivement quand la complexité l&amp;#8217;exige&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;✅ Maîtriser vos coûts à chaque étape&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;✅ Exploiter le meilleur de chaque technologie&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;✅ Éviter le sur-engineering prématuré&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;✅ Conserver la flexibilité pour l&amp;#8217;avenir&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Elle représente :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;🎯 &lt;strong&gt;Pragmatisme&lt;/strong&gt; : Chaque technologie où elle excelle&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;🚀 &lt;strong&gt;Vélocité&lt;/strong&gt; : Time-to-market minimal&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;💰 &lt;strong&gt;Économie&lt;/strong&gt; : Coûts alignés sur la valeur&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;🔮 &lt;strong&gt;Évolutivité&lt;/strong&gt; : Architecture qui grandit avec vous&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;🛡️ &lt;strong&gt;Robustesse&lt;/strong&gt; : Services éprouvés et fiables&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_votre_prochain_pas&quot;&gt;Votre Prochain Pas&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Si cette architecture vous parle, voici par où commencer :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Créez un compte Supabase&lt;/strong&gt; (gratuit)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Définissez votre schéma de données minimal&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Configurez l&amp;#8217;authentification OAuth2&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Créez votre première page JBake qui consomme l&amp;#8217;API&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Déployez sur GitHub Pages&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Vous aurez un MVP fonctionnel en &lt;strong&gt;quelques jours&lt;/strong&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Spring Boot viendra naturellement quand vous en aurez besoin. Pas avant.&lt;/p&gt;
&lt;/div&gt;
&lt;hr&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;L&amp;#8217;architecture hybride, c&amp;#8217;est l&amp;#8217;art de construire exactement ce qu&amp;#8217;il faut, quand il faut.&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;em&gt;Bon développement ! 🚀&lt;/em&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;hr&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;em&gt;Partagez cet article si vous pensez qu&amp;#8217;il peut aider d&amp;#8217;autres développeurs à faire les bons choix architecturaux.&lt;/em&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;preamble&quot;&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;div class=&quot;title&quot;&gt;okuma süresi : 12 minutes&lt;/div&gt;
&lt;p&gt;Supabase&amp;#8217;in basitliği ile Spring Boot&amp;#8217;un gücü arasında bir seçim yapmak yerine, ikisini birleştirmek neden olmasın? Her teknolojinin en iyi tarafını kullanan bir hibrit mimariyi keşfedin.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;dlist&quot;&gt;
&lt;dl&gt;
&lt;dt class=&quot;hdlist1&quot;&gt;tik&lt;/dt&gt;
&lt;dd&gt;
&lt;p&gt;[]&lt;/p&gt;
&lt;/dd&gt;
&lt;/dl&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_modern_mimarlık_yanlış_dilemmesi&quot;&gt;Modern Mimarlık Yanlış Dilemmesi&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Statik bir frontend kullanarak modern bir uygulama oluştururken, genellikle ikili bir seçenekle karşılaşırız:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Her şeyi Backend-as-a-Service çözümüne bağlamak&lt;/strong&gt;(Supabase, Firebase) - basit ama sınırlı&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Tam bir backend oluştur&lt;/strong&gt;(Spring Boot, Node.js) - güçlü ama karmaşık&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Bu seçim yanlış bir dilemmadır. Hibrit mimari bir üçüncü yol sunar : &lt;strong&gt;her teknolojinin iyi olduğu yerde kullanmak&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_mimari_vizyon&quot;&gt;Mimari Vizyon&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_geleneksel_mimarlık_monolitik&quot;&gt;Geleneksel Mimarlık: Monolitik&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam componentStyle rectangle

package &quot;Geleneksel Mimari&quot; {
  actor Utilisateur as user
  component &quot;Ön uç&quot; as frontend #LightBlue
  component &quot;Backend Monolitik&quot; as backend #LightCoral {
    [Authentification]
    [CRUD]
    [Logique Métier]
    [Jobs]
    [APIs Tierces]
  }
  database &quot;Veritabanı&quot; as db #LightGray

  user --&amp;gt; frontend
  frontend --&amp;gt; backend : Toutes les requêtes
  backend --&amp;gt; db
}

note right of backend
  Tout passe par le backend
  même les opérations simples

  ⚠️ Point de congestion unique
  ⚠️ Complexité dès le départ
  ⚠️ Couplage fort
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Bu yaklaşımda, hatta en basit işlemler (bir makale okuma, bir yorum oluşturma) bile backend&amp;#8217;ınızdan geçmelidir. İlk günden itibaren karmaşıklık maliyetini ödersiniz.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_baas_mimarisi_tüm_temsilci&quot;&gt;BaaS Mimarisi : Tüm Temsilci&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam componentStyle rectangle

package &quot;Pure BaaS mimarisi&quot; {
  actor Utilisateur as user
  component &quot;ön taraf&quot; as frontend #LightBlue
  cloud &quot;Supabase / Firebase&quot; as baas #LightGreen {
    [Auth]
    [Database]
    [Storage]
    [Edge Functions]
  }

  user --&amp;gt; frontend
  frontend --&amp;gt; baas : Toutes les opérations
}

note right of baas
  Développement rapide
  Pas de serveur à gérer

  ⚠️ Limité pour logique complexe
  ⚠️ Vendor lock-in
  ⚠️ Edge Functions contraintes
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Tersine, bir BaaS&amp;#8217;e her şeyi devretmek başta çekici görünebilir ama iş mantığı karmaşıklaştığında sınırları hızla gösterir.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_hibrit_mimari_sorumlulukların_ayrılması&quot;&gt;Hibrit Mimari: Sorumlulukların Ayrılması&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam componentStyle rectangle

actor Utilisateur as user #LightBlue

package &quot;Frontend Katmanı&quot; {
  component &quot;Statik site JBake&quot; as frontend #SkyBlue
}

package &quot;Basit Katman (Supabase)&quot; #LightGreen {
  component &quot;Kimlik doğrulama&quot; as auth
  component &quot;Temel CRUD&quot; as crud
  component &quot;Dosya Depolama&quot; as storage
  component &quot;gerçek zamanlı&quot; as realtime
}

package &quot;İş Katmanı (Spring Boot)&quot; #Coral {
  component &quot;Karmaşık Mantık&quot; as logic
  component &quot;Orkestrasyon&quot; as orchestration
  component &quot;Planlanmış İşler&quot; as jobs
  component &quot;Entegrasyonlar&quot; as integrations
}

database &quot;PostgreSQL Paylaşımlı&quot; as db #LightGray

user --&amp;gt; frontend

frontend --&amp;gt; auth : OAuth2, JWT
frontend --&amp;gt; crud : Articles, Profils
frontend --&amp;gt; storage : Images, Fichiers
frontend --&amp;gt; realtime : Notifications

frontend --&amp;gt; logic : Calculs, Rapports
frontend --&amp;gt; orchestration : Workflows
logic --&amp;gt; integrations : Stripe, APIs
orchestration --&amp;gt; db
jobs --&amp;gt; db

crud --&amp;gt; db
auth --&amp;gt; db

note bottom of db
  **Une seule source de vérité**
  Partagée entre Supabase et Spring Boot
end note

note right of auth
  **Gratuit jusqu&#39;à 50k users**
  Configuration en quelques clics
  OAuth2 multi-providers
end note

note right of logic
  **Activé seulement si nécessaire**
  Kotlin + Coroutines
  Transactions complexes
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Hibrit mimari, karmaşıklık ve işlemlerin doğasına göre sorumlulukları net bir şekilde ayırır.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_tasarım_i̇lkeleri&quot;&gt;Tasarım İlkeleri&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_prensip_1_basit_başla_akıllıca_geliş&quot;&gt;Prensip 1: Basit Başla, Akıllıca Geliş&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

rectangle &quot;**Aşama 1 : MVP**&quot; #LightGreen {
  component &quot;JBake + Supabase&quot; as mvp
  note right
    ✓ Développement en jours
    ✓ Coût : 0€
    ✓ Validation concept
  end note
}

rectangle &quot;Aşama 2: Büyüme&quot; #LightYellow {
  component &quot;JBake + Supabase\n+ Spring Boot (opsiyonel)&quot; as growth
  note right
    ✓ Logique métier émerge
    ✓ Premiers jobs planifiés
    ✓ Intégrations tierces
  end note
}

rectangle &quot;**Aşama 3 : Ölçek**&quot; #LightCoral {
  component &quot;Tam Mimari&quot; as scale
  note right
    ✓ Orchestration complexe
    ✓ Performances optimisées
    ✓ Cache distribué
  end note
}

mvp -down-&amp;gt; growth : Quand la complexité\nle justifie
growth -down-&amp;gt; scale : Optimisation\ncontinue
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Spring Boot&amp;#8217;a ihtiyacın yoksa onu yapmayın.&lt;/strong&gt;Supabase ile başlayın, karmaşıklık gerektirdiğinde Spring Boot ekleyin.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_prensip_2_operasyonun_doğasına_göre_ayrım&quot;&gt;Prensip 2: Operasyonun doğasına göre ayrım&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startmindmap
skinparam backgroundColor #FEFEFE
* Opérations\nApplicatives

left side

** Opérations Simples\n(Supabase)
***_ CRUD Standard
****_ Lecture
****_ Création
****_ Mise à jour
****_ Suppression
***_ Authentification
****_ Login/Logout
****_ OAuth2
****_ Gestion session
***_ Stockage
****_ Upload fichiers
****_ CDN automatique
***_ Temps Réel
****_ WebSocket
****_ Notifications

right side

** Opérations Complexes\n(Spring Boot)
***_ Logique Métier
****_ Calculs complexes
****_ Règles métier
****_ Validations avancées
***_ Orchestration
****_ Multi-services
****_ Transactions distribuées
****_ Saga patterns
***_ Tâches Planifiées
****_ Rapports périodiques
****_ Synchronisations
****_ Nettoyages
***_ Intégrations
****_ Paiements (Stripe)
****_ APIs tierces
****_ Services ML/AI

@endmindmap&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_prensip_3_tek_gerçek_kaynağı&quot;&gt;Prensip 3 : Tek Gerçek Kaynağı&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

database &quot;PostgreSQL&quot; as db #LightGray {
  package &quot;Şema: kimlik doğrulama (Supabase)&quot; #LightGreen {
    [users]
    [sessions]
    [identities]
  }

  package &quot;Şema: public (Paylaşılmış)&quot; #SkyBlue {
    [articles]
    [comments]
    [profiles]
  }

  package &quot;Şema: iş (Spring Boot)&quot; #Coral {
    [orders]
    [payments]
    [reports]
  }
}

component &quot;Supabase&quot; as supabase #LightGreen
component &quot;Spring Boot&quot; as spring #Coral

supabase -down-&amp;gt; users : Gère
supabase -down-&amp;gt; sessions : Gère
supabase -down-&amp;gt; articles : Accède
supabase -down-&amp;gt; comments : Accède
supabase -down-&amp;gt; profiles : Accède

spring -down-&amp;gt; articles : Accède
spring -down-&amp;gt; profiles : Accède
spring -down-&amp;gt; orders : Gère
spring -down-&amp;gt; payments : Gère
spring -down-&amp;gt; reports : Gère

note right of db
  **Avantages :**
  • Pas de synchronisation complexe
  • JOINs possibles entre tables
  • Cohérence garantie
  • Migrations unifiées
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Aynı PostgreSQL örneğini paylaşarak, Supabase ve Spring Boot, karmaşık senkronizasyon gerektirmeden aynı veriler üzerinde çalışır.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_akış_orkestrasyonu&quot;&gt;akış orkestrasyonu&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_akış_1_merkezi_kimlik_doğrulama&quot;&gt;Akış 1: Merkezi Kimlik Doğrulama&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
autonumber

actor &quot;Kullanıcı&quot; as user
participant &quot;JBake&quot; as jbake
participant &quot;Supabase Auth&quot; as auth
participant &quot;Spring Boot&quot; as spring
database &quot;PostgreSQL&quot; as db

== Authentification ==
user -&amp;gt; jbake : Clique &quot;Giriş yap&quot;
jbake -&amp;gt; auth : Redirect OAuth2 (Google/GitHub)
auth -&amp;gt; user : Consent screen
user -&amp;gt; auth : Autorise
auth -&amp;gt; auth : Génère JWT
auth -&amp;gt; jbake : Retourne JWT + Refresh Token
jbake -&amp;gt; jbake : Stocke tokens (sessionStorage)

== Accès aux Ressources ==
group Opération Simple (CRUD)
  user -&amp;gt; jbake : Crée un article
  jbake -&amp;gt; db : POST avec JWT
  note right: Supabase Row Level Security\nvérifie le JWT automatiquement
  db -&amp;gt; jbake : Article créé
end

group Opération Complexe (Métier)
  user -&amp;gt; jbake : Génère un rapport
  jbake -&amp;gt; spring : POST /api/reports\navec JWT
  spring -&amp;gt; spring : Valide JWT Supabase
  spring -&amp;gt; spring : Extrait claims (user_id, roles)
  spring -&amp;gt; db : Requêtes complexes
  spring -&amp;gt; jbake : Rapport généré
end

note over auth, spring
  **Le JWT est universel**
  Valide par Supabase ET Spring Boot
  Pas de double authentification
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Anahtar nokta&lt;/strong&gt;: Tek bir kimlik doğrulama süreci, tek bir JWT, her yerde kullanılabilir.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_flux_2_karmaşık_bir_i̇ş_sürecinin_koordinasyonu&quot;&gt;Flux 2 : Karmaşık Bir İş Sürecinin Koordinasyonu&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
autonumber

actor &quot;Müşteri&quot; as user
participant &quot;JBake&quot; as jbake
participant &quot;Spring Boot&quot; as spring
participant &quot;Supabase veritabanı&quot; as supadb
participant &quot;Stripe API&quot; as stripe
participant &quot;Envanter Servisi&quot; as inventory
participant &quot;E-posta hizmeti&quot; as email
database &quot;PostgreSQL&quot; as db

user -&amp;gt; jbake : Passe commande
jbake -&amp;gt; spring : POST /api/orders/create

== Orchestration Spring Boot ==
spring -&amp;gt; db : BEGIN TRANSACTION

par Vérifications Parallèles
  spring -&amp;gt; inventory : Vérifier stock
  inventory -&amp;gt; spring : Stock OK
else
  spring -&amp;gt; db : Vérifier profil client
  db -&amp;gt; spring : Client vérifié
end

spring -&amp;gt; stripe : Créer Payment Intent
stripe -&amp;gt; spring : Intent créé (ID: pi_xxx)

spring -&amp;gt; db : Créer Order (status: PENDING)
db -&amp;gt; spring : Order créé

spring -&amp;gt; stripe : Confirmer paiement
stripe -&amp;gt; spring : Paiement confirmé

spring -&amp;gt; db : Update Order (status: PAID)
spring -&amp;gt; inventory : Décrémenter stock
spring -&amp;gt; db : COMMIT TRANSACTION

par Notifications Asynchrones
  spring -&amp;gt; email : Email confirmation
else
  spring -&amp;gt; supadb : Insert notification
  note right: Notification temps réel\nvia Supabase Realtime
end

spring -&amp;gt; jbake : Order confirmé
jbake -&amp;gt; user : Affiche confirmation

note over spring
  **Responsabilités Spring Boot :**
  • Transaction ACID
  • Orchestration multi-services
  • Rollback automatique si erreur
  • Gestion des cas limites
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Spring Boot&amp;#8217;un getirdiği şey&lt;/strong&gt;: Güvenilir, birden fazla sistemi içeren karmaşık süreçlerin orkestrasyonu, işlem garantisiyle.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_flux_3_zamanlanmış_i̇şler_ve_senkronizasyonlar&quot;&gt;Flux 3: Zamanlanmış İşler ve Senkronizasyonlar&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

participant &quot;Zamanlayıcı
(Spring Boot)&quot; as scheduler
participant &quot;Rapor servisi&quot; as report
participant &quot;PostgreSQL&quot; as db
participant &quot;Dış API&quot; as api
participant &quot;E-posta hizmeti&quot; as email
participant &quot;Supabase Depolama&quot; as storage

== Job Quotidien : 2h00 ==
activate scheduler
scheduler -&amp;gt; report : Déclenche génération rapport

activate report
report -&amp;gt; db : Récupère données\ndes dernières 24h
db -&amp;gt; report : Dataset

report -&amp;gt; report : Calculs &amp;amp; Agrégations
report -&amp;gt; report : Génération PDF

report -&amp;gt; storage : Upload PDF
storage -&amp;gt; report : URL publique

report -&amp;gt; email : Envoie aux admins\navec lien PDF
deactivate report

== Job Hebdomadaire : Dimanche 3h00 ==
scheduler -&amp;gt; report : Synchronisation externe

activate report
report -&amp;gt; api : Fetch données externes
api -&amp;gt; report : Nouvelles données

report -&amp;gt; db : Mise à jour tables
report -&amp;gt; db : Nettoyage données obsolètes
deactivate report

== Job Mensuel : 1er du mois ==
scheduler -&amp;gt; report : Facturation

activate report
report -&amp;gt; db : Liste clients actifs
report -&amp;gt; report : Calcul montants
report -&amp;gt; api : Génération factures (Stripe)
report -&amp;gt; email : Envoi factures
deactivate report

deactivate scheduler

note right of scheduler
  **Impossible avec Supabase seul**
  Edge Functions non adaptées
  pour jobs longs et récurrents
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Spring Boot&amp;#8217;un sunduğu&lt;/strong&gt;: Güvenilir zamanlanmış işler, durum yönetimi, otomatik yeniden deneme ve garanti yürütme.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_karar_matrisi&quot;&gt;Karar Matrisi&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_supabasei_ne_zaman_kullanmalı&quot;&gt;Supabase&amp;#8217;i ne zaman kullanmalı?&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

start

:Nouvelle fonctionnalité à implémenter;

if (CRUD simple ?) then (oui)
  :✅ **Supabase**;
  stop
else (non)
  if (Authentification ?) then (oui)
    :✅ **Supabase Auth**;
    stop
  else (non)
    if (Upload fichiers ?) then (oui)
      :✅ **Supabase Storage**;
      stop
    else (non)
      if (Temps réel ?) then (oui)
        :✅ **Supabase Realtime**;
        stop
      else (non)
        if (Row Level Security\nsuffisante ?) then (oui)
          :✅ **Supabase + Policies**;
          stop
        else (non)
          :⚠️ **Considérer Spring Boot**;
          #Coral:Passer à l&#39;arbre\nde décision Spring Boot;
          stop
        endif
      endif
    endif
  endif
endif

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_spring_boot_kullanımı_ne_zaman&quot;&gt;Spring Boot Kullanımı Ne Zaman?&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

start

:Nouvelle fonctionnalité complexe;

if (Orchestration\nmulti-services ?) then (oui)
  :✅ **Spring Boot**;
  stop
else (non)
  if (Transaction ACID\ncritique ?) then (oui)
    :✅ **Spring Boot**;
    stop
  else (non)
    if (Job planifié ?) then (oui)
      :✅ **Spring Boot Scheduler**;
      stop
    else (non)
      if (Intégration API\ntierce complexe ?) then (oui)
        :✅ **Spring Boot**;
        stop
      else (non)
        if (Calculs lourds\n&amp;gt; 10 secondes ?) then (oui)
          :✅ **Spring Boot**;
          stop
        else (non)
          if (Cache distribué\nnécessaire ?) then (oui)
            :✅ **Spring Boot + Redis**;
            stop
          else (non)
            :⚠️ **Probablement Supabase**;
            #LightGreen:Revenir à l&#39;arbre\nde décision Supabase;
            stop
          endif
        endif
      endif
    endif
  endif
endif

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_proje_tipine_göre_mimari_örnekleri&quot;&gt;Proje tipine göre mimari örnekleri&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_blog_portföy&quot;&gt;Blog / Portföy&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam componentStyle rectangle

package &quot;Kişisel Blog - %95 Supabase&quot; {
  component &quot;JBake&quot; as jbake #SkyBlue

  package &quot;Supabase (Ücretsiz)&quot; #LightGreen {
    [Auth: OAuth2 Google]
    [Articles (CRUD)]
    [Commentaires]
    [Images (Storage)]
    [Notifications Realtime]
  }

  package &quot;Spring Boot (Opsiyonel)&quot; #LightCoral {
    [Newsletter Mensuelle]
    note bottom: Job planifié uniquement
  }

  database &quot;PostgreSQL&quot; as db

  jbake --&amp;gt; [Auth: OAuth2 Google]
  jbake --&amp;gt; [Articles (CRUD)]
  jbake --&amp;gt; [Commentaires]
  jbake --&amp;gt; [Images (Storage)]
  jbake --&amp;gt; [Notifications Realtime]

  [Articles (CRUD)] --&amp;gt; db
  [Commentaires] --&amp;gt; db
  [Newsletter Mensuelle] --&amp;gt; db
}

note bottom of &quot;Spring Boot (Opsiyonel)&quot;
  **Spring Boot pas obligatoire**
  Newsletter peut être gérée
  par un service tiers (Mailchimp)
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Karar&lt;/strong&gt;: %100 Supabase fazlasıyla yeterli.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_saas_uygulaması&quot;&gt;SaaS uygulaması&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam componentStyle rectangle

package &quot;SaaS Uygulaması - Hibrit Mimari&quot; {
  component &quot;JBake / React&quot; as frontend #SkyBlue

  package &quot;Supabase&quot; #LightGreen {
    [Auth Multi-tenant]
    [Profils Utilisateurs]
    [Données Simples]
    [Storage Documents]
  }

  package &quot;Spring Boot&quot; #Coral {
    [Facturation (Stripe)]
    [Analytics Avancées]
    [Rapports Mensuels]
    [Quotas &amp;amp; Limites]
    [Webhooks Stripe]
  }

  cloud &quot;Dış Hizmetler&quot; {
    [Stripe API]
    [SendGrid Email]
  }

  database &quot;PostgreSQL Paylaşılmış&quot; as db

  frontend --&amp;gt; [Auth Multi-tenant]
  frontend --&amp;gt; [Profils Utilisateurs]
  frontend --&amp;gt; [Données Simples]
  frontend --&amp;gt; [Facturation (Stripe)]
  frontend --&amp;gt; [Analytics Avancées]

  [Auth Multi-tenant] --&amp;gt; db
  [Profils Utilisateurs] --&amp;gt; db
  [Données Simples] --&amp;gt; db

  [Facturation (Stripe)] --&amp;gt; db
  [Facturation (Stripe)] --&amp;gt; [Stripe API]
  [Analytics Avancées] --&amp;gt; db
  [Rapports Mensuels] --&amp;gt; db
  [Rapports Mensuels] --&amp;gt; [SendGrid Email]
  [Webhooks Stripe] ..&amp;gt; [Stripe API] : Écoute
}

note right of &quot;Spring Boot&quot;
  **Nécessaire pour :**
  • Gestion abonnements
  • Facturation récurrente
  • Quotas dynamiques
  • Analytics complexes
  • Webhooks fiables
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;karar&lt;/strong&gt;: Hibrit mimari gereklidir. Supabase temel işlevler için, Spring Boot kritik bölüm (ödeme, faturalama) için.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_e_ticaret&quot;&gt;e-ticaret&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE
skinparam componentStyle rectangle

package &quot;e-ticaret - %70 Spring Boot&quot; {
  component &quot;Mağaza vitrini (JBake/React)&quot; as frontend #SkyBlue

  package &quot;Supabase&quot; #LightGreen {
    [Auth Clients]
    [Catalogue Produits\n(lecture seule)]
    [Images Produits]
  }

  package &quot;Spring Boot (Cœur Métier)&quot; #Coral {
    [Gestion Commandes]
    [Paiements Stripe]
    [Gestion Stock]
    [Calcul Frais Port]
    [Génération Factures]
    [Synchronisation ERP]
    [Emails Transactionnels]
  }

  cloud &quot;Intégrations&quot; {
    [Stripe]
    [Transporteur API]
    [ERP Externe]
  }

  database &quot;PostgreSQL&quot; as db

  frontend --&amp;gt; [Auth Clients]
  frontend --&amp;gt; [Catalogue Produits\n(lecture seule)]
  frontend --&amp;gt; [Gestion Commandes]

  [Auth Clients] --&amp;gt; db
  [Catalogue Produits\n(lecture seule)] --&amp;gt; db

  [Gestion Commandes] --&amp;gt; db
  [Paiements Stripe] --&amp;gt; [Stripe]
  [Gestion Stock] --&amp;gt; db
  [Calcul Frais Port] --&amp;gt; [Transporteur API]
  [Génération Factures] --&amp;gt; db
  [Synchronisation ERP] --&amp;gt; [ERP Externe]
  [Synchronisation ERP] --&amp;gt; db
}

note right of &quot;Spring Boot (Cœur Métier)&quot;
  **Spring Boot indispensable :**
  • Transactions critiques
  • Orchestration complexe
  • Intégrations multiples
  • Conformité légale
  • Jobs de synchronisation
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Verdict&lt;/strong&gt; : Spring Boot indispensable. Supabase pour auth et catalogue uniquement.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_stratégie_de_migration_progressive&quot;&gt;Stratégie de Migration Progressive&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

|Semaine 1-2|
start
:Créer projet Supabase;
:Configurer Auth (Google, GitHub);
:Définir schéma PostgreSQL initial;
:Implémenter CRUD de base sur JBake;
:Déployer MVP sur GitHub Pages;
note right
  **Livrable :** Application fonctionnelle
  **Coût :** 0€
  **Temps :** 1-2 semaines
end note

|Semaine 3-4|
:Observer utilisation réelle;
:Identifier limitations;

|Décision|
if (Logique complexe\némerge ?) then (non)
  |Supabase|
  :Continuer avec Supabase seul;
  :Ajouter Edge Functions si besoin;
  stop
else (oui)
  |Spring Boot|
  :Créer projet Spring Boot;
  :Configurer validation JWT Supabase;
  :Migrer logique complexe vers Spring Boot;
  note right
    **Migration sélective**
    Seulement ce qui est complexe
  end note
endif

|Semaines suivantes|
:Déployer Spring Boot (Cloud Run, EC2);
:Connecter à PostgreSQL Supabase;
:Implémenter premiers jobs planifiés;
:Intégrer APIs tierces;

stop

note right
  **Architecture finale hybride**
  Supabase + Spring Boot
  en parfaite harmonie
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_coûts_et_considérations_opérationnelles&quot;&gt;Coûts et Considérations Opérationnelles&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_maliyet_yapısı&quot;&gt;Maliyet Yapısı&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

package &quot;Tahmini Aylık Maliyetler&quot; {

  rectangle &quot;Phase MVP\n(0-1000 users)&quot; #LightGreen {
    [JBake (GitHub Pages): 0€]
    [Supabase: 0€]
    [Spring Boot: N/A]
    note bottom: **Total: 0€/mois**
  }

  rectangle &quot;Phase Croissance\n(1k-10k users)&quot; #LightYellow {
    [JBake (GitHub Pages): 0€]
    [Supabase: 0€]
    [Spring Boot (Cloud Run): 20-50€]
    [PostgreSQL (si séparé): 0-30€]
    note bottom: **Total: 20-80€/mois**
  }

  rectangle &quot;Phase Scale\n(10k-100k users)&quot; #LightCoral {
    [JBake (Netlify Pro): 19€]
    [Supabase Pro: 25€]
    [Spring Boot (instances multiples): 100-300€]
    [Redis Cache: 20-50€]
    [Monitoring: 20€]
    note bottom: **Total: 184-414€/mois**
  }
}

note right of &quot;Phase Scale\n(10k-100k users)&quot;
  À ce stade, les revenus
  justifient largement les coûts
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_operasyonel_sorumluluklar&quot;&gt;Operasyonel sorumluluklar&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

package &quot;Kim Neyi Yönetiyor?&quot; {

  rectangle &quot;Supabase tarafından yönetiliyor (0 çaba)&quot; #LightGreen {
    [Authentification]
    [Base de données]
    [Backups automatiques]
    [Scaling automatique]
    [Monitoring DB]
    [Sécurité DB]
  }

  rectangle &quot;Géré par GitHub (0 effort)&quot; #SkyBlue {
    [Hébergement site statique]
    [HTTPS/SSL]
    [CDN global]
    [Déploiement automatique]
  }

  rectangle &quot;À Gérer (Spring Boot)&quot; #LightCoral {
    [Déploiement application]
    [Monitoring APM]
    [Logs centralisés]
    [Scaling horizontal]
    [Mises à jour sécurité]
  }
}

note bottom of &quot;À Gérer (Spring Boot)&quot;
  **Minimisable avec :**
  • Cloud Run (serverless)
  • Kubernetes (si nécessaire)
  • Services managés (RDS, etc.)
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_conclusion_léquilibre_parfait&quot;&gt;Conclusion : L&amp;#8217;Équilibre Parfait&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;L&amp;#8217;architecture hybride Supabase + Spring Boot n&amp;#8217;est pas un compromis, c&amp;#8217;est une &lt;strong&gt;synergie&lt;/strong&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_hatırlanması_gereken_i̇lkeler&quot;&gt;Hatırlanması Gereken İlkeler&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startmindmap
skinparam backgroundColor #FEFEFE
* Architecture\nHybride

** Commencer Simple
***_ MVP avec Supabase
***_ 0€ de coût initial
***_ Validation rapide

** Évoluer Intelligemment
***_ Ajouter Spring Boot\nsi nécessaire
***_ Migration progressive
***_ Pas de refonte totale

** Exploiter les Forces
***_ Supabase: Simplicité
***_ Spring Boot: Puissance
***_ PostgreSQL: Source unique

** Minimiser la Complexité
***_ Pas de synchronisation
***_ Pas de duplication
***_ Architecture claire

** Optimiser les Coûts
***_ Gratuit au départ
***_ Scaling progressif
***_ ROI évident

@endmindmap&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_bu_mimariyi_ne_zaman_tercih_etmelisiniz&quot;&gt;Bu mimariyi ne zaman tercih etmelisiniz?&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;✅ Cette architecture est idéale si :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Vous voulez démarrer rapidement (MVP en jours, pas en mois)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Vous anticipez une croissance de la complexité métier&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Vous voulez minimiser les coûts initiaux&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;PostgreSQL&amp;#8217;i seviyorsun ve tek bir gerçeklik kaynağı istersin.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;İş kodları için Kotlin ve Coroutine&amp;#8217;leri seviyorsunuz&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Vous voulez éviter le vendor lock-in total&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;❌ Bu mimari uygun değilse:&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Votre projet est simple et le restera (blog personnel → 100% Supabase suffit)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Zaten hakim olduğunuz, kurulu bir backend stack&amp;#8217;iniz var.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Vous préférez un monolithe traditionnel&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Vous avez besoin de .NET, Python, ou autre langage côté backend&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_vision_densemble_finale&quot;&gt;Vision d&amp;#8217;Ensemble Finale&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

package &quot;Architecture Hybride Complète&quot; {

  actor &quot;Utilisateurs&quot; as users

  rectangle &quot;Frontend (Statique)&quot; #SkyBlue {
    [JBake / GitHub Pages]
    note right: Gratuit, CDN global
  }

  rectangle &quot;Backend Simple (Supabase)&quot; #LightGreen {
    [Auth OAuth2]
    [CRUD APIs]
    [Storage]
    [Realtime]
    note right
      Gratuit jusqu&#39;à 50k users
      Zéro configuration serveur
    end note
  }

  rectangle &quot;Backend Métier (Spring Boot)&quot; #Coral {
    [Orchestration]
    [Jobs Planifiés]
    [Intégrations]
    [Transactions]
    note right
      Activé uniquement
      si nécessaire
    end note
  }

  database &quot;PostgreSQL\nSource Unique de Vérité&quot; as db #LightGray

  users --&amp;gt; [JBake / GitHub Pages]

  [JBake / GitHub Pages] --&amp;gt; [Auth OAuth2]
  [JBake / GitHub Pages] --&amp;gt; [CRUD APIs]
  [JBake / GitHub Pages] --&amp;gt; [Storage]
  [JBake / GitHub Pages] --&amp;gt; [Realtime]
  [JBake / GitHub Pages] --&amp;gt; [Orchestration]

  [Auth OAuth2] --&amp;gt; db
  [CRUD APIs] --&amp;gt; db
  [Orchestration] --&amp;gt; db
  [Jobs Planifiés] --&amp;gt; db
  [Intégrations] --&amp;gt; db
}

note bottom of db
  **Une seule base, deux consommateurs**
  • Supabase pour le simple
  • Spring Boot pour le complexe
  • Aucune synchronisation requise
end note

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_le_meilleur_des_deux_mondes&quot;&gt;Le Meilleur des Deux Mondes&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Cette architecture vous donne :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;🚀 La Vélocité de Supabase&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Démarrage en heures, pas en semaines&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Authentification OAuth2 en quelques clics&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;APIs REST générées automatiquement&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Zéro configuration de serveur&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;💪 La Puissance de Spring Boot&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Kotlin et Coroutines pour code asynchrone élégant&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Orchestration de processus métier complexes&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Jobs planifiés fiables&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Transactions ACID garanties&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Écosystème Spring complet&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;💰 L&amp;#8217;Économie Progressive&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;0€ pour démarrer et valider&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Coûts qui suivent la croissance&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Pas de sur-engineering prématuré&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;🎯 La Flexibilité Architecturale&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Migration progressive sans refonte&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Ajout de Spring Boot seulement si nécessaire&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Pas de vendor lock-in total&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Architecture évolutive&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_pour_aller_plus_loin&quot;&gt;Pour Aller Plus Loin&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_ressources_techniques&quot;&gt;Ressources Techniques&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Documentation Supabase :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://supabase.com/docs/guides/auth&quot;&gt;Guide d&amp;#8217;Authentification&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://supabase.com/docs/guides/database/postgres/row-level-security&quot;&gt;Row Level Security&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://supabase.com/docs/guides/api&quot;&gt;Auto-generated APIs&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Documentation Spring Boot :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://spring.io/guides/tutorials/spring-boot-kotlin/&quot;&gt;Spring Boot avec Kotlin&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://spring.io/blog/2019/04/12/going-reactive-with-spring-coroutines-and-kotlin-flow&quot;&gt;Coroutines et Spring&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://docs.spring.io/spring-security/reference/servlet/oauth2/resource-server/jwt.html&quot;&gt;JWT Resource Server&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Articles Complémentaires :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Sécurisation des APIs avec JWT&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Optimisation des performances PostgreSQL&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Patterns de migration progressive&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Gestion des erreurs en architecture distribuée&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_cas_dusage_réels&quot;&gt;Cas d&amp;#8217;Usage Réels&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Cette architecture hybride est utilisée avec succès dans :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;SaaS B2B&lt;/strong&gt; : Authentification Supabase, facturation Spring Boot&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Marketplaces&lt;/strong&gt; : Catalogue Supabase, transactions Spring Boot&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Plateformes de contenu&lt;/strong&gt; : Articles Supabase, analytics Spring Boot&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Outils internes&lt;/strong&gt; : CRUD Supabase, workflows Spring Boot&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_checklist_de_démarrage&quot;&gt;Checklist de Démarrage&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Phase 1 - Fondations (Semaine 1)&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist checklist&quot;&gt;
&lt;ul class=&quot;checklist&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;i class=&quot;fa fa-square-o&quot;&gt;&lt;/i&gt; Créer compte Supabase - [ ] Configurer projet PostgreSQL - [ ] Activer Auth (Google, GitHub) - [ ] Définir schéma initial - [ ] Configurer Row Level Security - [ ] Tester APIs depuis JBake&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Phase 2 - MVP (Semaine 2-3)&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist checklist&quot;&gt;
&lt;ul class=&quot;checklist&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;i class=&quot;fa fa-square-o&quot;&gt;&lt;/i&gt; Implémenter pages principales - [ ] Intégrer authentification OAuth2 - [ ] Créer formulaires CRUD - [ ] Configurer Storage pour fichiers - [ ] Déployer sur GitHub Pages - [ ] Tester en conditions réelles&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Phase 3 - Évolution (Selon besoins)&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist checklist&quot;&gt;
&lt;ul class=&quot;checklist&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;i class=&quot;fa fa-square-o&quot;&gt;&lt;/i&gt; Identifier besoins de logique complexe - [ ] Créer projet Spring Boot si nécessaire - [ ] Configurer validation JWT Supabase - [ ] Connecter à PostgreSQL Supabase - [ ] Migrer fonctionnalités complexes - [ ] Implémenter jobs planifiés - [ ] Déployer Spring Boot (Cloud Run, etc.)&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_anti_patterns_à_éviter&quot;&gt;Anti-Patterns à Éviter&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;❌ Ne pas faire :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Dupliquer les données entre Supabase et Spring Boot&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Créer deux bases PostgreSQL séparées&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Coder l&amp;#8217;authentification vous-même&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Utiliser Spring Boot pour du CRUD simple&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Sur-architecturer dès le départ&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Ignorer Row Level Security de Supabase&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;✅ Faire plutôt :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Partager une seule base PostgreSQL&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Laisser Supabase gérer l&amp;#8217;authentification&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Utiliser Spring Boot seulement pour la complexité&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Commencer simple, évoluer progressivement&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Exploiter les forces de chaque technologie&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Sécuriser avec RLS au niveau base de données&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_perspectives_dévolution&quot;&gt;Perspectives d&amp;#8217;Évolution&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_ajout_de_nouvelles_capacités&quot;&gt;Ajout de Nouvelles Capacités&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

rectangle &quot;Architecture Actuelle&quot; #SkyBlue {
  [JBake]
  [Supabase]
  [Spring Boot]
}

rectangle &quot;Évolutions Possibles&quot; #LightYellow {

  package &quot;Performance&quot; {
    [Redis Cache]
    [CDN pour Assets]
    [PostgreSQL Replicas]
  }

  package &quot;Monitoring&quot; {
    [Grafana]
    [Prometheus]
    [Sentry]
  }

  package &quot;CI/CD&quot; {
    [GitHub Actions]
    [Tests Automatisés]
    [Déploiement Continu]
  }

  package &quot;Fonctionnalités&quot; {
    [Search (ElasticSearch)]
    [Queue (RabbitMQ)]
    [Event Sourcing]
  }
}

[Spring Boot] .down.&amp;gt; [Redis Cache] : Peut ajouter
[Spring Boot] .down.&amp;gt; [Queue (RabbitMQ)] : Peut ajouter
[Spring Boot] .down.&amp;gt; [Search (ElasticSearch)] : Peut ajouter

[Supabase] .down.&amp;gt; [PostgreSQL Replicas] : Peut ajouter

note bottom
  **Architecture extensible**
  Chaque ajout est indépendant
  Pas de refonte globale nécessaire
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_scaling_horizontal&quot;&gt;Scaling Horizontal&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Lorsque votre application grandit, l&amp;#8217;architecture hybride scale naturellement :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Supabase :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Scale automatiquement jusqu&amp;#8217;à des millions d&amp;#8217;opérations&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Read replicas pour performances lecture&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Point-in-time recovery pour sécurité&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Spring Boot :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Multiple instances derrière load balancer&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Stateless design facilite le scaling horizontal&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Kubernetes pour orchestration si nécessaire&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;PostgreSQL :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Partitioning pour tables volumineuses&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Connection pooling (PgBouncer)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Sharding si vraiment nécessaire (rare)&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_témoignages_architecturaux&quot;&gt;Témoignages Architecturaux&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_startup_saas_50k_utilisateurs&quot;&gt;Startup SaaS (50k utilisateurs)&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;em&gt;&lt;em&gt;_ Nous avons démarré 100% Supabase. À 5k utilisateurs, nous avons ajouté Spring Boot uniquement pour la facturation Stripe et les rapports mensuels. Un an plus tard, 80% de nos opérations passent toujours par Supabase. Spring Boot gère seulement la partie critique. Cette séparation nous a permis de scaler sans refonte. &lt;/em&gt;_&lt;/em&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_plateforme_e_learning_10k_utilisateurs&quot;&gt;Plateforme E-learning (10k utilisateurs)&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;em&gt;&lt;em&gt;_ L&amp;#8217;authentification OAuth2 de Supabase nous a fait gagner 3 semaines de développement. Les APIs auto-générées gèrent tout notre catalogue de cours. Spring Boot ne sert que pour les certificats PDF et les emails de progression. Architecture simple, maintenable, évolutive. &lt;/em&gt;_&lt;/em&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_marketplace_b2b_3k_utilisateurs&quot;&gt;Marketplace B2B (3k utilisateurs)&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;em&gt;&lt;em&gt;_ Spring Boot gère les transactions entre acheteurs et vendeurs (critique). Supabase gère tout le reste : profils, messagerie temps réel, documents. Le fait qu&amp;#8217;ils partagent la même base PostgreSQL nous évite toute synchronisation complexe. Meilleur choix architectural que nous ayons fait. &lt;/em&gt;_&lt;/em&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_synthèse_un_paradigme_architectural_moderne&quot;&gt;Synthèse : Un Paradigme Architectural Moderne&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;L&amp;#8217;architecture hybride Supabase + Spring Boot représente un nouveau paradigme : &lt;strong&gt;la spécialisation architecturale&lt;/strong&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

rectangle &quot;Ancien Paradigme&quot; #LightCoral {
  card &quot;Tout dans le Backend&quot; {
    [Auth]
    [CRUD]
    [Logique Métier]
    [Jobs]
    [Storage]
    [Realtime]
  }
  note bottom
    Complexité maximale
    dès le jour 1
  end note
}

rectangle &quot;Nouveau Paradigme&quot; #LightGreen {
  card &quot;Supabase\n(Commodité)&quot; {
    [Auth]
    [CRUD Simple]
    [Storage]
    [Realtime]
  }

  card &quot;Spring Boot\n(Différenciation)&quot; {
    [Logique Métier]
    [Jobs]
    [Intégrations]
  }

  note bottom
    Complexité progressive
    ajoutée seulement si nécessaire
  end note
}

[Ancien Paradigme] -right-&amp;gt; [Nouveau Paradigme] : Évolution

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Le principe fondamental :&lt;/strong&gt; Ne construisez pas ce qui existe déjà sous forme de service. Concentrez-vous sur ce qui différencie votre application.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_la_règle_des_8020&quot;&gt;La Règle des 80/20&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Dans la plupart des applications :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;80% des opérations&lt;/strong&gt; sont du CRUD standard → Supabase&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;20% des opérations&lt;/strong&gt; nécessitent de la logique métier → Spring Boot&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Cette règle naturelle justifie l&amp;#8217;architecture hybride.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam backgroundColor #FEFEFE

package &quot;Distribution des Opérations&quot; {

  rectangle &quot;80% - Opérations Standards&quot; #LightGreen {
    [Lecture de données]
    [Création d&#39;entités]
    [Mise à jour simple]
    [Suppression]
    [Upload fichiers]
    [Authentification]

    note bottom: **Géré par Supabase**
  }

  rectangle &quot;20% - Logique Métier&quot; #Coral {
    [Calculs complexes]
    [Workflows multi-étapes]
    [Transactions critiques]
    [Intégrations tierces]
    [Jobs planifiés]

    note bottom: **Géré par Spring Boot**
  }
}

note right
  **Focus optimal :**
  Votre temps de développement
  concentré sur les 20% qui
  différencient votre produit
end note
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_conclusion_finale&quot;&gt;Conclusion Finale&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;L&amp;#8217;architecture hybride n&amp;#8217;est pas un compromis technique, c&amp;#8217;est une &lt;strong&gt;décision stratégique&lt;/strong&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Elle vous permet de :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;✅ Démarrer rapidement avec un MVP fonctionnel&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;✅ Valider votre marché sans investissement lourd&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;✅ Évoluer progressivement quand la complexité l&amp;#8217;exige&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;✅ Maîtriser vos coûts à chaque étape&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;✅ Exploiter le meilleur de chaque technologie&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;✅ Éviter le sur-engineering prématuré&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;✅ Conserver la flexibilité pour l&amp;#8217;avenir&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Elle représente :&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;🎯 &lt;strong&gt;Pragmatisme&lt;/strong&gt; : Chaque technologie où elle excelle&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;🚀 &lt;strong&gt;Vélocité&lt;/strong&gt; : Time-to-market minimal&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;💰 &lt;strong&gt;Économie&lt;/strong&gt; : Coûts alignés sur la valeur&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;🔮 &lt;strong&gt;Évolutivité&lt;/strong&gt; : Architecture qui grandit avec vous&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;🛡️ &lt;strong&gt;Robustesse&lt;/strong&gt; : Services éprouvés et fiables&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_votre_prochain_pas&quot;&gt;Votre Prochain Pas&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Si cette architecture vous parle, voici par où commencer :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Créez un compte Supabase&lt;/strong&gt; (gratuit)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Définissez votre schéma de données minimal&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Configurez l&amp;#8217;authentification OAuth2&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Créez votre première page JBake qui consomme l&amp;#8217;API&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Déployez sur GitHub Pages&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Vous aurez un MVP fonctionnel en &lt;strong&gt;quelques jours&lt;/strong&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Spring Boot viendra naturellement quand vous en aurez besoin. Pas avant.&lt;/p&gt;
&lt;/div&gt;
&lt;hr&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;L&amp;#8217;architecture hybride, c&amp;#8217;est l&amp;#8217;art de construire exactement ce qu&amp;#8217;il faut, quand il faut.&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;em&gt;Bon développement ! 🚀&lt;/em&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;hr&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;em&gt;Partagez cet article si vous pensez qu&amp;#8217;il peut aider d&amp;#8217;autres développeurs à faire les bons choix architecturaux.&lt;/em&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

