&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_giriş&quot;&gt;Giriş&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Statik bir sitenin uluslararasılaştırılması (i18n) ilk bakışta karmaşık görünebilir, ancak JBake, Thymeleaf ile birleştirildiğinde çok dilli bir site oluşturmak için şık çözümler sunar. Bu makalede, blogumda i18n&amp;#8217;i nasıl kurduğumu, hem şablonlamayı hem de birden fazla dildeki makaleleri yönetmeyi kapsayarak göstereceğim.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_kullanım_durumu_diyagramı_use_case&quot;&gt;Kullanım durumu diyagramı (Use Case)&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
left to right direction
skinparam packageStyle rectangle

actor &quot;Yazar&quot; as author
actor &quot;FR Okuyucu&quot; as reader_fr
actor &quot;Okuyucu EN&quot; as reader_en

rectangle &quot;Çok dilli JBake sitesi&quot; {
  usecase &quot;FR makale yaz&quot; as UC1
  usecase &quot;Makale yaz EN&quot; as UC2
  usecase &quot;i18n mesajlarını yapılandır&quot; as UC3
  usecase &quot;Site oluştur&quot; as UC4
  usecase &quot;FR makalesini oku&quot; as UC5
  usecase &quot;Makaleyi oku EN&quot; as UC6
  usecase &quot;Dil değiştir&quot; as UC7
  usecase &quot;Kullanılabilir çevirileri gör&quot; as UC8
}

author --&amp;gt; UC1
author --&amp;gt; UC2
author --&amp;gt; UC3
author --&amp;gt; UC4

reader_fr --&amp;gt; UC5
reader_fr --&amp;gt; UC7
reader_fr --&amp;gt; UC8

reader_en --&amp;gt; UC6
reader_en --&amp;gt; UC7
reader_en --&amp;gt; UC8

UC1 ..&amp;gt; UC4 : &amp;lt;&amp;lt;include&amp;gt;&amp;gt;
UC2 ..&amp;gt; UC4 : &amp;lt;&amp;lt;include&amp;gt;&amp;gt;
UC3 ..&amp;gt; UC4 : &amp;lt;&amp;lt;include&amp;gt;&amp;gt;
UC5 ..&amp;gt; UC8 : &amp;lt;&amp;lt;extend&amp;gt;&amp;gt;
UC6 ..&amp;gt; UC8 : &amp;lt;&amp;lt;extend&amp;gt;&amp;gt;
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_uluslararasılaştırma_mimarisi&quot;&gt;Uluslararasılaştırma mimarisi&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Yaklaşımız iki temel üzerine dayanır:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;templating&amp;#8217;in i18n&lt;/strong&gt;: Thymeleaf mesaj dosyalarının arayüz öğeleri için kullanımı&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;İçeriğin i18n&amp;#8217;i&lt;/strong&gt;: dile göre makaleleri ayrı klasör yapısında düzenleme&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_yapı_diyagramı_dosya_organizasyonu&quot;&gt;Yapı diyagramı (Dosya organizasyonu)&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
@startsalt
{
{T
+ projet-jbake
++ content
+++ blog
++++ 2024
+++++ fr
++++++ article1.adoc
++++++ article2.adoc
+++++ en
++++++ article1.adoc
++++++ article2.adoc
++++ 2025
+++++ fr
++++++ guide-i18n.adoc
+++++ en
++++++ i18n-guide.adoc
++ templates
+++ post.html
+++ index.html
+++ index_en.html
+++ messages.properties
+++ messages_fr.properties
+++ messages_en.properties
++ assets
+++ css
+++ js
+++ img
++ jbake.properties
++ output
+++ fr
++++ blog
+++++ 2025
++++++ guide-i18n.html
+++ en
++++ blog
+++++ 2025
++++++ i18n-guide.html
}
}
@endsalt
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_neden_bu_yaklaşım&quot;&gt;Neden bu yaklaşım?&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Bu ayrıştırma şunu mümkün kılar:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Dil ne olursa olsun arayüzde tutarlılık koruyun&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;İçerik ve makale çevirlerini bağımsız olarak yönet&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Yeni dillerin eklenmesini büyük refaktörleme yapmadan kolaylaştır&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Belirli dillerde sadece mevcut olan makalelere izin ver&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_bileşen_diyagramı&quot;&gt;Bileşen diyagramı&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
skinparam componentStyle rectangle

package &quot;Kaynaklar&quot; {
  folder &quot;content/blog/2025/&quot; {
    folder &quot;fr/&quot; as content_fr {
      [article1.adoc]
      [article2.adoc]
    }
    folder &quot;en/&quot; as content_en {
      [article1.adoc] as article1_en
      [article2.adoc] as article2_en
    }
  }

  folder &quot;şablonlar/&quot; {
    [post.html]
    [index.html]
    [index_en.html]
  }

  folder &quot;mesajlar/&quot; {
    [messages_fr.properties]
    [messages_en.properties]
  }

  [jbake.properties]
}

package &quot;JBake Engine&quot; {
  [Parser AsciiDoc] as parser
  [Template Engine\nThymeleaf] as thymeleaf
  [Generator] as generator
  [I18n Resolver] as i18n
}

package &quot;oluşturulan site&quot; {
  folder &quot;fr/&quot; {
    folder &quot;blog/2025/&quot; as blog_fr {
      [article1.html]
      [article2.html]
    }
  }

  folder &quot;en/&quot; {
    folder &quot;blog/2025/&quot; as blog_en {
      [article1.html] as article1_html_en
      [article2.html] as article2_html_en
    }
  }
}

content_fr --&amp;gt; parser
content_en --&amp;gt; parser
parser --&amp;gt; generator

templates --&amp;gt; thymeleaf
messages --&amp;gt; i18n
i18n --&amp;gt; thymeleaf
thymeleaf --&amp;gt; generator
jbake.properties --&amp;gt; generator

generator --&amp;gt; blog_fr
generator --&amp;gt; blog_en
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_thymeleaf_ile_şablonlama_i18n&quot;&gt;Thymeleaf ile şablonlama I18n&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_mesaj_dosyalarının_yapısı&quot;&gt;Mesaj dosyalarının yapısı&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;İlk adım, desteklenen her dil için özellik dosyalarını oluşturmaktır :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-text hljs&quot; data-lang=&quot;text&quot;&gt;src/jbake/templates/
├── messages.properties        # Fallback par défaut
├── messages_fr.properties     # Français
├── messages_en.properties     # Anglais
└── messages_de.properties     # Allemand&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_mesaj_dosyalarının_içeriği&quot;&gt;Mesaj dosyalarının içeriği&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;İşte bir dosya örneği`messages_fr.properties` :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-properties hljs&quot; data-lang=&quot;properties&quot;&gt;# Navigation
nav.home=Accueil
nav.blog=Blog
nav.about=À propos
nav.contact=Contact

# Articles
article.readmore=Lire la suite
article.published=Publié le
article.tags=Étiquettes
article.also.available=Également disponible en

# Interface
site.title=Mon Blog Technique
site.description=Partage de connaissances et expériences
footer.copyright=© 2025 Tous droits réservés
search.placeholder=Rechercher un article...&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Ve onun İngilizce karşılığı`messages_en.properties` :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-properties hljs&quot; data-lang=&quot;properties&quot;&gt;# Navigation
nav.home=Home
nav.blog=Blog
nav.about=About
nav.contact=Contact

# Articles
article.readmore=Read more
article.published=Published on
article.tags=Tags
article.also.available=Also available in

# Interface
site.title=My Tech Blog
site.description=Sharing knowledge and experiences
footer.copyright=© 2025 All rights reserved
search.placeholder=Search articles...&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_şablonlarda_kullanım&quot;&gt;Şablonlarda kullanım&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Thymeleaf şablonlarınızda sözdizimini kullanın`#{}`mesajlara erişmek için :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-html hljs&quot; data-lang=&quot;html&quot;&gt;&amp;lt;!DOCTYPE html&amp;gt;
&amp;lt;html xmlns:th=&quot;http://www.thymeleaf.org&quot;&amp;gt;
&amp;lt;head&amp;gt;
    &amp;lt;title th:text=&quot;#{site.title}&quot;&amp;gt;Mon Blog&amp;lt;/title&amp;gt;
    &amp;lt;meta name=&quot;description&quot; th:content=&quot;#{site.description}&quot; /&amp;gt;
&amp;lt;/head&amp;gt;
&amp;lt;body&amp;gt;
    &amp;lt;nav&amp;gt;
        &amp;lt;a th:href=&quot;@{/}&quot; th:text=&quot;#{nav.home}&quot;&amp;gt;Accueil&amp;lt;/a&amp;gt;
        &amp;lt;a th:href=&quot;@{/blog/}&quot; th:text=&quot;#{nav.blog}&quot;&amp;gt;Blog&amp;lt;/a&amp;gt;
        &amp;lt;a th:href=&quot;@{/about.html}&quot; th:text=&quot;#{nav.about}&quot;&amp;gt;À propos&amp;lt;/a&amp;gt;
    &amp;lt;/nav&amp;gt;

    &amp;lt;footer&amp;gt;
        &amp;lt;p th:text=&quot;#{footer.copyright}&quot;&amp;gt;Copyright&amp;lt;/p&amp;gt;
    &amp;lt;/footer&amp;gt;
&amp;lt;/body&amp;gt;
&amp;lt;/html&amp;gt;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_dizineydiagramı_i18n_çözümü&quot;&gt;Dizineydiagramı - i18n Çözümü&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
actor Auteur
participant JBake
participant &quot;AsciiDoc\nParser&quot; as parser
participant &quot;Thymeleaf
Motor&quot; as thymeleaf
participant &quot;Uluslararasılaştırma
Çözümleyici&quot; as i18n
database &quot;messages_*.properties&quot; as messages

Auteur -&amp;gt; JBake: jbake -b
activate JBake

JBake -&amp;gt; parser: Lire article.fr.adoc
activate parser
parser --&amp;gt; JBake: Contenu + métadonnées\n(lang=fr, article-id=xyz)
deactivate parser

JBake -&amp;gt; parser: Lire article.en.adoc
activate parser
parser --&amp;gt; JBake: Contenu + métadonnées\n(lang=en, article-id=xyz)
deactivate parser

JBake -&amp;gt; thymeleaf: Générer page FR
activate thymeleaf

thymeleaf -&amp;gt; i18n: Résoudre #{nav.home}
activate i18n
i18n -&amp;gt; messages: Lire messages_fr.properties
messages --&amp;gt; i18n: &quot;Ana Sayfa&quot;
i18n --&amp;gt; thymeleaf: &quot;Ana Sayfa&quot;
deactivate i18n

thymeleaf -&amp;gt; JBake: Rechercher traductions\n(article-id=xyz, lang!=fr)
JBake --&amp;gt; thymeleaf: article.en.html trouvé

thymeleaf --&amp;gt; JBake: /fr/blog/article.html
deactivate thymeleaf

JBake -&amp;gt; thymeleaf: Générer page EN
activate thymeleaf

thymeleaf -&amp;gt; i18n: Résoudre #{nav.home}
activate i18n
i18n -&amp;gt; messages: Lire messages_en.properties
messages --&amp;gt; i18n: &quot;Ana Sayfa&quot;
i18n --&amp;gt; thymeleaf: &quot;Ana Sayfa&quot;
deactivate i18n

thymeleaf -&amp;gt; JBake: Rechercher traductions\n(article-id=xyz, lang!=en)
JBake --&amp;gt; thymeleaf: article.fr.html trouvé

thymeleaf --&amp;gt; JBake: /en/blog/article.html
deactivate thymeleaf

JBake --&amp;gt; Auteur: Site généré
deactivate JBake
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_jbakede_yerel_ayar_yapılandırması&quot;&gt;JBake&amp;#8217;de yerel ayar yapılandırması&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Dosyanızda`jbake.properties`, Varsayılan locale&amp;#8217;yi ayarlayın :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-properties hljs&quot; data-lang=&quot;properties&quot;&gt;# Locale par défaut
thymeleaf.locale=fr

# Encodage
template.encoding=UTF-8&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_makalelerin_i18ni_klasörlere_göre_düzenleme&quot;&gt;Makalelerin I18n&amp;#8217;i: klasörlere göre düzenleme&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_akış_şeması_flow_oluşturma&quot;&gt;Akış şeması (Flow) - Oluşturma&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
start

:Lire jbake.properties;
:Charger configuration i18n;

partition &quot;Her bir AsciiDoc dosyası için&quot; {
  :Lire métadonnées\n(:jbake-lang:, :jbake-article-id:);
  :Parser contenu AsciiDoc;
  :Stocker en mémoire avec langue;
}

partition &quot;Her şablon için&quot; {
  :Charger template Thymeleaf;
  :Identifier langue cible;
  :Charger messages_{lang}.properties;

  partition &quot;İçerik filtreleme&quot; {
    :Filtrer articles par langue;
    :Grouper traductions\npar article-id;
  }

  :Appliquer template avec i18n;
  :Générer HTML dans /{lang}/;
}

:Copier assets statiques;
:Générer sitemap multilingue;
:Générer flux RSS par langue;

stop
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_klasör_yapısı&quot;&gt;Klasör yapısı&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Dosya adlarında ek kullanmak yerine, daha fazla açıklık ve sürdürülebilirlik sunan bir klasör tabanlı organizasyon tercih ettim:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-text hljs&quot; data-lang=&quot;text&quot;&gt;content/blog/
├── 2024/
│   ├── fr/
│   │   ├── introduction-jbake.adoc
│   │   ├── guide-thymeleaf.adoc
│   │   └── astuces-asciidoc.adoc
│   └── en/
│       ├── introduction-jbake.adoc
│       ├── thymeleaf-guide.adoc
│       └── asciidoc-tips.adoc
└── 2025/
    ├── fr/
    │   └── internationalisation-jbake.adoc
    └── en/
        └── jbake-internationalization.adoc&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_bu_yaklaşımın_avantajları&quot;&gt;Bu yaklaşımın avantajları&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Bu yapının birkaç avantajı :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;net ayrıştırma&lt;/strong&gt;: her dilin kendi alanı var&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Esnek adlandırma&lt;/strong&gt;: dosyaların farklı dillere göre farklı isimler olabilir&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;ölçeklenebilirlik&lt;/strong&gt;: Yeni bir dil eklemek kolaydır&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Doğal organizasyon&lt;/strong&gt;: JBake&amp;#8217;in zaman mantığını izler&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_makale_meta_verileri&quot;&gt;Makale meta verileri&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Her makale çeviriler arasındaki bağlantıyı sağlayabilmek için meta veri içermelidir. Bir örnek:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Fransızca sürüm&lt;/strong&gt;(&lt;code&gt;2025/fr/internationalisation-jbake.adoc&lt;/code&gt;) :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-asciidoc hljs&quot; data-lang=&quot;asciidoc&quot;&gt;= Internationalisation d&#39;un site statique JBake
:jbake-type: post
:jbake-status: published
:jbake-date: 2025-10-20
:jbake-lang: fr
:jbake-article-id: jbake-i18n-thymeleaf
:jbake-tags: jbake, thymeleaf, i18n
:jbake-description: Guide pour mettre en place l&#39;i18n avec JBake&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;İngilizce sürümü&lt;/strong&gt;(&lt;code&gt;2025/en/jbake-internationalization.adoc&lt;/code&gt;) :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-asciidoc hljs&quot; data-lang=&quot;asciidoc&quot;&gt;= Internationalizing a JBake Static Site
:jbake-type: post
:jbake-status: published
:jbake-date: 2025-10-20
:jbake-lang: en
:jbake-article-id: jbake-i18n-thymeleaf
:jbake-tags: jbake, thymeleaf, i18n
:jbake-description: Guide to implement i18n with JBake&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Not: Özellik`:jbake-article-id:`Çok önemli: aynı makalenin farklı çevirilerini birbirine bağlamaya olanak tanır.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_url_yapılandırması&quot;&gt;URL Yapılandırması&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;İçinde`jbake.properties`, URL patternini dili dahil edecek şekilde yapılandırın :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-properties hljs&quot; data-lang=&quot;properties&quot;&gt;# Pattern d&#39;URL avec langue
post.permalink.pattern=:lang/blog/:year/:name.html

# Langue par défaut
site.default.lang=fr&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Bu, aşağıdaki gibi URL&amp;#8217;ler oluşturur:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;/fr/blog/2025/internationalisation-jbake.html&lt;/code&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;/en/blog/2025/jbake-internationalization.html&lt;/code&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_çok_dilli_görüntüleme_şablonları&quot;&gt;Çok dilli görüntüleme şablonları&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_dil_seçiciyle_makale_şablonu&quot;&gt;Dil seçiciyle makale şablonu&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Bir şablon oluşturun`post.html`mevcut çevirileri gösteren :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-html hljs&quot; data-lang=&quot;html&quot;&gt;&amp;lt;!DOCTYPE html&amp;gt;
&amp;lt;html xmlns:th=&quot;http://www.thymeleaf.org&quot;&amp;gt;
&amp;lt;head&amp;gt;
    &amp;lt;title th:text=&quot;${content.title}&quot;&amp;gt;Article&amp;lt;/title&amp;gt;
&amp;lt;/head&amp;gt;
&amp;lt;body&amp;gt;
    &amp;lt;article&amp;gt;
        &amp;lt;header&amp;gt;
            &amp;lt;h1 th:text=&quot;${content.title}&quot;&amp;gt;Titre&amp;lt;/h1&amp;gt;

            &amp;lt;div class=&quot;article-meta&quot;&amp;gt;
                &amp;lt;time th:text=&quot;${#dates.format(content.date, &#39;dd MMMM yyyy&#39;)}&quot;
                      th:attr=&quot;datetime=${#dates.format(content.date, &#39;yyyy-MM-dd&#39;)}&quot;&amp;gt;
                    Date
                &amp;lt;/time&amp;gt;

                &amp;lt;!-- Sélecteur de traductions --&amp;gt;
                &amp;lt;div class=&quot;translations&quot; th:if=&quot;${content[&#39;article-id&#39;]}&quot;&amp;gt;
                    &amp;lt;span th:text=&quot;#{article.also.available}&quot;&amp;gt;Aussi disponible en :&amp;lt;/span&amp;gt;
                    &amp;lt;ul class=&quot;language-list&quot;&amp;gt;
                        &amp;lt;li th:each=&quot;post : ${published_posts}&quot;
                            th:if=&quot;${post[&#39;article-id&#39;] == content[&#39;article-id&#39;] and post.lang != content.lang}&quot;&amp;gt;
                            &amp;lt;a th:href=&quot;${post.uri}&quot;
                               th:text=&quot;${post.lang.toUpperCase()}&quot;&amp;gt;
                                LANG
                            &amp;lt;/a&amp;gt;
                        &amp;lt;/li&amp;gt;
                    &amp;lt;/ul&amp;gt;
                &amp;lt;/div&amp;gt;
            &amp;lt;/div&amp;gt;
        &amp;lt;/header&amp;gt;

        &amp;lt;div class=&quot;content&quot; th:utext=&quot;${content.body}&quot;&amp;gt;
            Contenu de l&#39;article
        &amp;lt;/div&amp;gt;

        &amp;lt;footer class=&quot;article-footer&quot;&amp;gt;
            &amp;lt;div class=&quot;tags&quot; th:if=&quot;${content.tags}&quot;&amp;gt;
                &amp;lt;span th:text=&quot;#{article.tags}&quot;&amp;gt;Étiquettes :&amp;lt;/span&amp;gt;
                &amp;lt;span th:each=&quot;tag : ${content.tags}&quot;&amp;gt;
                    &amp;lt;a th:href=&quot;@{/tags/{tag}.html(tag=${tag})}&quot;
                       th:text=&quot;${tag}&quot;&amp;gt;tag&amp;lt;/a&amp;gt;
                &amp;lt;/span&amp;gt;
            &amp;lt;/div&amp;gt;
        &amp;lt;/footer&amp;gt;
    &amp;lt;/article&amp;gt;
&amp;lt;/body&amp;gt;
&amp;lt;/html&amp;gt;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_dil_ile_filtrelenmiş_indeks&quot;&gt;Dil ile filtrelenmiş indeks&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Her dil için dizin şablonları oluşturun:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;index.html&lt;/strong&gt;(fransızca indeks) :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-html hljs&quot; data-lang=&quot;html&quot;&gt;&amp;lt;!DOCTYPE html&amp;gt;
&amp;lt;html xmlns:th=&quot;http://www.thymeleaf.org&quot;&amp;gt;
&amp;lt;head&amp;gt;
    &amp;lt;title th:text=&quot;#{site.title}&quot;&amp;gt;Mon Blog&amp;lt;/title&amp;gt;
&amp;lt;/head&amp;gt;
&amp;lt;body&amp;gt;
    &amp;lt;main&amp;gt;
        &amp;lt;h1 th:text=&quot;#{nav.blog}&quot;&amp;gt;Blog&amp;lt;/h1&amp;gt;

        &amp;lt;div class=&quot;articles-list&quot;&amp;gt;
            &amp;lt;article th:each=&quot;post : ${published_posts}&quot;
                     th:if=&quot;${post.lang == &#39;fr&#39;}&quot;&amp;gt;
                &amp;lt;h2&amp;gt;
                    &amp;lt;a th:href=&quot;${post.uri}&quot; th:text=&quot;${post.title}&quot;&amp;gt;Titre&amp;lt;/a&amp;gt;
                &amp;lt;/h2&amp;gt;
                &amp;lt;time th:text=&quot;${#dates.format(post.date, &#39;dd MMMM yyyy&#39;)}&quot;&amp;gt;
                    Date
                &amp;lt;/time&amp;gt;
                &amp;lt;p th:text=&quot;${post.description}&quot;&amp;gt;Description&amp;lt;/p&amp;gt;
                &amp;lt;a th:href=&quot;${post.uri}&quot; th:text=&quot;#{article.readmore}&quot;&amp;gt;
                    Lire la suite
                &amp;lt;/a&amp;gt;
            &amp;lt;/article&amp;gt;
        &amp;lt;/div&amp;gt;
    &amp;lt;/main&amp;gt;
&amp;lt;/body&amp;gt;
&amp;lt;/html&amp;gt;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;index_en.html&lt;/strong&gt;(İngiliz indeksi) :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-html hljs&quot; data-lang=&quot;html&quot;&gt;&amp;lt;!DOCTYPE html&amp;gt;
&amp;lt;html xmlns:th=&quot;http://www.thymeleaf.org&quot;&amp;gt;
&amp;lt;head&amp;gt;
    &amp;lt;title th:text=&quot;#{site.title}&quot;&amp;gt;My Blog&amp;lt;/title&amp;gt;
&amp;lt;/head&amp;gt;
&amp;lt;body&amp;gt;
    &amp;lt;main&amp;gt;
        &amp;lt;h1 th:text=&quot;#{nav.blog}&quot;&amp;gt;Blog&amp;lt;/h1&amp;gt;

        &amp;lt;div class=&quot;articles-list&quot;&amp;gt;
            &amp;lt;article th:each=&quot;post : ${published_posts}&quot;
                     th:if=&quot;${post.lang == &#39;en&#39;}&quot;&amp;gt;
                &amp;lt;h2&amp;gt;
                    &amp;lt;a th:href=&quot;${post.uri}&quot; th:text=&quot;${post.title}&quot;&amp;gt;Title&amp;lt;/a&amp;gt;
                &amp;lt;/h2&amp;gt;
                &amp;lt;time th:text=&quot;${#dates.format(post.date, &#39;dd MMMM yyyy&#39;)}&quot;&amp;gt;
                    Date
                &amp;lt;/time&amp;gt;
                &amp;lt;p th:text=&quot;${post.description}&quot;&amp;gt;Description&amp;lt;/p&amp;gt;
                &amp;lt;a th:href=&quot;${post.uri}&quot; th:text=&quot;#{article.readmore}&quot;&amp;gt;
                    Read more
                &amp;lt;/a&amp;gt;
            &amp;lt;/article&amp;gt;
        &amp;lt;/div&amp;gt;
    &amp;lt;/main&amp;gt;
&amp;lt;/body&amp;gt;
&amp;lt;/html&amp;gt;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_diller_arasında_gezinti&quot;&gt;Diller arasında gezinti&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_küresel_dil_seçici&quot;&gt;Küresel dil seçici&lt;/h3&gt;

&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_akış_diyagramı_kullanıcı_okuma&quot;&gt;Akış diyagramı - Kullanıcı okuma&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
start

:Utilisateur accède au site;

if (Langue préférée ?) then (FR)
  :Afficher /index.html;
  :Lister articles FR;
else (EN)
  :Afficher /en/index.html;
  :Lister articles EN;
endif

:Utilisateur clique sur article;

:Afficher article\navec métadonnées;

if (Traductions disponibles ?) then (oui)
  :Afficher sélecteur\nde traductions;

  if (Changement de langue ?) then (oui)
    :Rediriger vers\ntraduction;
    :Afficher article\ndans nouvelle langue;
  else (non)
    :Continuer lecture;
  endif
else (non)
  :Continuer lecture;
endif

stop
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Ana şablonunuzda bir dil seçici ekleyin :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-html hljs&quot; data-lang=&quot;html&quot;&gt;&amp;lt;nav class=&quot;language-switcher&quot;&amp;gt;
    &amp;lt;a href=&quot;/index.html&quot;
       th:classappend=&quot;${content.lang == &#39;fr&#39;} ? &#39;active&#39;&quot;
       title=&quot;Français&quot;&amp;gt;
        🇫🇷 FR
    &amp;lt;/a&amp;gt;
    &amp;lt;a href=&quot;/en/index.html&quot;
       th:classappend=&quot;${content.lang == &#39;en&#39;} ? &#39;active&#39;&quot;
       title=&quot;English&quot;&amp;gt;
        🇬🇧 EN
    &amp;lt;/a&amp;gt;
&amp;lt;/nav&amp;gt;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_seçici_için_css_stili&quot;&gt;Seçici için CSS stili&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-css hljs&quot; data-lang=&quot;css&quot;&gt;.language-switcher {
    display: flex;
    gap: 1rem;
    padding: 0.5rem;
    background: #f5f5f5;
    border-radius: 4px;
}

.language-switcher a {
    padding: 0.5rem 1rem;
    text-decoration: none;
    color: #333;
    border-radius: 4px;
    transition: background 0.2s;
}

.language-switcher a:hover {
    background: #e0e0e0;
}

.language-switcher a.active {
    background: #007bff;
    color: white;
}

.translations {
    margin: 1rem 0;
    padding: 1rem;
    background: #f8f9fa;
    border-left: 4px solid #007bff;
}

.language-list {
    display: inline-flex;
    gap: 0.5rem;
    list-style: none;
    padding: 0;
    margin: 0;
}

.language-list li::after {
    content: &quot;•&quot;;
    margin-left: 0.5rem;
}

.language-list li:last-child::after {
    content: &quot;&quot;;
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_dil_bazlı_rss_akışı&quot;&gt;Dil bazlı RSS akışı&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Dil ayarına göre ayrılmış RSS feed&amp;#8217;leri elde etmek için ayrı şablonlar oluşturun :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;feed.xml&lt;/strong&gt;(Fransızca akış) :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-xml hljs&quot; data-lang=&quot;xml&quot;&gt;&amp;lt;?xml version=&quot;1.0&quot; encoding=&quot;UTF-8&quot;?&amp;gt;
&amp;lt;rss version=&quot;2.0&quot; xmlns:th=&quot;http://www.thymeleaf.org&quot;&amp;gt;
    &amp;lt;channel&amp;gt;
        &amp;lt;title th:text=&quot;#{site.title}&quot;&amp;gt;Mon Blog&amp;lt;/title&amp;gt;
        &amp;lt;link th:text=&quot;${config.site_host}&quot;&amp;gt;http://example.com&amp;lt;/link&amp;gt;
        &amp;lt;description th:text=&quot;#{site.description}&quot;&amp;gt;Description&amp;lt;/description&amp;gt;
        &amp;lt;language&amp;gt;fr&amp;lt;/language&amp;gt;

        &amp;lt;item th:each=&quot;post : ${published_posts}&quot;
              th:if=&quot;${post.lang == &#39;fr&#39;}&quot;&amp;gt;
            &amp;lt;title th:text=&quot;${post.title}&quot;&amp;gt;Titre&amp;lt;/title&amp;gt;
            &amp;lt;link th:text=&quot;${config.site_host + post.uri}&quot;&amp;gt;Lien&amp;lt;/link&amp;gt;
            &amp;lt;pubDate th:text=&quot;${#dates.format(post.date, &#39;EEE, dd MMM yyyy HH:mm:ss Z&#39;)}&quot;&amp;gt;
                Date
            &amp;lt;/pubDate&amp;gt;
            &amp;lt;description th:text=&quot;${post.description}&quot;&amp;gt;Description&amp;lt;/description&amp;gt;
        &amp;lt;/item&amp;gt;
    &amp;lt;/channel&amp;gt;
&amp;lt;/rss&amp;gt;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_i̇yi_uygulamalar_ve_ipuçları&quot;&gt;İyi uygulamalar ve ipuçları&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_1_makale_kimliklerinin_tutarlılığı&quot;&gt;1. Makale kimliklerinin tutarlılığı&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Emin olun ki`:jbake-article-id:`bir makalenin tüm çevirileri için aynıdır. Tutarlı bir format kullanın :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Küresellik için İngilizce tanımlayıcıları tercih edin&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Kelimeleri ayırmak için tireler kullanın&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Özel karakterlerden kaçının&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_2_tutarlı_tarihler&quot;&gt;2. Tutarlı tarihler&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Bir makalenin tüm çevirileri aynı yayın tarihine sahip olmalıdır (`:jbake-date:`Bu, sıralamayı ve kronolojik görüntülemeyi kolaylaştırır.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_3_çok_dilli_etiketler&quot;&gt;3. Çok dilli etiketler&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Etiketler için, iki seçeneğiniz var :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Seçenek 1 : İngilizce evrensel etiketler&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-asciidoc hljs&quot; data-lang=&quot;asciidoc&quot;&gt;:jbake-tags: java, spring-boot, microservices&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Seçenek 2 : Eşlemeyle çevirilen etiketler&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-asciidoc hljs&quot; data-lang=&quot;asciidoc&quot;&gt;# Version française
:jbake-tags: java, spring-boot, microservices

# Version anglaise
:jbake-tags: java, spring-boot, microservices&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_4_çevirilmemiş_makalelerin_yönetimi&quot;&gt;4. Çevirilmemiş makalelerin yönetimi&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Tüm makaleleri çevirmek zorunlu değildir. Bir makale sadece bir dilde mevcutsa, diğer dilin listelerinde görünmez.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_5_çok_dilli_sitemap&quot;&gt;5. Çok dilli sitemap&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Tüm dilleri içeren bir sitemap oluşturun:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-xml hljs&quot; data-lang=&quot;xml&quot;&gt;&amp;lt;?xml version=&quot;1.0&quot; encoding=&quot;UTF-8&quot;?&amp;gt;
&amp;lt;urlset xmlns=&quot;http://www.sitemaps.org/schemas/sitemap/0.9&quot;
        xmlns:xhtml=&quot;http://www.w3.org/1999/xhtml&quot;
        xmlns:th=&quot;http://www.thymeleaf.org&quot;&amp;gt;
    &amp;lt;url th:each=&quot;post : ${published_posts}&quot;&amp;gt;
        &amp;lt;loc th:text=&quot;${config.site_host + post.uri}&quot;&amp;gt;URL&amp;lt;/loc&amp;gt;
        &amp;lt;lastmod th:text=&quot;${#dates.format(post.date, &#39;yyyy-MM-dd&#39;)}&quot;&amp;gt;Date&amp;lt;/lastmod&amp;gt;

        &amp;lt;!-- Liens alternatifs pour les traductions --&amp;gt;
        &amp;lt;xhtml:link th:each=&quot;translation : ${published_posts}&quot;
                    th:if=&quot;${translation[&#39;article-id&#39;] == post[&#39;article-id&#39;] and translation.lang != post.lang}&quot;
                    rel=&quot;alternate&quot;
                    th:attr=&quot;hreflang=${translation.lang},href=${config.site_host + translation.uri}&quot; /&amp;gt;
    &amp;lt;/url&amp;gt;
&amp;lt;/urlset&amp;gt;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_sonuç&quot;&gt;Sonuç&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;JBake sitesinin Thymeleaf ile uluslararasılaştırılması sağlam ve sürdürülebilir bir yaklaşımdır. Şablondan i18n&amp;#8217;i (mesaj dosyalarıyla) ve içerikten i18n&amp;#8217;i (klasör organizasyonuyla) ayırarak, kolayca gelişebilen esnek bir sistem elde edersiniz.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Önemli noktalar:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Thymeleaf mesaj dosyaları&lt;/strong&gt;kullanıcı arayüzü için&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Klasör bazlı düzenleme&lt;/strong&gt;(yıl/dil) makaleler için&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Makale kimlikleri&lt;/strong&gt;çevirileri bağlamak için&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Özel şablonlar&lt;/strong&gt;her dil için&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Açık URL&amp;#8217;ler&lt;/strong&gt;dil kodunu içeren&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_dağıtım_diyagramı&quot;&gt;Dağıtım Diyagramı&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
node &quot;Geliştirme Makinesi&quot; {
  artifact &quot;Kaynaklar&quot; {
    folder &quot;mutlu/&quot;
    folder &quot;şablonlar/&quot;
    folder &quot;assets/&quot;
  }

  component &quot;JBake CLI&quot; as jbake

  Sources --&amp;gt; jbake : jbake -b
}

node &quot;Derleme sunucusu
(CI/CD)&quot; {
  component &quot;GitHub Actions
veya GitLab CI&quot; as ci

  jbake --&amp;gt; ci : push
}

cloud &quot;CDN / Barındırma&quot; {
  node &quot;Statik Web Sunucu&quot; {
    artifact &quot;Oluşturulan site&quot; {
      folder &quot;/fr/blog/&quot;
      folder &quot;/en/blog/&quot;
      folder &quot;/assets/&quot;
    }
  }
}

ci --&amp;gt; &quot;Oluşturulan site&quot; : déploiement

actor &quot;Okuyucular&quot; as users

users --&amp;gt; &quot;Statik Web Sunucu&quot; : HTTPS
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Bu mimari, iki dille basitçe başlamanı ve büyük refactoring yapmadan diğer dilleri eklemeni sağlar. Her şey tamamen statik ve performant kalır, JBake felsefesine sadık kalır.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Çoklu dil geliştirme iyi! 🌍&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;Table of Contents&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_giriş&quot;&gt;Giriş&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_tor_ve_imzasının_indirimi&quot;&gt;Tor ve imzasının indirimi&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_kriptografik_imza_doğrulaması&quot;&gt;kriptografik imza doğrulaması&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_tor_projesinin_genel_anahtarını_içe_aktar&quot;&gt;Tor Projesinin genel anahtarını içe aktar&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_2_i̇mzayı_doğrula&quot;&gt;2. İmzayı doğrula&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_pratik_durum_geçerli_imza_ama_sertifikasız_anahtar&quot;&gt;Pratik durum: Geçerli imza ama sertifikasız anahtar&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_i̇mzayı_neden_kontrol_etmek&quot;&gt;İmzayı neden kontrol etmek?&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_tor_browserın_çıkarılması_ve_başlatılması&quot;&gt;Tor Browser&amp;#8217;ın çıkarılması ve başlatılması&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_ubuntu_masaüstü_entegrasyonu&quot;&gt;Ubuntu masaüstü entegrasyonu&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_tor_ile_eğitim_kaynaklarını_keşfet&quot;&gt;Tor ile eğitim kaynaklarını keşfet&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_tor_browser_güncellemesi&quot;&gt;Tor Browser güncellemesi&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_sonuç&quot;&gt;Sonuç&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_referanslar&quot;&gt;Referanslar&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_giriş&quot;&gt;Giriş&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Dijital gizlilik her geçen gün daha da tehdit altında bir dünyada, &lt;strong&gt;Tor Browser&lt;/strong&gt; anonimliğini ve bilgilendirme özgürlüğünü korumak için vazgeçilmez bir araçtır. Ancak, indirilen bir yazılımı asla çalıştırmadan önce&lt;strong&gt;authentikliğini doğrulamış&lt;/strong&gt;. Bu makale, tam bir yöntem sunar :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Tor Browser&lt;/strong&gt; ve imzasını indir`.asc`&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;İndirilen dosyanın geçerliliğini kontrol edin&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Ubuntu üzerinde &lt;strong&gt;Tor Browser&lt;/strong&gt; kurun ve başlatın&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Günlük kullanım için masaüstü menülerine eklemek&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Tor üzerinden eğitim kaynakları ve etik OSINT kaynaklarını keşfedin&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_tor_ve_imzasının_indirimi&quot;&gt;Tor ve imzasının indirimi&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Tor tarayıcı için ayrı bir klasör oluşturun:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;mkdir -p ~/workspace/tipiak/tor
cd ~/workspace/tipiak/tor&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Sonra Tor tarayıcısının arşivi ve imzasını indirin:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;wget https://www.torproject.org/dist/torbrowser/14.5.7/tor-browser-linux-x86_64-14.5.7.tar.xz
wget https://www.torproject.org/dist/torbrowser/14.5.7/tor-browser-linux-x86_64-14.5.7.tar.xz.asc&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_kriptografik_imza_doğrulaması&quot;&gt;kriptografik imza doğrulaması&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Bu adıma&lt;strong&gt;gerekli&lt;/strong&gt;indirilen dosyanın Tor Project&amp;#8217;ten geldiğinden ve değiştirilmediğinden emin olmak için.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_tor_projesinin_genel_anahtarını_içe_aktar&quot;&gt;Tor Projesinin genel anahtarını içe aktar&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;gpg --auto-key-locate nodefault,wkd --locate-keys torbrowser@torproject.org&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Anahtarın düzgün bir şekilde aktarıldığını kontrol edin:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;gpg --list-keys torbrowser@torproject.org&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_2_i̇mzayı_doğrula&quot;&gt;2. İmzayı doğrula&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;gpg --verify tor-browser-linux-x86_64-14.5.7.tar.xz.asc tor-browser-linux-x86_64-14.5.7.tar.xz&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Her şey doğruysa, aşağıdaki mesaj görüntülenecek:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-none hljs&quot;&gt;gpg: Good signature from &quot;Tor Browser Developers (signing key)&quot;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Sertifikalı olmayan anahtar uyarısı alındığında, bu sadece Tor Project&amp;#8217;in güvenilir anahtarını henüz imzaladığınızı, imzanın hâlâ geçerli olduğu anlamına gelir.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_pratik_durum_geçerli_imza_ama_sertifikasız_anahtar&quot;&gt;Pratik durum: Geçerli imza ama sertifikasız anahtar&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Doğrulama sırasında bu gibi bir mesajla karşılaşmak yaygındır :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-none hljs&quot;&gt;gpg --verify tor-browser-linux-x86_64-14.5.7.tar.xz.asc tor-browser-linux-x86_64-14.5.7.tar.xz
gpg: Signature faite le mar. 16 sept. 2025 14:26:26 CEST
gpg:                avec la clef RSA CAAE408AEBE2288E96FC5D5E157432CF78A65729
gpg: Bonne signature de « Tor Browser Developers (signing key) &amp;lt;torbrowser@torproject.org&amp;gt; » [inconnu]
gpg: Attention : cette clef n&#39;est pas certifiée avec une signature de confiance.
gpg:          Rien n&#39;indique que la signature appartient à son propriétaire.
Empreinte de clef principale : EF6E 286D DA85 EA2A 4BA7  DE68 4E2C 6E87 9329 8290
     Empreinte de la sous-clef : CAAE 408A EBE2 288E 96FC  5D5E 1574 32CF 78A6 5729&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Bu mesaj, imzanın teknik olarak &quot;geçerli&quot; olduğu (dosya bozulmamış) ancak GPG sisteminizin anahtarın kendisine &lt;strong&gt;güveni sertifile&lt;/strong&gt; edemediğini gösterir. Bu şüpheyi gidermek için anahtarın ana parmağını karşılaştırmak zorunludur (&lt;code&gt;EF6E 286D DA85 EA2A 4BA7 DE68 4E2C 6E87 9329 8290&lt;/code&gt;) Tor Projesi&amp;#8217;nin resmi sitesinde yayınlananla&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Resmi sitesine göre, beklenen iz:`EF6E286DDA85EA2A4BA7DE684E2C6E8793298290`.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Çünkü görüntülenen iz`gpg`Resmi sitesiyle &lt;strong&gt;tam olarak&lt;/strong&gt; eşleşiyorsa, anahtarın geçerli olduğunu ve dosyanın güvenli olduğunu kesinleştirebilirsiniz. &quot;Sertifikalı olmayan anahtar&quot; uyarısı, ardından yerel GPG yapılandırmanızla ilgili bir bilgidir ve imzanın geçerliliği ya da dosyanın authenticitiyle ilgili değildir.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_i̇mzayı_neden_kontrol_etmek&quot;&gt;İmzayı neden kontrol etmek?&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;GPG imzalarının doğrulanması, dijital güvenlik için temel bir eylemdir. İzin verir:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;garantilemek&lt;strong&gt;asallık&lt;/strong&gt;indirilen yazılım&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Kötü niyetli bir aktör tarafından tehlikeye giren bir dosyanın kurulmasını engellemek&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Katılmak&lt;strong&gt;dijital egemenlik&lt;/strong&gt;bireysel&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Sorumlu ve etik bir dijital kültür teşvik etmek&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
left to right direction
actor &quot;Kullanıcı&quot; as U
actor &quot;Sunucu TorProject&quot; as S

usecase &quot;Tor ve imzasını indir&quot; as D
usecase &quot;Public anahtarını içe aktar&quot; as K
usecase &quot;GPG imzasını kontrol et&quot; as V
usecase &quot;Tor&#39;u yükle ve çalıştır&quot; as I

U --&amp;gt; D
U --&amp;gt; K
U --&amp;gt; V
U --&amp;gt; I
S --&amp;gt; D

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_tor_browserın_çıkarılması_ve_başlatılması&quot;&gt;Tor Browser&amp;#8217;ın çıkarılması ve başlatılması&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;İndirilen arşivinizi açın:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;tar -xvf tor-browser-linux-x86_64-14.5.7.tar.xz
cd tor-browser&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Ardından tarayıcıyı başlatın :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;./start-tor-browser.desktop&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;İlk çalıştırmada, Tor ağına bağlantı kurmak için bir yapılandırma penceresi açılacak.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_ubuntu_masaüstü_entegrasyonu&quot;&gt;Ubuntu masaüstü entegrasyonu&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Tor Browser&lt;/strong&gt; uygulama menüsüne eklemek için:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;./start-tor-browser.desktop --register-app&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Ardından şunları yapabilirsiniz:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Uygulamalar menüsünden &lt;strong&gt;Tor Browser&lt;/strong&gt;&#39;u çalıştır&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Dock favorilerine ekle&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;İstenirse bir klavye kısayolu oluştur&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
start
:Téléchargement de Tor;
:Importation de la clé GPG;
:Vérification de la signature;
if (Signature valide ?) then (Oui)
:Extraction du navigateur;
:Lancement du navigateur Tor;
:Enregistrement dans le bureau;
else (Non)
:Supprimer le fichier compromis;
endif
stop
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_tor_ile_eğitim_kaynaklarını_keşfet&quot;&gt;Tor ile eğitim kaynaklarını keşfet&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Tor sadece bir anonimlik aracı değil. Bu, eğitim ve araştırma kaynaklarına erişim sağlayan bir portaldır, özellikle aşağıdaki alanlarda:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;OSINT (Açık Kaynak İstihbaratı)&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://inteltechniques.com&quot;&gt;https://inteltechniques.com&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://osintframework.com&quot;&gt;https://osintframework.com&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Eğitimsel paylaşım ve açık kaynak&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://archive.org&quot;&gt;https://archive.org&lt;/a&gt;(Tor üzerinden erişim, daha fazla gizlilik için)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://github.com/&quot;&gt;https://github.com/&lt;/a&gt;Tor üzerinden erişilebilir&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://librarygenesis.pro&quot;&gt;https://librarygenesis.pro&lt;/a&gt;(özgür bilimsel literatür erişimi)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Bilgi aktarımı ve insanlıkla ilgili anlayış, dijital toplumda&lt;/strong&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Dijital kültür, ifade özgürlüğü ve bilgi erişimi kaynakları&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Özgür Siber Güvenlik ve Teknoloji Etik Hakkındaki Dokümantasyon&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_tor_browser_güncellemesi&quot;&gt;Tor Browser güncellemesi&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Optimal güvenlik sağlamak için &lt;strong&gt;Tor Browser&lt;/strong&gt; güncel tutulması çok önemlidir. Tarayıcı, komut satırından tetiklenebilecek otomatik bir güncelleme mekanizması içerir.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Tor Browser kurulum dizininden, başlatma komut dosyasını yeniden çalıştırmak yeterlidir :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;cd ~/workspace/tipiak/tor/tor-browser
./start-tor-browser.desktop&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Başlangıçta, &lt;strong&gt;Tor Browser&lt;/strong&gt; otomatik olarak yeni bir sürüm olup olmadığını kontrol eder. Eğer bir güncelleme mevcutsa, onu indirir ve sizin için kurar.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Bu basit yöntem, güvenli bir gezinti için gerekli olan en son güvenlik yamalarını ve en güncel iyileştirmeleri her zaman bulundurmanızı sağlar; bu, güvenli bir gezinti için hayati önem taşır.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_sonuç&quot;&gt;Sonuç&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;İndirmelerini kontrol etmek, güvenli bir dijital ortamda ilerlemek isteyen herkes için temel bir refleksidir. Tor&amp;#8217;u doğrulanan bir şekilde kurmak,&lt;strong&gt;dijital bütünlüğünü korumak&lt;/strong&gt;, &lt;strong&gt;özgür yazılımlardaki güveni korumak&lt;/strong&gt;, et &lt;strong&gt;bilgi bağımsızlığını güçlendirmek&lt;/strong&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;strong&gt;Dijital güvenlik bir bilinçli eylemdir, bir korku değil.&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
title Tor kullanımının sentezli görünümü
actor Utilisateur
rectangle &quot;Tor Tarayıcı&quot; {
rectangle &quot;anonimlik&quot; as A
rectangle &quot;OSINT Arama&quot; as O
rectangle &quot;Eğitim paylaşımı&quot; as E
}
Utilisateur --&amp;gt; A
Utilisateur --&amp;gt; O
Utilisateur --&amp;gt; E
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_referanslar&quot;&gt;Referanslar&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Tor Projesi&amp;#8217;nin resmi sitesi:https://www.torproject.org/download/[&lt;a href=&quot;https://www.torproject.org/download/&quot; class=&quot;bare&quot;&gt;https://www.torproject.org/download/&lt;/a&gt;]&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;İmza doğrulama dokümanı:https://support.torproject.org/tbb/how-to-verify-signature/[&lt;a href=&quot;https://support.torproject.org/tbb/how-to-verify-signature/&quot; class=&quot;bare&quot;&gt;https://support.torproject.org/tbb/how-to-verify-signature/&lt;/a&gt;]&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Ubuntu Belgeleri:https://ubuntu.com[&lt;a href=&quot;https://ubuntu.com&quot; class=&quot;bare&quot;&gt;https://ubuntu.com&lt;/a&gt;]&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Eğitim arşivi :https://archive.org/details/opensource[&lt;a href=&quot;https://archive.org/details/opensource&quot; class=&quot;bare&quot;&gt;https://archive.org/details/opensource&lt;/a&gt;]&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;admonitionblock note&quot;&gt;
&lt;table&gt;
&lt;tr&gt;
&lt;td class=&quot;icon&quot;&gt;
&lt;i class=&quot;fa icon-note&quot; title=&quot;Note&quot;&gt;&lt;/i&gt;
&lt;/td&gt;
&lt;td class=&quot;content&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Bu makale &lt;strong&gt;Güvenlik ve Dijital Farkındalık&lt;/strong&gt; serisinin bir parçasıdır, sorumlu ve pedagogik uygulamaları teşvik etmeyi amaçlayan özgür araçlar etrafında&lt;/p&gt;
&lt;/div&gt;
&lt;/td&gt;
&lt;/tr&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;Sommaire&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_giriş&quot;&gt;Giriş&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_1_versiyon_kataloğu_libs_versions_toml_bir_hatırlatma&quot;&gt;1. Versiyon Kataloğu (&lt;code&gt;libs.versions.toml&lt;/code&gt;) : Bir Hatırlatma&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_2_sorun_bir_bileşik_yapı_ve_ayrı_dünyalar&quot;&gt;2. Sorun: Bir Bileşik Yapı ve Ayrı Dünyalar&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_3_çözüm_bağımlılık_çözümlemesini_paylaşmak&quot;&gt;3. Çözüm: Bağımlılık Çözümlemesi&amp;#8217;ni Paylaşmak&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_4_sonuç_yönetilmiş_bileşenli_yapıların_gücü&quot;&gt;4. Sonuç: Yönetilmiş bileşenli yapıların gücü&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_giriş&quot;&gt;Giriş&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;div class=&quot;title&quot;&gt;Hedef kitle : Çoklu derleme projelerinde bağımlılık yönetimiyle karşı karşıya olan Gradle geliştiricileri.&lt;/div&gt;
&lt;p&gt;Bizim plugini oluşturma çabamızda`site-baker`, temiz ve merkezi bir kod tabanı korumaya çalıştık. Modern Gradle ekosistemindeki en iyi uygulamalardan biri, &amp;#8230;&amp;#8203; kullanmaktır.&lt;strong&gt;sürümler kataloğu&lt;/strong&gt;(&lt;code&gt;libs.versions.toml&lt;/code&gt;) bağımlılıkları yönetmek için. Ancak projeniz daha karmaşık hale geldiğinde ne oluyor, bir&lt;strong&gt;kompozit yapmak&lt;/strong&gt;Nerede bir bağımsız derleme (eklentimiz) bir diğerine dahil edilmelidir?&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Orada maceramız beklenmedik bir dönüm aldı. Plug-inimizi istiyorduk.&lt;code&gt;site-baker&lt;/code&gt;, kendi Gradle projesi olan, ana projemizle aynı sürüm kataloğunu kullanır. Bu makale, serimizin beşinci olan, bu sorunu nasıl çözdüğümüzü anlatır.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_1_versiyon_kataloğu_libs_versions_toml_bir_hatırlatma&quot;&gt;1. Versiyon Kataloğu (&lt;code&gt;libs.versions.toml&lt;/code&gt;) : Bir Hatırlatma&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Dosya`gradle/libs.versions.toml`Gradle&amp;#8217;in bir özelliği olup projenizin bağımlılıklarının sürüm ve koordinatlarını merkezi bir yerde tutmanızı sağlar. Genellikle dört bölüme ayrılmıştır:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;[versions]&lt;/code&gt;: Sürüm numaraları için takma ad tanımlar (örnek:`kotlin = &quot;1.9.20&quot;`).&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;[libraries]&lt;/code&gt;: Tam bağımlılıklar için takma adlar tanımlar, yukarıda tanımlanan sürümleri kullanarak (örnek:`kotlin-stdlib = { module = &quot;org.jetbrains.kotlin:kotlin-stdlib&quot;, version.ref = &quot;kotlin&quot; }`).&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;[bundles]&lt;/code&gt;: Birleştirir birden çok kütüphane tek bir takma adı altında (örnek:`jackson = [&quot;jackson-core&quot;, &quot;jackson-databind&quot;]`).&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;[plugins]&lt;/code&gt;: Gradle eklentileri için alias tanımlar.&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Bir kez tanımlandıktan sonra Gradle otomatik olarak tipize edilmiş erişimciler üretir, bu da sizin`build.gradle.kts`daha fazla okunabilir :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;dependencies {
    // Au lieu de : implementation(&quot;org.jetbrains.kotlin:kotlin-stdlib:1.9.20&quot;)
    implementation(libs.kotlin.stdlib)
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;title&quot;&gt;veri akışı sürüm kataloğu&lt;/div&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
!theme plain
file &quot;gradle/libs.versions.toml&quot; as Toml
node &quot;Gradle&quot; as G
file &quot;build.gradle.kts&quot; as BuildScript

Toml --&amp;gt; G : &quot;tarafından okunuyor&quot;
G --&amp;gt; BuildScript : &quot;libs` erişim oluşturucusunu oluşturur&quot;
BuildScript -&amp;gt; G : &quot;kullan `libs` bağımlılıkları bildirmek için&quot;
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_2_sorun_bir_bileşik_yapı_ve_ayrı_dünyalar&quot;&gt;2. Sorun: Bir Bileşik Yapı ve Ayrı Dünyalar&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Projemizin yapısı bir&lt;strong&gt;bileşik oluştur&lt;/strong&gt;. Ana proje (&lt;code&gt;thymeleaf.cheroliv.com&lt;/code&gt;) eklenti projesini içerir (&lt;code&gt;site-baker&lt;/code&gt;) komut aracılığıyla`includeBuild(&quot;site-baker&quot;)&lt;code&gt;dosyada`settings.gradle.kts&lt;/code&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;title&quot;&gt;Kompozit yapı yapısı&lt;/div&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
!theme plain
package &quot;Ana Proje&quot; {
  file &quot;settings.gradle.kts&quot; as MainSettings
  folder &quot;gradle&quot; {
    file &quot;libs.versions.toml&quot; as MainToml
  }
}

package &quot;Eklenti `site-baker` (Dahil Edilmiş Derleme)&quot; {
  file &quot;settings.gradle.kts&quot; as PluginSettings
  file &quot;build.gradle.kts&quot; as PluginBuild
}

MainSettings -&amp;gt; PluginSettings : `includeBuild(&quot;site-baker&quot;)`
PluginBuild ..&amp;gt; MainToml : **Voulait accéder à...**
note right on link: ...mais ne pouvait pas !
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Sorun, varsayılan olarak, dahil edilmiş bir derleme bir&lt;strong&gt;ayrılmış dünya&lt;/strong&gt;. Kendi yapılandırmasına, kendi yaşam döngüsüne sahiptir ve dosyayı görmez`libs.versions.toml`ana derlemenin. Bizim`plugin/build.gradle.kts`kullanmaya çalışıyordu`libs.plugins.kotlin.jvm`, ama nesne`libs`Doğru TOML dosyasından üretilemedi, bu da derleme hatalarına neden oldu.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_3_çözüm_bağımlılık_çözümlemesini_paylaşmak&quot;&gt;3. Çözüm: Bağımlılık Çözümlemesi&amp;#8217;ni Paylaşmak&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Birkaç araştırma sonrasında, çözümün Gradle&amp;#8217;in bu duruma özel olarak tasarlanmış bir özelliği olduğu ortaya çıktı :`dependencyResolutionManagement`.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Dosyada`settings.gradle.kts` du &lt;strong&gt;inklusif yapı&lt;/strong&gt;(&lt;code&gt;site-baker/settings.gradle.kts&lt;/code&gt;), Gradle&amp;#8217;ye sürüm kataloğunu nerede bulabileceğini söyleyebiliriz.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;İşte eklediğimiz yapı`site-baker/settings.gradle.kts`:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;// site-baker/settings.gradle.kts

dependencyResolutionManagement {
    repositoriesMode.set(RepositoriesMode.FAIL_ON_PROJECT_REPOS)
    repositories {
        gradlePluginPortal()
        mavenCentral()
    }
    versionCatalogs {
        create(&quot;libs&quot;) {
            from(files(&quot;../gradle/libs.versions.toml&quot;))
        }
    }
}

rootProject.name = &quot;site-baker&quot;
include(&quot;plugin&quot;)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Kritik bölümü analiz edelim :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;versionCatalogs {
    create(&quot;libs&quot;) { // Crée un catalogue nommé &#39;libs&#39;
        from(files(&quot;../gradle/libs.versions.toml&quot;)) // En utilisant ce fichier
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;create(&quot;libs&quot;)`Bir sürüm kataloğu beyan ediyoruz ve bu katalog, &#39;alias&#39; üzerinden erişilebilir olacak`libs&lt;/code&gt;.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;from(files(&quot;../gradle/libs.versions.toml&quot;))&lt;/code&gt;: Bu sihirli. Gradle&amp;#8217;a, bu catalogun kaynağının bu dizindeki TOML dosyası olduğunu söyleriz.&lt;code&gt;gradle&lt;/code&gt; du &lt;strong&gt;ana proje&lt;/strong&gt;(&lt;code&gt;../&lt;/code&gt;)&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Bu yapılandırma ile, derleme`site-baker`Şimdi, ana proje&amp;#8217;nin sürüm kataloğunu kullanması gerektiğini biliyor. Nesne`libs`doğru şekilde oluşturulur, ve bağımlılıklar beklendiği gibi çözülür.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_4_sonuç_yönetilmiş_bileşenli_yapıların_gücü&quot;&gt;4. Sonuç: Yönetilmiş bileşenli yapıların gücü&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Bu deneyim zengin dersler sağladı. Versiyon kataloğu, sürdürülebilirlik için harika bir araçtır, fakat bileşik derleme senaryolarındaki davranışı her zaman doğal olarak anlaşılmaz.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Anahtar, bir dahil edilmiş derlemenin yine de bağımsız bir derleme olduğunu unutmamaktır. Sürüm kataloğu gibi yapılandırmaları paylaşmak için, Gradle tarafından sağlanan açık mekanizmaları kullanmalısınız, örneğin blok.&lt;code&gt;dependencyResolutionManagement`içinde`settings.gradle.kts&lt;/code&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Bu sorunu çözerek, derlememizi sadece daha temiz hâle getirmekle kalmayıp, aynı zamanda plugin ve ana proje arasındaki bağımlılıklar için tek bir gerçeklik kaynağı paylaşmasını sağlayarak projemizin tutarlılığını da güçlendirdik.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Bir sonraki makalede, bağımlılık yönetimimiz sağlam ve merkezi olduğuna göre, plugin&amp;#8217;imizi daha karmaşık görevler ekleyerek zenginleştirmeye devam edeceğiz.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;Sommaire&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_giriş&quot;&gt;Giriş&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_belirti_hayalet_derlemeleri&quot;&gt;Belirti: Hayalet Derlemeleri&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_araştırma_yapılandırma_önbelleği_nedir&quot;&gt;Araştırma: Yapılandırma Önbelleği nedir?&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_sorunun_nedeni_uygun_olmayan_bir_eklenti&quot;&gt;Sorunun Nedeni: Uygun Olmayan Bir Eklenti&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_geçici_çözüm_önbelleği_devre_dışı_bırak&quot;&gt;Geçici Çözüm: Önbelleği Devre Dışı Bırak&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_gerçek_çözüm_eklentiyi_uyumlu_hale_getirmek&quot;&gt;Gerçek Çözüm: Eklentiyi uyumlu hale getirmek&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div id=&quot;preamble&quot;&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;div class=&quot;title&quot;&gt;&lt;em&gt;Okuma süresi :&lt;/em&gt; 11 minutes.&lt;/div&gt;
&lt;p&gt;Hedef kitle: Daha önce &#39;sihirli&#39; veya beklenmedik derleme davranışlarıyla karşılaşmış Gradle geliştiricileri.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_giriş&quot;&gt;Giriş&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Eklenti oluşturma maceramızda`site-baker`, sıkı bir TDD yaklaşımı izledik. Her özellik test edildi, doğrulandı ve güvenle ilerledik. Ve bir gün, beklenmedik şey çıktı. Build&amp;#8217;lar hatalı davranmaya başladı. Eklenti mantığındaki veya yapılandırma dosyalarındaki değişiklikler göz ardı edilmiş gibi görünüyor ve güvenilir olan fonksiyonel testlerimiz, neden belli olmaksızın başarısız oldu.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Bu tip bir sorun inanılmazca sinir bozucu olabilir. Araç güvenilirliğinin ve kodumuzun geçerliliğinin sorgulanmasına yol açar. Yoğun bir hata ayıklama oturumu sonrası, suçlu belirlenmiştir:&lt;strong&gt;Gradle yapılandırma önbelleği&lt;/strong&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_belirti_hayalet_derlemeleri&quot;&gt;Belirti: Hayalet Derlemeleri&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Sorun birden çok şekilde ortaya çıkıyor:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;Bir görevde bir karakter dizisini değiştiriyordum`println`, ancak eski dize çalışma zamanında görüntülenmeye devam ediyordu.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Ben dosyamda bir değeri değiştiriyordum`managed-jbake-context.yml`, ancak eklenti, dosyanın değiştirilmemiş gibi davranıyordu.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Uçusta test projeleri oluşturan işlevsel testler, eklenti yeni oluşturulan yapılandırma dosyalarını algılamadığı için başarısız oluyordu.&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Her şey, Gradle&amp;#8217;in derlemenin &quot;fantom versiyonu&quot; gibi bir sürümünü çalıştırdığını gösteriyormuş gibi ilerliyordu, en son değişikliklerimizi görmezden geliyordu.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_araştırma_yapılandırma_önbelleği_nedir&quot;&gt;Araştırma: Yapılandırma Önbelleği nedir?&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Yapılandırma önbelleği, Gradle&amp;#8217;in nispeten modern ve oldukça güçlü bir özelliğidir ve yeni sürümlerde varsayılan olarak etkindir. Amacı, derlemeleri daha hızlı hale getirmektir.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;div class=&quot;title&quot;&gt;Prensip basittir:&lt;/div&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;İlk çalıştırma sırasında, Gradle fazı yürütür de&lt;strong&gt;Konfigürasyon&lt;/strong&gt;(okuma`build.gradle.kts`, görevlerin oluşturulması, bağımlılıkların çözümü) ve bir görev grafiği oluşturur.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Bu aşamanın sonunda, Gradle&lt;strong&gt;Bu görev grafiğini serileştir.&lt;/strong&gt;onu önbelleğe alır.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Aşağıdaki çalıştırmalarda, hiçbir şey değişmediyse (derleme betikleri,&lt;code&gt;gradle.properties&lt;/code&gt;, etc.), Gradle&lt;strong&gt;Tamamen yapılandırma aşamasını atlar&lt;/strong&gt;ve önbelleğe alınmış görev grafiğini yeniden kullanır.&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Zaman kazancı büyük projelerde spektaküler. Ancak bu performans bir maliyet getirir: eklentilerin nasıl yazılması gerektiği hakkında katı kurallar getirir.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;title&quot;&gt;Yapılandırma önbelleği yaşam döngüsü&lt;/div&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
start
:Première exécution;
:Phase de Configuration;
:Création du graphe de tâches;
:Mise en cache du graphe;
:Phase d&#39;Exécution;
end

start
:Exécution suivante;
if (Cache valide ?) then (oui)
  :Restauration du graphe depuis le cache;
  note right
    La phase de configuration
    est sautée !
  end note
else (non)
  :Phase de Configuration;
  :Mise à jour du cache;
endif
:Phase d&#39;Exécution;
stop
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_sorunun_nedeni_uygun_olmayan_bir_eklenti&quot;&gt;Sorunun Nedeni: Uygun Olmayan Bir Eklenti&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Bizim eklentimiz`site-baker`bilmeden, yapılandırma önbelleğinin çeşitli kurallarını ihlal ediyordu. Bir görev grafiğinin seri hale getirilebilmesi için, görevler karmaşık nesnelere referans içermemelidir, örneğin nesne gibi.`Project`veya dosyaları çalıştırma aşamasında rasgele okumak.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Ana hatamız, görev yürütme mantığı içinde YAML dosyasının içeriğini doğrudan okumaktı, uzantımızda saklanan yol referansını kullanarak. Bu yaklaşım, Gradle dosya içeriğinin değişip değişmediğini bu okuma bir olarak modellenmediği takdirde bilemez olduğundan cache ile uyumsuzdur.&lt;strong&gt;görev girişi&lt;/strong&gt;Task Input&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_geçici_çözüm_önbelleği_devre_dışı_bırak&quot;&gt;Geçici Çözüm: Önbelleği Devre Dışı Bırak&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;En hızlı çözüm, yapılandırma önbelleğini devre dışı bırakmaktı. Dosyaya aşağıdaki satırı eklemek yeterli.&lt;code&gt;gradle.properties`plugini kullanan proje (veya bizim durumumuzda, test projesini)`site-baker&lt;/code&gt;).&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-properties hljs&quot; data-lang=&quot;properties&quot;&gt;# site-baker/gradle.properties
org.gradle.configuration-cache=false&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Anında, derlemeler normal davranışlarını geri kazandı. Her çalıştırma yapılandırma aşamasını yeniden başlatıyordu ve değişikliklerimiz dikkate alınıyordu.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Ancak, bu geçici bir çözümdür, kalıcı bir çözüm değildir. Performansı düşürür ve eklentimizin temel sorununu çözmez.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_gerçek_çözüm_eklentiyi_uyumlu_hale_getirmek&quot;&gt;Gerçek Çözüm: Eklentiyi uyumlu hale getirmek&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Bir eklenti, modern Gradle ekosisteminin iyi bir vatandaşı olmak için yapılandırma önbelleğiyle uyumlu olmalıdır. Bu, görevlerimize veri akışının nasıl olacağını yeniden düşünmemizi gerektirir.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Anahtar, kullanmak için&lt;strong&gt;Sağlayıcı API&amp;#8217;leri&lt;/strong&gt;Gradle. Doğrudan değer geçirmek yerine (bir`String` ou un &lt;code&gt;File&lt;/code&gt;) görevlerimize, geçirmemiz gereken`Property&amp;lt;T&amp;gt;`veya &amp;lt;/think&amp;gt; veya`Provider&amp;lt;T&amp;gt;`.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;div class=&quot;title&quot;&gt;İşte refaktoring planı :&lt;/div&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Görev girişlerini beyan edin:&lt;/strong&gt;YAML dosyasını ayrıştıran görev, bu dosyayı bir giriş olarak beyan etmelidir. Bunun için anotasyondan yararlanılır.&lt;code&gt;@InputFile&lt;/code&gt;.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Kullan &lt;code&gt;Property&lt;/code&gt; ve &lt;code&gt;Provider&lt;/code&gt;:&lt;/strong&gt;Değeri`configFile`özelliğe bağlanacak`configPath`DSL uzantımızdan. Gradle böylece verinin kaynağını izleyebilir.&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;[source,kotlin] ---- // Eklentide tasks.register&amp;lt;MyTask&amp;gt;(&quot;myTask&quot;) { configFile.set(extension.configPath.flatMap { project.layout.projectDirectory.file(it) }) } ----&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;Sommaire&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_giriş&quot;&gt;Giriş&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_1_bağlam_bizim_eklentimiz_site_baker&quot;&gt;1. Bağlam : Bizim Eklentimiz `site-baker&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_2_kotlinde_yapılandırma_modellemesi&quot;&gt;2. Kotlin&amp;#8217;de Yapılandırma Modellemesi&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_3_jacksonın_build_gradle_ktse_entegrasyonu&quot;&gt;3. Jackson&amp;#8217;ın `build.gradle.kts&amp;#8217;e entegrasyonu&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_4_tdd_yaklaşımı_yaml_parsingini_test_etme&quot;&gt;4. TDD Yaklaşımı: YAML Parsing&amp;#8217;ini Test Etme&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_4_1_birim_testi_yamli_kotlin_nesnesine_eşleme&quot;&gt;4.1. Birim Testi: YAML&amp;#8217;i Kotlin Nesnesine Eşleme&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_4_2_fonksiyonel_test_yapılandırma_dosyasının_okumasını_doğrula&quot;&gt;4.2. Fonksiyonel Test: Yapılandırma Dosyasının Okumasını Doğrula&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_5_parsing_akışı_görselleştirme&quot;&gt;5. Parsing Akışı Görselleştirme&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_sonuç&quot;&gt;Sonuç&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div id=&quot;preamble&quot;&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;div class=&quot;title&quot;&gt;&lt;em&gt;Okuma süresi :&lt;/em&gt; 12 dakika&lt;/div&gt;
&lt;p&gt;Hedef kitle: karmaşık yapılandırmaları yönetmek isteyen orta seviye Gradle geliştiricileri&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_giriş&quot;&gt;Giriş&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Gradle eklenti geliştirme yaparken, karmaşık yapılandırma yönetimi yaygın bir görevdir. DSL&amp;#8217;yi yüzlerce özellikle yükmelmek yerine, yapılandırmayı YAML gibi harici bir dosyada tanımlamak genellikle daha temiz ve sürdürülebilirdir. Bu makale, güçlü Jackson kütüphanesini kullanarak YAML dosyalarını Kotlin nesnelerine dönüştürmeyi entegre etme konusunda size rehberlik eder ve eklentimizin sağlamlığını garanti altına almak için katı bir TDD yaklaşımı benimser.&lt;code&gt;site-baker&lt;/code&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_1_bağlam_bizim_eklentimiz_site_baker&quot;&gt;1. Bağlam : Bizim Eklentimiz `site-baker&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Eklentimiz`site-baker`bir statik sitesinin üretimini ve dağıtımını otomatikleştirmek için tasarlanmıştır. Bir YAML yapılandırma dosyasını okuması gerekir.&lt;code&gt;managed-jbake-context.yml&lt;/code&gt;) kaynak yolları, dağıtım hedefleri ve Git kimlikleri gibi bilgileri elde etmek için.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Ayrıştırıcı olarak istediğimiz YAML yapılandırması şu şekilde:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-yaml hljs&quot; data-lang=&quot;yaml&quot;&gt;bake:
  srcPath: &quot;./site/jbake&quot;
  destDirPath: &quot;bake&quot;
  cname: &quot;cheroliv.com&quot;
pushPage:
  from: &quot;bake&quot;
  to: &quot;cvs&quot;
  repo:
    name: &quot;trainings&quot;
    repository: &quot;https://github.com/pages-content/pages-content.github.io.git&quot;
    credentials:
      username: &quot;USERNAME&quot;
      password: &quot;SECRET_TOKEN&quot;
  branch: &quot;main&quot;
  message: &quot;cheroliv.com&quot;
# ... autres configurations (pushMaquette, supabase, etc.)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_2_kotlinde_yapılandırma_modellemesi&quot;&gt;2. Kotlin&amp;#8217;de Yapılandırma Modellemesi&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Parsing öncesi, Kotlin&amp;#8217;te veri yapımızı tanımlamalıyız. Jackson, bu sınıfları kullanarak YAML içeriğini otomatik olarak eşleyecek.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;// plugin/src/main/kotlin/com/cheroliv/site/baker/data/SiteConfiguration.kt
package com.cheroliv.site.baker.data

import com.fasterxml.jackson.databind.ObjectMapper
import com.fasterxml.jackson.dataformat.yaml.YAMLFactory
import com.fasterxml.jackson.module.kotlin.readValue
import com.fasterxml.jackson.module.kotlin.registerKotlinModule

fun parseSiteConfiguration(yaml: String): SiteConfiguration {
    val mapper = ObjectMapper(YAMLFactory()).registerKotlinModule()
    return mapper.readValue(yaml)
}

data class GitPushConfiguration(
    val from: String = &quot;&quot;,
    val to: String = &quot;&quot;,
    val repo: RepositoryConfiguration = RepositoryConfiguration(),
    val branch: String = &quot;&quot;,
    val message: String = &quot;&quot;,
)

data class RepositoryConfiguration(
    val name: String = &quot;&quot;,
    val repository: String = &quot;&quot;,
    val credentials: RepositoryCredentials = RepositoryCredentials(),
) {
    companion object {
        const val ORIGIN = &quot;origin&quot;
        const val CNAME = &quot;CNAME&quot;
        const val REMOTE = &quot;remote&quot;
    }
}

data class RepositoryCredentials(val username: String = &quot;&quot;, val password: String = &quot;&quot;)

data class SiteConfiguration(
    val bake: BakeConfiguration = BakeConfiguration(),
    val pushPage: GitPushConfiguration = GitPushConfiguration(),
    val pushMaquette: GitPushConfiguration = GitPushConfiguration(),
    val pushSource: GitPushConfiguration? = null,
    val pushTemplate: GitPushConfiguration? = null,
    val supabase: SupabaseContactFormConfig? = null
)

data class BakeConfiguration(
    val srcPath: String = &quot;&quot;,
    val destDirPath: String = &quot;&quot;,
    val cname: String? = null,
)

// ... (autres data classes pour Supabase, si nécessaire)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Fonksiyon`parseSiteConfiguration`bu, deserileşme için giriş noktamız. Kullanır`ObjectMapper`Jackson&amp;#8217;ın, yapılandırılmış ile`YAMLFactory`YAML formatı için ve`registerKotlinModule()`Kotlin&amp;#8217;in özelliklerini (özelliklerin varsayılan değerleri gibi) desteklemek için.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_3_jacksonın_build_gradle_ktse_entegrasyonu&quot;&gt;3. Jackson&amp;#8217;ın `build.gradle.kts&amp;#8217;e entegrasyonu&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Jackson kullanmak için, gerekli bağımlılıkları eklememiz gerekiyor`build.gradle.kts`bizim modülünün`plugin`(empty)&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;// plugin/build.gradle.kts
dependencies {
    // Jackson for YAML parsing
    implementation(&quot;com.fasterxml.jackson.module:jackson-module-kotlin:2.18.3&quot;)
    implementation(&quot;com.fasterxml.jackson.dataformat:jackson-dataformat-yaml:2.18.3&quot;)

    // ... autres dépendances
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Kullanıyoruz`jackson-module-kotlin`Kotlin desteği için ve`jackson-dataformat-yaml`YAML formatının yönetimi için.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_4_tdd_yaklaşımı_yaml_parsingini_test_etme&quot;&gt;4. TDD Yaklaşımı: YAML Parsing&amp;#8217;ini Test Etme&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Şimdi, ayrıştırma mantığımızı doğrulamak için TDD&amp;#8217;yi uygulayalım.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_4_1_birim_testi_yamli_kotlin_nesnesine_eşleme&quot;&gt;4.1. Birim Testi: YAML&amp;#8217;i Kotlin Nesnesine Eşleme&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Bir birim testi ile başlıyoruz`SiteBakerPluginTest.kt`fonksiyonu kontrol etmek için`parseSiteConfiguration`YAML dizesini bir nesneye doğru bir şekilde dönüştürebilir`SiteConfiguration`.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;// plugin/src/test/kotlin/com/cheroliv/site/baker/SiteBakerPluginTest.kt
@Test
fun `can map configuration text to SiteConfiguration object`() {
    val yamlString = &quot;../../managed-jbake-context.yml&quot;
        .run(::File)
        .readText()
        .trimIndent()

    val config: SiteConfiguration = parseSiteConfiguration(yamlString)

    assertEquals(&quot;cheroliv.com&quot;, config.bake.cname)
    assertEquals(&quot;main&quot;, config.pushPage.branch)
    assertEquals(&quot;https://github.com/pages-content/pages-content.github.io.git&quot;, config.pushPage.repo.repository)
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Bu test dosyanın içeriğini okur`managed-jbake-context.yml`(testin geçerli olması için mevcut olmalıdır) ve nesne üzerinde iddialar yapar`SiteConfiguration`Sonuçlanan. YAML anahtar değerlerinin doğru şekilde eşlendiğini doğrular.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_4_2_fonksiyonel_test_yapılandırma_dosyasının_okumasını_doğrula&quot;&gt;4.2. Fonksiyonel Test: Yapılandırma Dosyasının Okumasını Doğrula&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Eklentinin DSL üzerinden yapılandırma dosyasını okuyabildiğini ve analiz işleminin gerçek bir Gradle ortamında çalıştığından emin olmak için, bir fonksiyonel test ekliyoruz`SiteBakerPluginFunctionalTest.kt`.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Bu test, gerçek bir projede pluginin çalıştırılmasını simüle ettiği için çok önemlidir. Olmalı&lt;strong&gt;hermetik&lt;/strong&gt;, yani kendisi dosyayı oluşturmalıdır`managed-jbake-context.yml`kontrollü bir içerikle, testin tekrarlanabilirliğini ve izolasyonunu sağlamak için.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;// plugin/src/functionalTest/kotlin/com/cheroliv/site/baker/SiteBakerPluginFunctionalTest.kt
@Test
fun `config file contains good data`(){
    val configContent = configFile.readText(UTF_8)
    // Vérifications comme dans vos commentaires
    assertTrue(configContent.contains(&quot;bake&quot;))
    assertTrue(configContent.contains(&quot;pushPage&quot;))
    assertTrue(configContent.contains(&quot;repository&quot;))
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Bu fonksiyonel test, testin geçici dizinine kopyalanan yapılandırma dosyasının beklenen verileri içerdiğini doğrular. YAML&amp;#8217;i doğrudan Kotlin nesnesine ayrıştırmazsa da, dosyanın varlığını ve içeriğini doğrular; bu, eklenti tarafından ayrıştırma öncesinde gereken temel bir adımdır.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_5_parsing_akışı_görselleştirme&quot;&gt;5. Parsing Akışı Görselleştirme&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Aşağıdaki diyagram, YAML yapılandırması ayrıştırılırken veri akışı ve etkileşimlerini gösterir :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
actor &quot;Gradle kullanıcı&quot; as User
participant &quot;build.gradle.kts&quot; as BuildScript
participant &quot;SiteBakerPlugin&quot; as Plugin
participant &quot;Site Uzantısı&quot; as Extension
participant &quot;managed-jbake-context.yml&quot; as ConfigFile
participant &quot;parseSiteConfiguration()&quot; as Parser
participant &quot;SiteConfiguration (Kotlin nesnesi)&quot; as KotlinObject

User -&amp;gt; BuildScript : Applique le plugin et configure le DSL
BuildScript -&amp;gt; Plugin : apply()
Plugin -&amp;gt; Extension : Crée et enregistre l&#39;extension &#39;site&#39;
User -&amp;gt; BuildScript : site { configPath = &quot;...&quot; }
BuildScript -&amp;gt; Extension : Définit configPath

Plugin -&amp;gt; ConfigFile : Lit le fichier (via configPath)
ConfigFile --&amp;gt; Plugin : Contenu YAML
Plugin -&amp;gt; Parser : Appelle parseSiteConfiguration(yamlString)
Parser -&amp;gt; KotlinObject : Mappe le YAML en objet SiteConfiguration
KotlinObject --&amp;gt; Plugin : Retourne l&#39;objet configuré

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_sonuç&quot;&gt;Sonuç&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;TDD yaklaşımını izleyerek, Jackson kütüphanesini YAML yapılandırma dosyalarını Kotlin nesnelerine ayrıştırmak için başarıyla Gradle eklentimizle entegre ettik. Bu yöntem, bize şunları sağladı:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Açıkça modellemek&lt;/strong&gt;Kotlin veri sınıflarıyla yapılandırma.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Parsing mantığını doğrula&lt;/strong&gt;hedefli birim testleri ile&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Entegrasyonu sağlamak&lt;/strong&gt;gerçek Gradle ortamında, kapalı fonksiyonel testler sayesinde.&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Bu sağlam temel, bu yapıya dayalı özelliklerle eklentimizi genişletirken bize büyük güven sağlarken, kodun sürdürülebilirliğini ve sağlamlığını da garanti altına alır. YAML ayrıştırma artık eklentimizin güvenilir ve test edilmiş bir özelliğidir.&lt;code&gt;site-baker&lt;/code&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;Table of Contents&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_proje_başlatması&quot;&gt;Proje Başlatması&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_2_i̇lk_tdd_döngümüz_bir_görev_kaydetmek&quot;&gt;2. İlk TDD döngümüz : Bir görev kaydetmek&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_2_1_i̇lk_test_başarısız_olan_test&quot;&gt;2.1. İlk Test (Başarısız Olan Test)&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_2_2_kod_sonra_testi_geçir&quot;&gt;2.2. Kod Sonra (Testi Geçir)&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_3_i̇kinci_dönem_tdd_dsl_uzantısı_ekle&quot;&gt;3. İkinci Dönem TDD : DSL Uzantısı Ekle&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_3_1_i̇lk_test&quot;&gt;3.1. İlk Test&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_3_2_kodu_sonra&quot;&gt;3.2. Kodu Sonra&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_4_fonksiyonel_test_entegrasyonu_doğrula&quot;&gt;4. Fonksiyonel Test: Entegrasyonu Doğrula&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_4_1_entegrasyon_testi_denetlenen_ortam_oluşturma&quot;&gt;4.1. Entegrasyon Testi: Denetlenen Ortam Oluşturma&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_4_2_mantığı_sonlandır&quot;&gt;4.2. Mantığı Sonlandır&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_sonuç&quot;&gt;Sonuç&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div id=&quot;preamble&quot;&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Bu makalede, Gradle eklentisi için sağlam bir geliştirme temeli oluşturmanın nasıl yapılacağını, Test Odaklı Geliştirme (TDD - Test-Driven Development) yaklaşımını kullanarak inceleyeceğiz. Bu yöntem, kodun sağlam, sürdürülebilir ve gereksinimlere tam olarak ilk etapta uyanmasını sağlar.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_proje_başlatması&quot;&gt;Proje Başlatması&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Gradle, komut sayesinde yeni bir eklenti oluşturmayı çok kolaylaştırır.&lt;code&gt;gradle init&lt;/code&gt;. Kotlin ile bir &quot;Gradle Plugin&quot; oluşturmaya karar verdiğimizde, iki önemli test türü de bulunan kullanıma hazır bir proje yapısı elde ederiz:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Birim Testleri :&lt;/strong&gt;bulunan`src/test`, bu pluginimizdeki izole bileşenlerini doğrulamamızı sağlar, örneğin bir görevin iç mantığı veya bir uzantının yapılandırması gibi. Hızlıdır ve Gradle&amp;#8217;in tam bir yürütmesini gerektirmez.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Fonksiyonel Testler :&lt;/strong&gt;bulunan`src/functionalTest`, kullanırlar`GradleRunner`bir Gradle derlemesi tam olarak çalıştırmak için geçici bir test projesi içinde. Bu, eklentinin gerçek davranışını kontrol edilmiş bir ortamda doğrulamamıza olanak tanır.&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_2_i̇lk_tdd_döngümüz_bir_görev_kaydetmek&quot;&gt;2. İlk TDD döngümüz : Bir görev kaydetmek&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;İlk gereksinimimiz basittir: eklenti bir isimlendirilmiş görevi kaydetmeli`printSiteConfig`.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_2_1_i̇lk_test_başarısız_olan_test&quot;&gt;2.1. İlk Test (Başarısız Olan Test)&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;TDD&amp;#8217;ye göre, ilk olarak bu görevin varlığını kontrol eden bir test yazıyoruz. İçinde`SiteBakerPluginTest.kt`(birim test dosyamız), ekliyoruz :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;@Test
fun `plugin registers task`() {
    // Créer un projet de test en mémoire
    val project = ProjectBuilder.builder().build()
    project.plugins.apply(&quot;com.cheroliv.site-baker&quot;)

    // Vérifier que la tâche a bien été enregistrée
    assertNotNull(project.tasks.findByName(&quot;printSiteConfig&quot;))
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Bu test başarısız, çünkü hâlâ eklentimizde hiçbir kod yazmadık.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_2_2_kod_sonra_testi_geçir&quot;&gt;2.2. Kod Sonra (Testi Geçir)&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Şimdi, gerekli minimum kodu yazıyoruz içinde`SiteBakerPlugin.kt`testin geçebilmesi için :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;class SiteBakerPlugin: Plugin&amp;lt;Project&amp;gt; {
    override fun apply(project: Project) {
        // Enregistrer une tâche simple
        project.tasks.register(&quot;printSiteConfig&quot;) { task -&amp;gt;
            // ... la logique de la tâche viendra plus tard
        }
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Testleri yeniden başlatıyoruz ve geçiyorlar. İlk işlevimiz onaylandı.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_3_i̇kinci_dönem_tdd_dsl_uzantısı_ekle&quot;&gt;3. İkinci Dönem TDD : DSL Uzantısı Ekle&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Aşağıdaki gereklilik, kullanıcıların bir DSL bloğu üzerinden eklentimizi yapılandırmalarına olanak sağlamaktır.&lt;code&gt;build.gradle.kts&lt;/code&gt;. Biz bir blok istiyoruz`site { &amp;#8230;&amp;#8203; }`bir yapılandırma yolu belirtebileceğiniz yer.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_3_1_i̇lk_test&quot;&gt;3.1. İlk Test&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Bir test ekliyoruz, uzantının çalıştığını doğrulamak için.`site`Doğru şekilde kaydedilir ve ona bir değer atanabilir.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;@Test
fun `plugin registers extension`() {
    val project = ProjectBuilder.builder().build()
    project.plugins.apply(&quot;com.cheroliv.site-baker&quot;)

    // Récupérer l&#39;extension et lui affecter une valeur
    project.extensions
        .findByType(SiteExtension::class.java)!!
        .configPath
        .set(&quot;config.yml&quot;)

    // Vérifier que la valeur a bien été prise en compte
    assertEquals(
        &quot;config.yml&quot;,
        project.extensions.findByType(SiteExtension::class.java)?.configPath?.get()
    )
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Bu test başarısız oluyor çünkü ne sınıf`SiteExtension`Eklenti kaydı da yoktur.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_3_2_kodu_sonra&quot;&gt;3.2. Kodu Sonra&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Sınıfı oluşturuyoruz`SiteBakerExtension.kt`ve güncelliyoruz`SiteBakerPlugin.kt` :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;// SiteBakerExtension.kt
open class SiteExtension @Inject constructor(objects: ObjectFactory) {
    val configPath: Property&amp;lt;String&amp;gt; = objects.property(String::class.java)
}

// SiteBakerPlugin.kt
class SiteBakerPlugin: Plugin&amp;lt;Project&amp;gt; {
    override fun apply(project: Project) {
        // Enregistrer l&#39;extension
        val extension = project.extensions.create(&quot;site&quot;, SiteExtension::class.java)

        project.tasks.register(&quot;printSiteConfig&quot;) { task -&amp;gt;
            task.doLast {
                // On utilisera l&#39;extension plus tard
            }
        }
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Testler yeniden geçiyor.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_4_fonksiyonel_test_entegrasyonu_doğrula&quot;&gt;4. Fonksiyonel Test: Entegrasyonu Doğrula&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Şimdi birimler test edildiğinde, her şeyin gerçek bir derlemede birlikte çalıştığından emin olmamız gerekiyor. Bu, fonksiyonel testin rolü`SiteBakerPluginFunctionalTest.kt`.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_4_1_entegrasyon_testi_denetlenen_ortam_oluşturma&quot;&gt;4.1. Entegrasyon Testi: Denetlenen Ortam Oluşturma&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Bu test, eklentimizi kullanan gerçek bir projeyi simüle edecek. Güvenilir olabilmesi için&lt;strong&gt;hermetik&lt;/strong&gt;, yani, sistemde mevcut olan dosyalara bağımlı olmamalıdır. Kendisi gerekli tüm koşulları oluşturmalıdır.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Test şu şekilde:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;Bir oluştur`build.gradle.kts`nosu plugini ve DSL&amp;#8217;ini kullanan testin&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Yapılandırma dosyasını oluştur&lt;/strong&gt; (&lt;code&gt;managed-jbake-context.yml&lt;/code&gt;) eklenti okumasını beklediği. Bu, testin sağlamlığı için kritik bir adımdır.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Görevi çalıştır`printSiteConfig`vasıtasıyla`GradleRunner`.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Derlemenin çıktısının doğru olduğunu kontrol et.&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Bu yapılandırma dosyasını her çalıştırmada kopyalayarak veya oluşturarak testin &amp;#8230;&amp;#8203; olduğundan emin oluruz.&lt;strong&gt;tekrar edilebilir&lt;/strong&gt;ve dış bir duruma bağlı değildir. Bu, dosya okuma ile ilgili olabilecek regresyonlara karşı testlerimizi güvence altına alır.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;@Test fun `can run task with DSL`() {
    // 1. Créer un build.gradle.kts de test
    buildFile.writeText(&quot;&quot;&quot;
        plugins { id(&quot;com.cheroliv.site-baker&quot;) }
        site { configPath = &quot;managed-jbake-context.yml&quot; }
    &quot;&quot;&quot;.trimIndent())

    // 2. Créer le fichier de configuration pour un test contrôlé
    val configFile = File(projectDir, &quot;managed-jbake-context.yml&quot;)
    configFile.writeText(&quot;site: { title: &#39;Mon Site de Test&#39; }&quot;) // Contenu YAML simple

    // 3. Exécuter la build
    val runner = GradleRunner.create()
    runner.withPluginClasspath()
    runner.withArguments(&quot;printSiteConfig&quot;)
    runner.withProjectDir(projectDir) // Spécifier le répertoire du projet de test
    val result = runner.build()

    // 4. Vérifier la sortie
    assertTrue(result.output.contains(&quot;Site config path: managed-jbake-context.yml&quot;))
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Görev tamamlanana kadar bu test başarısız olacak`printSiteConfig`Gerçekte uzantının değerini kullanmayacaktır.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_4_2_mantığı_sonlandır&quot;&gt;4.2. Mantığı Sonlandır&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Görev içinde güncelliyoruz`SiteBakerPlugin.kt`yapılandırılmış değeri görüntülemek için :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;project.tasks.register(&quot;printSiteConfig&quot;) { task -&amp;gt;
    task.doLast {
        println(&quot;Site config path: ${extension.configPath.get()}&quot;)
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Tüm testler, birim ve fonksiyonel, artık geçiyor.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_sonuç&quot;&gt;Sonuç&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;TDD yaklaşımını izleyerek, bir eklenti artımlı ve güvenli bir şekilde inşa ettik. Her küçük özellik, bir test tarafından hemen doğrulanır — hızlı birim testlerinden tüm entegrasyonu doğrulayan fonksiyonel testlere kadar.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Testlerimizi fonksiyonel hâle getirirken özen göstererek&lt;strong&gt;hermetyk&lt;/strong&gt;— özellikle gerekli yapılandırma dosyalarını programatik olarak oluştururken — bir son derece sağlam güvenlik ağı oluşturuyoruz. Bu titizlik, regresyonlara etkili bir şekilde karşı koruma sağlar ve daha karmaşık özellikler eklemek için bize büyük güven verir, daha sonra YAML yapılandırma dosyasının ayrıştırılması gibi.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Bu sağlam test tabanı, eklentinin bakımı ve gelecekteki gelişimi için en değerli varlıktır.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;Sommaire&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_giriş&quot;&gt;Giriş&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_adım_1_proje_asistanını_başlat&quot;&gt;Adım 1: Proje asistanını başlat&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_adım_2_oluşturulan_yapıyı_anlama&quot;&gt;Adım 2: Oluşturulan yapıyı anlama&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_önemli_dosyalar_ve_klasörler&quot;&gt;önemli dosyalar ve klasörler&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_giriş&quot;&gt;Giriş&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;div class=&quot;title&quot;&gt;Hedef kitle : Gradle ile başlangıç seviyesinden orta seviyeye kadar geliştirici.&lt;/div&gt;
&lt;p&gt;Yeni bir Gradle eklentisi projesi başlatmak korkutucu gelebilir. Şükranla, Gradle güçlü etkileşimli bir asistan sağlar, görev`init`, bir projeye tam, temiz ve hemen kullanılabilir bir yapı oluşturur. Bu rehber, bu aracı nasıl kullanacağınızı göstererek sağlıklı bir eklenti tabanı oluşturmanızı sağlayacak, yapısını açıklayacak ve ilk derleme görevlerini nasıl başlatacağınızı gösterecektir.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_adım_1_proje_asistanını_başlat&quot;&gt;Adım 1: Proje asistanını başlat&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Komut`gradle init`başlangıç noktasıdır. Komut satırı bir asistan başlatır ve projeyi yapılandırmak için size bir dizi soru sorar.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Terminalinizi boş bir klasörde açın ve çalıştırın:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;gradle init&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Asistan size yol gösterecek. İşte bir Kotlin ile yazılmış Gradle eklentisi için yapmanız gereken seçenekler:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Oluşturulacak proje türünü seçin:&lt;/strong&gt;Seçin`Gradle plugin`.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Uygulama dili seçin:&lt;/strong&gt;Seçin`Kotlin`.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Derleme betiği DSL&amp;#8217;ini seçin:&lt;/strong&gt;seçiniz`Kotlin`.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Proje adı:&lt;/strong&gt;Projeniz için bir isim girin (örnek:`site-baker`)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Eklenti kimliği:&lt;/strong&gt;Eklentiniz için benzersiz bir kimlik verin (örn:`com.cheroliv.site-baker`)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Plugin sınıf:&lt;/strong&gt;Uygulama sınıfının adını belirtin (örnek:`com.cheroliv.SiteBakerPlugin`).&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Tamamlandıktan sonra, Gradle tam bir dosya ağacı oluşturur.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;title&quot;&gt;İlk başlatma süreci diyagramı&lt;/div&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
start
:Lancer `gradle init`;
:Choisir &quot;Gradle eklentisi&quot;;
:Choisir &quot;Kotlin&quot; (langage);
:Choisir &quot;Kotlin&quot; (DSL);
:Saisir nom, ID, et classe;
:Projet généré;
stop
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_adım_2_oluşturulan_yapıyı_anlama&quot;&gt;Adım 2: Oluşturulan yapıyı anlama&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Asistan, çok modüllü bir proje yapısı oluşturarak, ana projeyi eklenti kaynak kodundan ayırır.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-text hljs&quot; data-lang=&quot;text&quot;&gt;.
├── gradle/
│   └── wrapper/
│       ├── gradle-wrapper.jar
│       └── gradle-wrapper.properties
├── gradlew
├── gradlew.bat
├── plugin/
│   ├── build.gradle.kts
│   └── src/
│       ├── main/
│       │   └── kotlin/
│       │       └── com/cheroliv/SiteBakerPlugin.kt
│       ├── test/
│       │   └── kotlin/
│       │       └── com/cheroliv/SiteBakerPluginTest.kt
│       └── functionalTest/
│           └── kotlin/
│               └── com/cheroliv/SiteBakerPluginFunctionalTest.kt
└── settings.gradle.kts&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_önemli_dosyalar_ve_klasörler&quot;&gt;önemli dosyalar ve klasörler&lt;/h3&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;settings.gradle.kts&lt;/code&gt;: Bu dosya, kök dizinde derleme dahil edilmesi gereken modülleri tanımlar. Burada, alt projeyi ekler.&lt;code&gt;plugin&lt;/code&gt;.&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;[source,kotlin] ---- rootProject.name = &quot;site-baker include(&quot;plugin&quot;) ----&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;Sommaire&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_giriş&quot;&gt;Giriş&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_1_jdk_gradlein_motoru&quot;&gt;1. JDK: Gradle&amp;#8217;in motoru&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_hangi_sürümü_seçmeliyim&quot;&gt;Hangi sürümü seçmeliyim?&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_installation_via_sdkman_önerilen&quot;&gt;Installation via SDKMAN! (Önerilen)&lt;/a&gt;
&lt;ul class=&quot;sectlevel3&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_sdkman_kurun&quot;&gt;&lt;strong&gt;SDKMAN! kurun&lt;/strong&gt;&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_jdknın_bir_sürümünü_kurmak&quot;&gt;&lt;strong&gt;JDK&amp;#8217;nın bir sürümünü kurmak&lt;/strong&gt;&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_kurulumu_kontrol_et&quot;&gt;&lt;strong&gt;Kurulumu kontrol et&lt;/strong&gt;&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_2_ide_intellij_idea&quot;&gt;2. IDE: IntelliJ IDEA&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_3_gradle_derleme_aracı&quot;&gt;3. Gradle: Derleme aracı&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_sdkman_üzerinden_kurulum&quot;&gt;SDKMAN! üzerinden kurulum&lt;/a&gt;
&lt;ul class=&quot;sectlevel3&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_gradleı_kur&quot;&gt;&lt;strong&gt;Gradle&amp;#8217;ı kur&lt;/strong&gt;&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_kurulumu_kontrol_et_2&quot;&gt;Kurulumu kontrol et&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_4_jbake_statik_site_oluşturucu&quot;&gt;4. JBake : Statik site oluşturucu&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_sdkman_üzerinden_kurulum_2&quot;&gt;SDKMAN! üzerinden kurulum&lt;/a&gt;
&lt;ul class=&quot;sectlevel3&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_jbakei_kur&quot;&gt;&lt;strong&gt;JBake&amp;#8217;i kur&lt;/strong&gt;&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_kurulumu_kontrol_et_3&quot;&gt;Kurulumu kontrol et&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_5_gradle_wrapper_mutlak_iyi_uygulama&quot;&gt;5. Gradle Wrapper: Mutlak iyi uygulama&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_6_docker_ve_portainer_tekrarlanabilir_oluşumlar_i̇çin_i̇steğe_bağlı&quot;&gt;6. Docker ve Portainer : Tekrarlanabilir Oluşumlar İçin (İsteğe Bağlı)&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_docker_engine_kurulumu&quot;&gt;Docker Engine kurulumu&lt;/a&gt;
&lt;ul class=&quot;sectlevel3&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_dockerı_resmi_komut_dosyasıyla_kurun&quot;&gt;&lt;strong&gt;Docker&amp;#8217;ı resmi komut dosyasıyla kurun :&lt;/strong&gt;&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_dockerı_sudo_kullanmadan_yönetin_önerilen&quot;&gt;&lt;strong&gt;Docker&amp;#8217;ı &lt;code&gt;sudo&lt;/code&gt; kullanmadan yönetin (önerilen) :&lt;/strong&gt;&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_portainer_gui_ile_dockerı_yönet&quot;&gt;Portainer (GUI) ile Docker&amp;#8217;ı yönet&lt;/a&gt;
&lt;ul class=&quot;sectlevel3&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_portainer_verileri_için_bir_birim_oluşturun&quot;&gt;Portainer verileri için bir birim oluşturun:&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_portainer_konteynerini_başlat&quot;&gt;Portainer konteynerini başlat :&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_sonuç&quot;&gt;Sonuç&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div id=&quot;preamble&quot;&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;div class=&quot;title&quot;&gt;&lt;em&gt;Okuma süresi :&lt;/em&gt; 9 dakika.&lt;/div&gt;
&lt;p&gt;Hedef kitle: Gradle eklenti geliştirmeye başlamak isteyen geliştiriciler&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_giriş&quot;&gt;Giriş&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Gradle eklentileri etkili bir şekilde geliştirmek için iyi yapılandırılmış bir geliştirme ortamı gereklidir. Bir iyi kurulum, zamanınızı kazandırır, öfkenizi azaltır ve derlemelerinizin tutarlılığını sağlar.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;div class=&quot;title&quot;&gt;Bu kılavuz, dört temel sütunu odaklar :&lt;/div&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;Le &lt;strong&gt;JDK&lt;/strong&gt;(Java Development Kit), çünkü Gradle ve JBake JVM&amp;#8217;de çalışırlar.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Un &lt;strong&gt;IDE&lt;/strong&gt;modern Kotlin ve Gradle için iyi destekli (IntelliJ IDEA).&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Gradle&lt;/strong&gt;Kendi, projeleri başlatmak için.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;JBake&lt;/strong&gt;, statik sitemizin motoru.&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;title&quot;&gt;Geliştirme ortamı bileşenleri&lt;/div&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
!theme plain
node &quot;Geliştirici makinesi&quot; {
  component &quot;JDK (JVM)&quot; as JDK
  component &quot;IntelliJ IDEA&quot; as IDE
  component &quot;Gradle (küresel)&quot; as Gradle
  component &quot;JBake (küresel)&quot; as JBake

  IDE --&amp;gt; JDK : utilise
  Gradle --&amp;gt; JDK : utilise
  JBake --&amp;gt; JDK : utilise
}
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_1_jdk_gradlein_motoru&quot;&gt;1. JDK: Gradle&amp;#8217;in motoru&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Gradle, Java sanal makinesi (JVM) üzerinde çalışan bir uygulamadır. Bu nedenle, bir JDK kurulumu mutlak bir gerekliliktir.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_hangi_sürümü_seçmeliyim&quot;&gt;Hangi sürümü seçmeliyim?&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Java&amp;#8217;nın LTS (Uzun Vadeli Destek) sürümünü kullanmanız önerilir. Şu anda,&lt;strong&gt;JDK 17&lt;/strong&gt; ou &lt;strong&gt;JDK 21&lt;/strong&gt;Harika seçeneklerdir.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_installation_via_sdkman_önerilen&quot;&gt;Installation via SDKMAN! (Önerilen)&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;SDKMAN!, Java ve Gradle dahil birçok SDK&amp;#8217;nın sürümlerini yönetmek için harika bir araçtır.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_sdkman_kurun&quot;&gt;&lt;strong&gt;SDKMAN! kurun&lt;/strong&gt;&lt;/h4&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;curl -s &quot;https://get.sdkman.io&quot; | bash source &quot;$HOME/.sdkman/bin/sdkman-init.sh&quot;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_jdknın_bir_sürümünü_kurmak&quot;&gt;&lt;strong&gt;JDK&amp;#8217;nın bir sürümünü kurmak&lt;/strong&gt;&lt;/h4&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;# Pour lister les versions de Java disponibles sdk list java

# Pour installer Java 17 (par exemple, la distribution Temurin)
sdk install java 17.0.8-tem&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_kurulumu_kontrol_et&quot;&gt;&lt;strong&gt;Kurulumu kontrol et&lt;/strong&gt;&lt;/h4&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;java -version&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Yüklediğiniz sürümü görmeniz gerekiyor&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_2_ide_intellij_idea&quot;&gt;2. IDE: IntelliJ IDEA&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Kotlin DSL ile Gradle eklenti geliştirme için,&lt;strong&gt;IntelliJ IDEA&lt;/strong&gt;seçilen araçtır Gradle ve Kotlin ile entegrasyonu eşsizdir.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Topluluk Sürümü :&lt;/strong&gt;Ücretsiz ve başlangıç için yeterince fazla&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Nihai Sürüm :&lt;/strong&gt;Ücretli, web ve veritabanı geliştirme için gelişmiş işlevler sunar.&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Sizin için uygun sürümü JetBrains sitesinden indirin: &lt;a href=&quot;https://www.jetbrains.com/idea/download/&quot; class=&quot;bare&quot;&gt;https://www.jetbrains.com/idea/download/&lt;/a&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;IDE dosyalarınızı otomatik olarak algılayacaktır`build.gradle.kts` et &lt;code&gt;settings.gradle.kts&lt;/code&gt;, sizin için güçlü bir otomatik tamamlama, kod içinde gezinme ve entegre hata ayıklama araçları sunuyor.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_3_gradle_derleme_aracı&quot;&gt;3. Gradle: Derleme aracı&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Ancak her proje Gradle Wrapper üzerinden kendi Gradle sürümünü kullanacaksa da, yeni projeleri başlatmak gibi görevler için Global Gradle kurulumuna sahip olmak faydalı (&lt;code&gt;gradle init&lt;/code&gt;).&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_sdkman_üzerinden_kurulum&quot;&gt;SDKMAN! üzerinden kurulum&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;JDK gibi, SDKMAN! Gradle&amp;#8217;ın kurulumunu basitleştirir.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_gradleı_kur&quot;&gt;&lt;strong&gt;Gradle&amp;#8217;ı kur&lt;/strong&gt;&lt;/h4&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;sdk install gradle&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_kurulumu_kontrol_et_2&quot;&gt;Kurulumu kontrol et&lt;/h4&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;gradle -v&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Bu komut Gradle, Kotlin, Groovy ve JDK sürümlerini görüntüleyecektir.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_4_jbake_statik_site_oluşturucu&quot;&gt;4. JBake : Statik site oluşturucu&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;JBake, kaynak dosyalarımızı (bu gibi) statik bir web sitesine dönüştürmek için kullanacağımız aractır. Yerel bir kurulum, değişiklikleri önizlemek için pratiktir.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_sdkman_üzerinden_kurulum_2&quot;&gt;SDKMAN! üzerinden kurulum&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Diğer araçlar gibi, SDKMAN! en basit yöntemdir.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_jbakei_kur&quot;&gt;&lt;strong&gt;JBake&amp;#8217;i kur&lt;/strong&gt;&lt;/h4&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;sdk install jbake&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_kurulumu_kontrol_et_3&quot;&gt;Kurulumu kontrol et&lt;/h4&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;jbake -v&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Bu komut, JBake sürümünü ve kullandığı Java ortamı bilgilerini görüntüleyecektir.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_5_gradle_wrapper_mutlak_iyi_uygulama&quot;&gt;5. Gradle Wrapper: Mutlak iyi uygulama&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Projenizi oluşturduktan sonra (bunu sonraki makalede göreceğiz), global komutu artık kullanmamalısınız.&lt;code&gt;gradle&lt;/code&gt;. Onun yerine onu kullanacaksınız&lt;strong&gt;Gradle Wrapper&lt;/strong&gt;(&lt;code&gt;./gradlew&lt;/code&gt;), projenize dahil edilmiş bir komut dosyası.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Neden?&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;yeniden üretilebilirlik:&lt;/strong&gt;Wrapper, proje üzerinde çalışan herkesin (CI/CD sunucunuz dahil) tam olarak kullanmasını garantiler.&lt;strong&gt;Gradle&amp;#8217;in aynı sürümü&lt;/strong&gt;, böylece farklı ortamlardan kaynaklanan derleme hatalarını ortadan kaldırıyor.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Basitlik :&lt;/strong&gt;Projeye katkıda bulunmak için Gradle&amp;#8217;i manuel olarak kurmanıza gerek yok.&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Depoyu klonlamak ve çalıştırmak yeterlidir.&lt;code&gt;./gradlew&lt;/code&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Tipik bir komut buna benzeyecek:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;# Ne pas faire : gradle build
# À faire :
./gradlew build&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_6_docker_ve_portainer_tekrarlanabilir_oluşumlar_i̇çin_i̇steğe_bağlı&quot;&gt;6. Docker ve Portainer : Tekrarlanabilir Oluşumlar İçin (İsteğe Bağlı)&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Bir eklenti yazmak için kesin olarak gerekli olmasa da, Docker ve Portainer modern DevOps araçlardır ve yeniden üretilebilir derlemelerin oluşturulmasını ve ortamınızın yönetimini büyük ölçüde kolaylaştırırlar.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_docker_engine_kurulumu&quot;&gt;Docker Engine kurulumu&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Docker, uygulamanızı ve bağımlılıklarını bir konteyner içinde paketlemenizi sağlar.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_dockerı_resmi_komut_dosyasıyla_kurun&quot;&gt;&lt;strong&gt;Docker&amp;#8217;ı resmi komut dosyasıyla kurun :&lt;/strong&gt;&lt;/h4&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;curl -fsSL https://get.docker.com -o get-docker.sh sudo sh get-docker.sh&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_dockerı_sudo_kullanmadan_yönetin_önerilen&quot;&gt;&lt;strong&gt;Docker&amp;#8217;ı &lt;code&gt;sudo&lt;/code&gt; kullanmadan yönetin (önerilen) :&lt;/strong&gt;&lt;/h4&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Kullanıcınızı gruba ekleyin`docker`.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;sudo usod -aG docker $USER&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;admonitionblock important&quot;&gt;
&lt;table&gt;
&lt;tr&gt;
&lt;td class=&quot;icon&quot;&gt;
&lt;i class=&quot;fa icon-important&quot; title=&quot;Important&quot;&gt;&lt;/i&gt;
&lt;/td&gt;
&lt;td class=&quot;content&quot;&gt;

&lt;/td&gt;
&lt;/tr&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;docker run hello-world&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_portainer_gui_ile_dockerı_yönet&quot;&gt;Portainer (GUI) ile Docker&amp;#8217;ı yönet&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Portainer, Docker konteynerlerinizi yönetmek için hafif bir web arayüzüdür.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_portainer_verileri_için_bir_birim_oluşturun&quot;&gt;Portainer verileri için bir birim oluşturun:&lt;/h4&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;docker volume create portainer_data&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_portainer_konteynerini_başlat&quot;&gt;Portainer konteynerini başlat :&lt;/h4&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;docker run -d -p 8000:8000 -p 9443:9443 --name portainer --restart=always -v /var/run/docker.sock:/var/run/docker.sock -v portainer_data:/data portainer/portainer-ce:latest&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Portainer arayüzünde şimdi erişebilirsiniz`https://localhost:9443`.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_sonuç&quot;&gt;Sonuç&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Ortamınız şimdi hazır! Bir JDK, en uygun IDE, Gradle ve JBake&amp;#8217;ye sahipsiniz. Docker eklendiğinde, konteynerleştirilmiş ve tekrarlanabilir derlemeler oluşturmak için de hazırsınız. Bu sağlam temel, önemli olan şeye odaklanmanızı sağlayacak: güçlü ve kullanışlı eklentilerin geliştirilmesi.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Bir sonraki makalede, komutu kullanacağız.`gradle init`İlk eklenti projemizin yapısını oluşturmak için.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;Table of Contents&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_poetry_ile_entegrasyon&quot;&gt;Poetry ile entegrasyon&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_poetry_kurulumu&quot;&gt;Poetry kurulumu&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_proje_başlatma&quot;&gt;Proje başlatma&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_bağımlılıkların_eklenmesi_ve_kurulması&quot;&gt;Bağımlılıkların eklenmesi ve kurulması&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_poetry_ile_yayın&quot;&gt;Poetry ile yayın&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_yeniden_üretilebilir_derlemeler_docker_ile&quot;&gt;Yeniden üretilebilir derlemeler Docker ile&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_dockerfile_örneği&quot;&gt;Dockerfile örneği&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_github_actionste_entegrasyon&quot;&gt;GitHub Actions&amp;#8217;te entegrasyon&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_şartlı_yayın&quot;&gt;Şartlı yayın&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_renovate_ve_dependabot_ile_bağımlılık_otomasyonu&quot;&gt;Renovate ve Dependabot ile bağımlılık otomasyonu&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_dependabot&quot;&gt;Dependabot&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_yeniden_düzenlemek&quot;&gt;Yeniden düzenlemek&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_plantuml_diagramları&quot;&gt;PlantUML diagramları&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_kullanım_durumu_gelişmiş_cicd&quot;&gt;Kullanım Durumu – Gelişmiş CI/CD&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_sıra_koşullu_yayın&quot;&gt;Sıra – Koşullu Yayın&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_durumlar_cicd_boru_hattı&quot;&gt;Durumlar – CI/CD Boru Hattı&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_dağıtım_cicd_mimarisi&quot;&gt;Dağıtım – CI/CD Mimarisi&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_sonuç&quot;&gt;Sonuç&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div id=&quot;preamble&quot;&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Bu serinin ilk iki bölümünde, şunları yapmışız: - Bir Python uygulaması için GitHub Actions ve PyPI ile işlevsel bir CI/CD hattı kuruldu. - Bu pipeline&amp;#8217;i multi-versiyon testleri, Test PyPI üzerinden aşamalı yayın ve kalite ve güvenlik araçlarıyla endüstriyel hale getirdik.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Bu üçüncü bölümde gideceğiz.&lt;strong&gt;PyPI&amp;#8217;de sadece yayınlamanın ötesinde&lt;/strong&gt;tam, güçlü ve profesyonel bir CI/CD zinciri oluşturmak için : - &lt;strong&gt;Şiir&lt;/strong&gt;modern bir paketleme ve bağımlılıkların optimize edilmiş yönetimi için - &lt;strong&gt;Docker&lt;/strong&gt;tekrarlanabilir ve çok platformlu derlemeler oluşturmak için - &lt;strong&gt;Şartlı yayın&lt;/strong&gt;release candidate&amp;#8217;ları gibi senaryoları yönetmek için - &lt;strong&gt;Otomasyon araçları&lt;/strong&gt;(Renovate, Dependabot) pipeline&amp;#8217;yi çaba harcamadan güncel tutmak için.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_poetry_ile_entegrasyon&quot;&gt;Poetry ile entegrasyon&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Poetry, eski paketleme araçlarını (setup.py, requirements.txt) yerine koyarak, bağımlılık ve derleme yönetimini merkezi bir şekilde içinde`pyproject.toml`.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_poetry_kurulumu&quot;&gt;Poetry kurulumu&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-shell hljs&quot; data-lang=&quot;shell&quot;&gt;# Installer Poetry
curl -sSL https://install.python-poetry.org | python3 -
# Vérifier la version
poetry --version&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_proje_başlatma&quot;&gt;Proje başlatma&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-shell hljs&quot; data-lang=&quot;shell&quot;&gt;# Initialiser un nouveau projet avec Poetry
poetry init
# Suivre l&#39;assistant pour renseigner : nom, version, description, licence, dépendances.&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Bu bir dosya oluşturur`pyproject.toml` :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-toml hljs&quot; data-lang=&quot;toml&quot;&gt;[tool.poetry]
name = &quot;playlist-downloader&quot;
version = &quot;0.1.0&quot;
description = &quot;CLI tool for managing YouTube playlists&quot;
authors = [&quot;Christophe Hérolivier &amp;lt;cheroliv@example.com&amp;gt;&quot;]

[tool.poetry.dependencies]
python = &quot;&amp;gt;=3.8&quot;
typer = &quot;^0.9.0&quot;
yt-dlp = &quot;^2023.7.6&quot;
google-api-python-client = &quot;^2.0.0&quot;
google-auth-oauthlib = &quot;^1.0.0&quot;

[tool.poetry.group.dev.dependencies]
pytest = &quot;^7.0&quot;
mypy = &quot;^1.0&quot;
bandit = &quot;^1.7&quot;
safety = &quot;^2.3&quot;
black = &quot;^23.0&quot;
ruff = &quot;^0.1&quot;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_bağımlılıkların_eklenmesi_ve_kurulması&quot;&gt;Bağımlılıkların eklenmesi ve kurulması&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-shell hljs&quot; data-lang=&quot;shell&quot;&gt;poetry add typer yt-dlp google-api-python-client google-auth-oauthlib
poetry add --group dev pytest mypy black bandit safety ruff&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_poetry_ile_yayın&quot;&gt;Poetry ile yayın&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Poetry yayınlamayı yerel olarak yönetir:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-shell hljs&quot; data-lang=&quot;shell&quot;&gt;# Publication sur Test PyPI
poetry publish --build --repository test-pypi

# Publication sur PyPI
poetry publish --build&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Bu komut, içinde bulunan bilgileri otomatik olarak kullanır`pyproject.toml`.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_yeniden_üretilebilir_derlemeler_docker_ile&quot;&gt;Yeniden üretilebilir derlemeler Docker ile&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Geliştirme, CI/CD ve üretimde aynı yürütmeleri sağlamak için Docker, Poetry ile mükemmel bir şekilde entegre olur.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_dockerfile_örneği&quot;&gt;Dockerfile örneği&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-dockerfile hljs&quot; data-lang=&quot;dockerfile&quot;&gt;FROM python:3.11-slim

WORKDIR /app
COPY pyproject.toml poetry.lock ./
RUN pip install poetry
RUN poetry install --no-root --only main

COPY . .

CMD [&quot;poetry&quot;, &quot;run&quot;, &quot;python&quot;, &quot;cli.py&quot;]&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Bu garanti eder : - Buzlanmış bir Python ortamı. - kilitlenmiş bağımlılıklar vasıtasıyla`poetry.lock`. - Bir Docker destekleyen tüm sistemlerde çalıştırılabilir bir imaj.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_github_actionste_entegrasyon&quot;&gt;GitHub Actions&amp;#8217;te entegrasyon&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-yaml hljs&quot; data-lang=&quot;yaml&quot;&gt;name: Docker Build

on:
  push:
    branches: [main]

jobs:
  build-docker:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4
      - name: Build Docker image
        run: docker build -t ghcr.io/${{ github.repository }}:latest .
      - name: Push Docker image
        run: docker push ghcr.io/${{ github.repository }}:latest&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_şartlı_yayın&quot;&gt;Şartlı yayın&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Profesyonel bir pipeline içinde, yalnızca belirli durumlarda yayın yapabilmek gerekir: - Release candidates Test PyPI&amp;#8217;ye doğru - PyPI&amp;#8217;ye stabil sürümler. - Sadece Docker tarafından tetiklenen derlemeler için`main`.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-yaml hljs&quot; data-lang=&quot;yaml&quot;&gt;- name: Publish to Test PyPI
  if: contains(github.ref, &#39;-rc&#39;)
  run: poetry publish --build --repository test-pypi

- name: Publish to PyPI
  if: startsWith(github.ref, &#39;refs/tags/v&#39;)
  run: poetry publish --build&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Bu yaklaşım, kazara yapılan yayınları önler.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_renovate_ve_dependabot_ile_bağımlılık_otomasyonu&quot;&gt;Renovate ve Dependabot ile bağımlılık otomasyonu&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Bağımlılıklarınızın eski kalmasını önlemek için otomatik güncelleme araçlarını entegre edin.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_dependabot&quot;&gt;Dependabot&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-yaml hljs&quot; data-lang=&quot;yaml&quot;&gt;version: 2
updates:
  - package-ecosystem: &quot;pip&quot;
    directory: &quot;/&quot;
    schedule:
      interval: &quot;weekly&quot;
  - package-ecosystem: &quot;github-actions&quot;
    directory: &quot;/&quot;
    schedule:
      interval: &quot;weekly&quot;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Dependabot, Python ve GitHub Actions bağımlılıklarını güncellemek için her hafta PR açar.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_yeniden_düzenlemek&quot;&gt;Yeniden düzenlemek&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-json hljs&quot; data-lang=&quot;json&quot;&gt;{
  &quot;extends&quot;: [&quot;config:base&quot;],
  &quot;packageRules&quot;: [
    {
      &quot;matchManagers&quot;: [&quot;pip&quot;],
      &quot;groupName&quot;: &quot;python-dependencies&quot;,
      &quot;schedule&quot;: [&quot;before 6am on monday&quot;]
    }
  ]
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Renovate, daha hassas kontrol sağlar: bağımlılık gruplandırması, zamanlama ve ileri düzey kurallar.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_plantuml_diagramları&quot;&gt;PlantUML diagramları&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_kullanım_durumu_gelişmiş_cicd&quot;&gt;Kullanım Durumu – Gelişmiş CI/CD&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
actor Developer
actor GitHub as &quot;GitHub Actions&quot;
actor PyPI
actor DockerRegistry as &quot;Docker Kayıt Defteri&quot;
actor Automation as &quot;Yenileme/Dependabot&quot;

Developer --&amp;gt; (Push code)
(Trigger CI) --&amp;gt; GitHub
GitHub --&amp;gt; (Run Tests &amp;amp; Lint)
GitHub --&amp;gt; (Build Docker Image)
GitHub --&amp;gt; DockerRegistry
GitHub --&amp;gt; (Publish to Test PyPI)
GitHub --&amp;gt; (Promote to PyPI)
Automation --&amp;gt; (Update Dependencies)
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_sıra_koşullu_yayın&quot;&gt;Sıra – Koşullu Yayın&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
!theme vibrant
left to right direction
Developer -&amp;gt; GitHub: Push tag v1.2.3-rc
GitHub -&amp;gt; CI: Run tests
CI -&amp;gt; CD: Check release type
CD -&amp;gt; Test PyPI: Publish RC
Developer -&amp;gt; GitHub: Push tag v1.2.3
GitHub -&amp;gt; CD: Publish to PyPI
CD -&amp;gt; Docker Registry: Push Docker image
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_durumlar_cicd_boru_hattı&quot;&gt;Durumlar – CI/CD Boru Hattı&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
[*] --&amp;gt; Idle
Idle --&amp;gt; CI_Running : push
CI_Running --&amp;gt; CI_Success : tests ok
CI_Running --&amp;gt; CI_Failed : tests fail
CI_Success --&amp;gt; CD_Running : tag detected
CD_Running --&amp;gt; CD_Success : publish ok
CD_Running --&amp;gt; CD_Failed : error
CD_Success --&amp;gt; [*]
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_dağıtım_cicd_mimarisi&quot;&gt;Dağıtım – CI/CD Mimarisi&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
node &quot;Geliştirici Makinesi&quot; {
  component &quot;Git İstemcisi&quot;
}

node &quot;GitHub Actions&quot; {
  component &quot;CI İş Akışı&quot;
  component &quot;CD iş akışı&quot;
}

node &quot;Paket depoları&quot; {
  artifact &quot;Test PyPI&quot;
  artifact &quot;PyPI&quot;
  artifact &quot;Docker Kayıt Defteri&quot;
}

&quot;Geliştirici Makinesi&quot; --&amp;gt; &quot;GitHub Actions&quot;
&quot;GitHub Actions&quot; --&amp;gt; &quot;Test PyPI&quot;
&quot;GitHub Actions&quot; --&amp;gt; &quot;PyPI&quot;
&quot;GitHub Actions&quot; --&amp;gt; &quot;Docker Kayıt Defteri&quot;
@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_sonuç&quot;&gt;Sonuç&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Bu üçüncü bölümde, gördüğümüz şu şekilde: - Python paketlemeyi Poetry ile modernleştirin. Docker aracılığıyla tekrarlanabilir derlemeler sağlayın. - Bir koşullu yayın kurmak. Bağımlılık güncellemelerini otomatikleştir.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Artık bir CI/CD ardışık hattınız var&lt;strong&gt;tamam, sanayileştirilmiş ve güvenli&lt;/strong&gt;, projelerinizle birlikte gelişmeye hazır.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;Sommaire&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_giriş&quot;&gt;Giriş&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_cicd_işlem_hattı_mimarisi&quot;&gt;CI/CD işlem hattı mimarisi&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_proje_yapısı&quot;&gt;Proje Yapısı&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_pyproject_toml_ile_paket_konfigürasyonu&quot;&gt;pyproject.toml ile paket konfigürasyonu&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_cicd_i̇ş_akışı_testler_ve_kalite&quot;&gt;CI/CD İş Akışı - Testler ve Kalite&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_yayın_ve_dağıtım_i̇ş_akışı&quot;&gt;Yayın ve Dağıtım İş Akışı&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_mimari_diyagramlar&quot;&gt;Mimari diyagramlar&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_sekans_diyagramı_yayın_süreci&quot;&gt;Sekans Diyagramı - Yayın Süreci&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_durum_diyagramı_paketin_yaşam_döngüsü&quot;&gt;Durum Diyagramı - Paketin Yaşam Döngüsü&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_dağıtım_diyagramı_cicd_altyapısı&quot;&gt;Dağıtım Diyagramı - CI/CD Altyapısı&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_pipelinenin_nesneleri_ve_modelleri&quot;&gt;pipeline&amp;#8217;nin nesneleri ve modelleri&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_sınıf_diyagramı_cicd_modelleri&quot;&gt;Sınıf Diyagramı - CI/CD Modelleri&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_gizli_bilgiler_yapılandırması&quot;&gt;gizli bilgiler yapılandırması&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_github_actions_sırları&quot;&gt;GitHub Actions Sırları&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_pypi_belirteç_üretimi&quot;&gt;PyPI belirteç üretimi&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_yerel_geliştirme_betikleri&quot;&gt;Yerel Geliştirme Betikleri&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_makefile&quot;&gt;Makefile&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_versiyon_scripti&quot;&gt;Versiyon Scripti&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_i̇yi_uygulamalar_ve_öneriler&quot;&gt;İyi Uygulamalar ve Öneriler&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_semantik_versiyonlama&quot;&gt;Semantik Versiyonlama&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_branching_stratejisi&quot;&gt;Branching stratejisi&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_testler_ve_kapsam&quot;&gt;Testler ve Kapsam&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_güvenlik&quot;&gt;Güvenlik&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_i̇zleme_ve_gözlemlenebilirlik&quot;&gt;İzleme ve Gözlemlenebilirlik&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_pipeline_metrikleri&quot;&gt;Pipeline metrikleri&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_bildirimler&quot;&gt;Bildirimler&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_sonuç&quot;&gt;Sonuç&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_ek_kaynaklar&quot;&gt;Ek Kaynaklar&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_giriş&quot;&gt;Giriş&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;div class=&quot;title&quot;&gt;Hedef : Basit bir pipeline&amp;#8217;ı, paketleme ve yazılım mühendisliği modern standartlarına uygun sağlam bir endüstriyel pipeline&amp;#8217;a dönüştürün.&lt;/div&gt;
&lt;p&gt;Bu serinin ilk bölümünde, PyPI&amp;#8217;de bir Python paketinin testlerini ve yayınını otomatikleştirmek için basit ama etkili bir CI/CD ardışık düzeni oluşturduk.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Şimdi bu pipelini profesyonelleştirme zamanı gelmiştir. Bu ikinci bölümde, yapacağız :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Modern pyproject.toml standardına geçiş yap,&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Kalite ve güvenlik araçları ekle (Black, Mypy, Bandit, Safety)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Çoklu versiyon testlerini kurun,&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Test PyPI üzerinden aşamalı dağıtımı entegre edin,&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Versiyonlamayı otomatikleştirin ve ardışık hattın izlemesini iyileştirin.&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Fonksiyonel bir pipeline&amp;#8217;den profesyonel bir CI/CD altyapısına geçmeye hazırlanın.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Bir Python uygulaması PyPI&amp;#8217;ye dağıtmak, testleri, derlemeyi ve paket yayınlamayı otomatikleştiren sağlam bir CI/CD pipeline&amp;#8217;i gerektirir. Bu makale, modern Python ekosistemi&amp;#8217;nin en iyi uygulamalarına dayanarak, bir Python CLI uygulaması için GitHub Actions kullanılarak tam bir pipeline&amp;#8217;ın kurulumunu detaylandırır.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_cicd_işlem_hattı_mimarisi&quot;&gt;CI/CD işlem hattı mimarisi&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Oluşturacağımız işlem hattı, birden fazla aşamadan oluşan bir yaklaşımı takip ediyor :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
!theme plain
title PyPI&#39;ye Python CI/CD hattı
skinparam backgroundColor #f8f9fa
skinparam componentStyle rectangle

rectangle &quot;Geliştirici&quot; as dev
rectangle &quot;GitHub Depo&quot; as repo {
  rectangle &quot;.github/workflows/&quot; as workflows
  rectangle &quot;testler/&quot; as tests
  rectangle &quot;setup.py / pyproject.toml&quot; as setup
  rectangle &quot;requirements.txt&quot; as req
}

rectangle &quot;GitHub Actions&quot; as actions {
  rectangle &quot;test çalıştırıcı&quot; as test_runner
  rectangle &quot;İnşa&quot; as build
  rectangle &quot;Güvenlik taraması&quot; as security
  rectangle &quot;Kalite Kontrolü&quot; as quality
}

rectangle &quot;PyPI&quot; as pypi {
  rectangle &quot;Test PyPI&quot; as test_pypi
  rectangle &quot;Üretim PyPI&quot; as prod_pypi
}

rectangle &quot;Kullanıcılar&quot; as users

dev --&amp;gt; repo : push/PR
repo --&amp;gt; actions : trigger workflow
actions --&amp;gt; test_runner : run tests
actions --&amp;gt; security : security checks
actions --&amp;gt; quality : code quality
actions --&amp;gt; build : build package
build --&amp;gt; test_pypi : deploy (pre-release)
build --&amp;gt; prod_pypi : deploy (release)
prod_pypi --&amp;gt; users : install package

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_proje_yapısı&quot;&gt;Proje Yapısı&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Dağıtım için hazır bir Python CLI uygulaması standart bir yapıya uygun olmalıdır:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-text hljs&quot; data-lang=&quot;text&quot;&gt;playlist-downloader/
├── .github/
│   └── workflows/
│       ├── ci.yml
│       ├── release.yml
│       └── security.yml
├── src/
│   └── playlist_downloader/
│       ├── __init__.py
│       ├── cli.py
│       ├── core/
│       └── adapters/
├── tests/
│   ├── unit/
│   ├── integration/
│   └── conftest.py
├── docs/
├── pyproject.toml
├── requirements.txt
├── requirements-dev.txt
├── MANIFEST.in
├── README.md
├── LICENSE
└── CHANGELOG.md&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_pyproject_toml_ile_paket_konfigürasyonu&quot;&gt;pyproject.toml ile paket konfigürasyonu&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Dosya`pyproject.toml`Python paketlerini yapılandırmak için modern standarttır :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-toml hljs&quot; data-lang=&quot;toml&quot;&gt;[build-system]
requires = [&quot;setuptools&amp;gt;=45&quot;, &quot;wheel&quot;, &quot;setuptools_scm&amp;gt;=6.2&quot;]
build-backend = &quot;setuptools.build_meta&quot;

[project]
name = &quot;playlist-downloader&quot;
authors = [
    {name = &quot;Christophe Hérolivier&quot;, email = &quot;cheroliv@example.com&quot;},
]
description = &quot;CLI tool for YouTube playlist management&quot;
readme = &quot;README.md&quot;
requires-python = &quot;&amp;gt;=3.8&quot;
keywords = [&quot;youtube&quot;, &quot;playlist&quot;, &quot;cli&quot;, &quot;downloader&quot;]
license = {text = &quot;MIT&quot;}
classifiers = [
    &quot;Development Status :: 4 - Beta&quot;,
    &quot;Environment :: Console&quot;,
    &quot;Intended Audience :: End Users/Desktop&quot;,
    &quot;License :: OSI Approved :: MIT License&quot;,
    &quot;Operating System :: OS Independent&quot;,
    &quot;Programming Language :: Python :: 3&quot;,
    &quot;Programming Language :: Python :: 3.8&quot;,
    &quot;Programming Language :: Python :: 3.9&quot;,
    &quot;Programming Language :: Python :: 3.10&quot;,
    &quot;Programming Language :: Python :: 3.11&quot;,
    &quot;Topic :: Multimedia :: Sound/Audio&quot;,
    &quot;Topic :: Utilities&quot;,
]
dependencies = [
    &quot;typer&amp;gt;=0.9.0&quot;,
    &quot;yt-dlp&amp;gt;=2023.7.6&quot;,
    &quot;google-api-python-client&amp;gt;=2.0.0&quot;,
    &quot;google-auth-oauthlib&amp;gt;=1.0.0&quot;,
    &quot;pyyaml&amp;gt;=6.0&quot;,
    &quot;rich&amp;gt;=13.0.0&quot;,
]
dynamic = [&quot;version&quot;]

[project.optional-dependencies]
dev = [
    &quot;pytest&amp;gt;=7.0.0&quot;,
    &quot;pytest-cov&amp;gt;=4.0.0&quot;,
    &quot;pytest-mock&amp;gt;=3.10.0&quot;,
    &quot;black&amp;gt;=23.0.0&quot;,
    &quot;flake8&amp;gt;=6.0.0&quot;,
    &quot;mypy&amp;gt;=1.0.0&quot;,
    &quot;pre-commit&amp;gt;=3.0.0&quot;,
    &quot;tox&amp;gt;=4.0.0&quot;,
]
test = [
    &quot;pytest&amp;gt;=7.0.0&quot;,
    &quot;pytest-cov&amp;gt;=4.0.0&quot;,
    &quot;pytest-mock&amp;gt;=3.10.0&quot;,
]

[project.urls]
Homepage = &quot;https://github.com/cheroliv/playlist-downloader&quot;
Documentation = &quot;https://github.com/cheroliv/playlist-downloader#readme&quot;
Repository = &quot;https://github.com/cheroliv/playlist-downloader.git&quot;
&quot;Bug Tracker&quot; = &quot;https://github.com/cheroliv/playlist-downloader/issues&quot;

[project.scripts]
playlist-downloader = &quot;playlist_downloader.cli:main&quot;

[tool.setuptools_scm]
write_to = &quot;src/playlist_downloader/_version.py&quot;

[tool.setuptools.packages.find]
where = [&quot;src&quot;]

[tool.pytest.ini_options]
testpaths = [&quot;tests&quot;]
python_files = [&quot;test_*.py&quot;]
python_classes = [&quot;Test*&quot;]
python_functions = [&quot;test_*&quot;]
addopts = [
    &quot;--cov=src/playlist_downloader&quot;,
    &quot;--cov-report=html&quot;,
    &quot;--cov-report=term-missing&quot;,
    &quot;--cov-fail-under=85&quot;,
]

[tool.black]
line-length = 88
target-version = [&#39;py38&#39;]
include = &#39;\.pyi?$&#39;
extend-exclude = &#39;&#39;&#39;
/(
  \.eggs
  | \.git
  | \.hg
  | \.mypy_cache
  | \.tox
  | \.venv
  | _build
  | buck-out
  | build
  | dist
)/
&#39;&#39;&#39;

[tool.mypy]
python_version = &quot;3.8&quot;
warn_return_any = true
warn_unused_configs = true
disallow_untyped_defs = true
disallow_incomplete_defs = true
check_untyped_defs = true
disallow_untyped_decorators = true
no_implicit_optional = true
warn_redundant_casts = true
warn_unused_ignores = true
warn_no_return = true
warn_unreachable = true
strict_equality = true

[[tool.mypy.overrides]]
module = [
    &quot;yt_dlp.*&quot;,
    &quot;googleapiclient.*&quot;,
    &quot;google_auth_oauthlib.*&quot;,
]
ignore_missing_imports = true&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_cicd_i̇ş_akışı_testler_ve_kalite&quot;&gt;CI/CD İş Akışı - Testler ve Kalite&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Ana iş akışı (&lt;code&gt;ci.yml&lt;/code&gt;) Birden fazla Python sürümünde testleri çalıştırır :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-yaml hljs&quot; data-lang=&quot;yaml&quot;&gt;name: CI

on:
  push:
    branches: [ main, develop ]
  pull_request:
    branches: [ main ]

jobs:
  test:
    runs-on: ubuntu-latest
    strategy:
      matrix:
        python-version: [&quot;3.8&quot;, &quot;3.9&quot;, &quot;3.10&quot;, &quot;3.11&quot;]

    steps:
    - uses: actions/checkout@v4
      with:
        fetch-depth: 0

    - name: Set up Python ${{ matrix.python-version }}
      uses: actions/setup-python@v4
      with:
        python-version: ${{ matrix.python-version }}

    - name: Cache dependencies
      uses: actions/cache@v3
      with:
        path: |
          ~/.cache/pip
          ~/.cache/pre-commit
        key: ${{ runner.os }}-pip-${{ hashFiles(&#39;**/requirements*.txt&#39;) }}
        restore-keys: |
          ${{ runner.os }}-pip-

    - name: Install dependencies
      run: |
        python -m pip install --upgrade pip
        pip install -e &quot;.[dev]&quot;

    - name: Lint with flake8
      run: |
        flake8 src tests --count --select=E9,F63,F7,F82 --show-source --statistics
        flake8 src tests --count --exit-zero --max-complexity=10 --max-line-length=88 --statistics

    - name: Check code formatting with Black
      run: black --check src tests

    - name: Type checking with mypy
      run: mypy src

    - name: Run tests with pytest
      run: |
        pytest tests/ -v --cov=src/playlist_downloader \
          --cov-report=xml --cov-report=term-missing

    - name: Upload coverage to Codecov
      uses: codecov/codecov-action@v3
      if: matrix.python-version == &#39;3.11&#39;
      with:
        file: ./coverage.xml
        flags: unittests
        name: codecov-umbrella

  security:
    runs-on: ubuntu-latest
    steps:
    - uses: actions/checkout@v4

    - name: Set up Python
      uses: actions/setup-python@v4
      with:
        python-version: &quot;3.11&quot;

    - name: Install dependencies
      run: |
        python -m pip install --upgrade pip
        pip install bandit[toml] safety

    - name: Run security checks with bandit
      run: bandit -r src/ -f json -o bandit-report.json

    - name: Check dependencies with safety
      run: safety check --json --output safety-report.json

    - name: Upload security reports
      uses: actions/upload-artifact@v3
      if: always()
      with:
        name: security-reports
        path: |
          bandit-report.json
          safety-report.json

  build:
    needs: [test, security]
    runs-on: ubuntu-latest
    steps:
    - uses: actions/checkout@v4
      with:
        fetch-depth: 0

    - name: Set up Python
      uses: actions/setup-python@v4
      with:
        python-version: &quot;3.11&quot;

    - name: Install build dependencies
      run: |
        python -m pip install --upgrade pip
        pip install build twine

    - name: Build package
      run: python -m build

    - name: Check package with twine
      run: twine check dist/*

    - name: Upload build artifacts
      uses: actions/upload-artifact@v3
      with:
        name: dist
        path: dist/&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_yayın_ve_dağıtım_i̇ş_akışı&quot;&gt;Yayın ve Dağıtım İş Akışı&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Yayın iş akışı`release.yml`) PyPI&amp;#8217;de otomatik yayınlamayı yönetir :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-yaml hljs&quot; data-lang=&quot;yaml&quot;&gt;name: Release

on:
  push:
    tags:
      - &#39;v*.*.*&#39;
  workflow_dispatch:
    inputs:
      environment:
        description: &#39;Deployment environment&#39;
        required: true
        default: &#39;test&#39;
        type: choice
        options:
        - test
        - production

env:
  PYTHON_VERSION: &quot;3.11&quot;

jobs:
  release:
    runs-on: ubuntu-latest
    environment:
      name: ${{ github.event.inputs.environment || (startsWith(github.ref, &#39;refs/tags/&#39;) &amp;amp;&amp;amp; &#39;production&#39; || &#39;test&#39;) }}

    steps:
    - uses: actions/checkout@v4
      with:
        fetch-depth: 0

    - name: Set up Python
      uses: actions/setup-python@v4
      with:
        python-version: ${{ env.PYTHON_VERSION }}

    - name: Install dependencies
      run: |
        python -m pip install --upgrade pip
        pip install build twine

    - name: Build package
      run: python -m build

    - name: Check package
      run: twine check dist/*

    - name: Publish to Test PyPI
      if: github.event.inputs.environment == &#39;test&#39; || (startsWith(github.ref, &#39;refs/tags/&#39;) &amp;amp;&amp;amp; contains(github.ref, &#39;rc&#39;))
      env:
        TWINE_USERNAME: __token__
        TWINE_PASSWORD: ${{ secrets.TEST_PYPI_API_TOKEN }}
      run: |
        twine upload --repository testpypi dist/*

    - name: Publish to PyPI
      if: github.event.inputs.environment == &#39;production&#39; || (startsWith(github.ref, &#39;refs/tags/&#39;) &amp;amp;&amp;amp; !contains(github.ref, &#39;rc&#39;))
      env:
        TWINE_USERNAME: __token__
        TWINE_PASSWORD: ${{ secrets.PYPI_API_TOKEN }}
      run: |
        twine upload dist/*

    - name: Create GitHub Release
      if: startsWith(github.ref, &#39;refs/tags/&#39;)
      uses: actions/create-release@v1
      env:
        GITHUB_TOKEN: ${{ secrets.GITHUB_TOKEN }}
      with:
        tag_name: ${{ github.ref }}
        release_name: Release ${{ github.ref }}
        draft: false
        prerelease: ${{ contains(github.ref, &#39;rc&#39;) }}

  post-release:
    needs: release
    runs-on: ubuntu-latest
    if: startsWith(github.ref, &#39;refs/tags/&#39;)

    steps:
    - uses: actions/checkout@v4

    - name: Set up Python
      uses: actions/setup-python@v4
      with:
        python-version: ${{ env.PYTHON_VERSION }}

    - name: Test installation from PyPI
      run: |
        sleep 60  # Attendre la propagation sur PyPI
        pip install playlist-downloader
        playlist-downloader --version

    - name: Update documentation
      run: |
        # Script pour mettre à jour la documentation
        echo &quot;Documentation updated for version ${GITHUB_REF#refs/tags/}&quot;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_mimari_diyagramlar&quot;&gt;Mimari diyagramlar&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_sekans_diyagramı_yayın_süreci&quot;&gt;Sekans Diyagramı - Yayın Süreci&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
!theme plain
title PyPI&#39;ye Release dizisi
actor Developer as dev
participant &quot;GitHub&quot; as gh
participant &quot;GitHub Eylemleri&quot; as ga
participant &quot;Test PyPI&quot; as tpypi
participant &quot;PyPI&quot; as pypi
participant &quot;Kullanıcılar&quot; as users

dev -&amp;gt; gh : git push --tags v1.2.3
gh -&amp;gt; ga : trigger release workflow

ga -&amp;gt; ga : checkout code
ga -&amp;gt; ga : setup Python environment
ga -&amp;gt; ga : install dependencies
ga -&amp;gt; ga : run tests
ga -&amp;gt; ga : build package (wheel + sdist)
ga -&amp;gt; ga : check package with twine

alt Pre-release (rc tag)
    ga -&amp;gt; tpypi : upload to Test PyPI
    tpypi -&amp;gt; ga : confirm upload
else Stable release
    ga -&amp;gt; pypi : upload to PyPI
    pypi -&amp;gt; ga : confirm upload
end

ga -&amp;gt; gh : create GitHub release
ga -&amp;gt; ga : test installation from PyPI

users -&amp;gt; pypi : pip install playlist-downloader
pypi -&amp;gt; users : download package

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_durum_diyagramı_paketin_yaşam_döngüsü&quot;&gt;Durum Diyagramı - Paketin Yaşam Döngüsü&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
!theme plain
title Python Paketi Durumları
[*] --&amp;gt; Development
Development --&amp;gt; Testing : commit/PR
Testing --&amp;gt; Development : tests fail
Testing --&amp;gt; Built : tests pass
Built --&amp;gt; TestPyPI : pre-release tag
Built --&amp;gt; PyPI : stable tag
TestPyPI --&amp;gt; PyPI : validation OK
PyPI --&amp;gt; Published
Published --&amp;gt; [*]

state Development {
  [*] --&amp;gt; Coding
  Coding --&amp;gt; LocalTesting
  LocalTesting --&amp;gt; Coding : fix issues
  LocalTesting --&amp;gt; ReadyForCI : all tests pass
}

state Testing {
  [*] --&amp;gt; CITests
  CITests --&amp;gt; SecurityScan
  SecurityScan --&amp;gt; QualityCheck
  QualityCheck --&amp;gt; BuildValidation
}

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_dağıtım_diyagramı_cicd_altyapısı&quot;&gt;Dağıtım Diyagramı - CI/CD Altyapısı&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
!theme plain
title Dağıtım Altyapısı
node &quot;GitHub&quot; {
  component &quot;depo&quot; as repo
  component &quot;Actions Çalıştırıcı&quot; as runner
  component &quot;Sırlar Deposu&quot; as secrets
}

node &quot;PyPI Altyapısı&quot; {
  component &quot;PyPI&quot; as pypi
  component &quot;Test PyPI&quot; as testpypi
  database &quot;Paket İndeksi&quot; as index
}

node &quot;Geliştirici Makine&quot; {
  component &quot;Git İstemcisi&quot; as git
  component &quot;Python Ortamı&quot; as python
  component &quot;Entegre Geliştirme Ortamı&quot; as ide
}

node &quot;Kullanıcı Ortamı&quot; {
  component &quot;çekirdek&quot; as pip_client
  component &quot;Python Çalışma Zamanı&quot; as py_runtime
}

git --&amp;gt; repo : push code/tags
repo --&amp;gt; runner : trigger workflows
runner --&amp;gt; secrets : read API tokens
runner --&amp;gt; testpypi : upload pre-release
runner --&amp;gt; pypi : upload release
pypi --&amp;gt; index : store package
pip_client --&amp;gt; pypi : download package
py_runtime &amp;lt;-- pip_client : install package

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_pipelinenin_nesneleri_ve_modelleri&quot;&gt;pipeline&amp;#8217;nin nesneleri ve modelleri&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_sınıf_diyagramı_cicd_modelleri&quot;&gt;Sınıf Diyagramı - CI/CD Modelleri&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre&gt;@startuml
!theme plain
title CI/CD İşlem hattı modelleri
class PipelineConfig {
  +python_versions: List[str]
  +test_environments: List[str]
  +security_checks: bool
  +coverage_threshold: float
  +validate()
}

class BuildArtifact {
  +name: str
  +version: str
  +wheel_path: str
  +sdist_path: str
  +checksums: Dict[str, str]
  +validate_integrity()
}

class TestResult {
  +test_suite: str
  +python_version: str
  +passed: int
  +failed: int
  +coverage: float
  +duration: float
  +is_success(): bool
}

class SecurityReport {
  +bandit_issues: List[Issue]
  +safety_vulnerabilities: List[Vulnerability]
  +severity_level: str
  +is_secure(): bool
}

class DeploymentTarget {
  +name: str
  +url: str
  +api_token: str
  +environment: str
  +deploy(artifact: BuildArtifact)
}

class ReleaseManager {
  +version: str
  +changelog: str
  +artifacts: List[BuildArtifact]
  +test_results: List[TestResult]
  +security_report: SecurityReport
  +deploy_to_test()
  +deploy_to_production()
  +create_github_release()
}

PipelineConfig ||--o{ TestResult
ReleaseManager *-- BuildArtifact
ReleaseManager *-- SecurityReport
ReleaseManager o-- DeploymentTarget
DeploymentTarget ..&amp;gt; BuildArtifact : uses

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_gizli_bilgiler_yapılandırması&quot;&gt;gizli bilgiler yapılandırması&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Pipeline&amp;#8217;ın çalışabilmesi için, GitHub&amp;#8217;de aşağıdaki gizli dizileri yapılandırmanız gerekir:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_github_actions_sırları&quot;&gt;GitHub Actions Sırları&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;# Dans Settings &amp;gt; Secrets and variables &amp;gt; Actions

# Token PyPI pour la production
PYPI_API_TOKEN=pypi-...

# Token Test PyPI pour les pré-releases
TEST_PYPI_API_TOKEN=pypi-...

# Token GitHub pour créer les releases
GITHUB_TOKEN=(automatiquement fourni)

# Token Codecov (optionnel)
CODECOV_TOKEN=...&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_pypi_belirteç_üretimi&quot;&gt;PyPI belirteç üretimi&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-bash hljs&quot; data-lang=&quot;bash&quot;&gt;# 1. Créer un compte sur PyPI et Test PyPI
# 2. Aller dans Account Settings &amp;gt; API tokens
# 3. Créer un token avec scope &quot;Entire account&quot; ou spécifique au projet
# 4. Format du token : pypi-AgEIcHlwaS5vcmc...&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_yerel_geliştirme_betikleri&quot;&gt;Yerel Geliştirme Betikleri&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Geliştirmeyi kolaylaştırmak için faydalı komut dosyaları oluşturun:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_makefile&quot;&gt;Makefile&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-makefile hljs&quot; data-lang=&quot;makefile&quot;&gt;.PHONY: install test lint format security build clean release-test release-prod

install:
	pip install -e &quot;.[dev]&quot;

test:
	pytest tests/ -v --cov=src/playlist_downloader

lint:
	flake8 src tests
	mypy src

format:
	black src tests

security:
	bandit -r src/
	safety check

build:
	python -m build
	twine check dist/*

clean:
	rm -rf build/ dist/ *.egg-info/
	find . -type d -name __pycache__ -delete
	find . -name &quot;*.pyc&quot; -delete

release-test: clean build
	twine upload --repository testpypi dist/*

release-prod: clean build
	twine upload dist/*

pre-commit: format lint test security
	@echo &quot;✅ Prêt pour commit&quot;&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_versiyon_scripti&quot;&gt;Versiyon Scripti&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-python hljs&quot; data-lang=&quot;python&quot;&gt;#!/usr/bin/env python3
&quot;&quot;&quot;Script pour gérer les versions du projet.&quot;&quot;&quot;

import sys
import subprocess
from pathlib import Path

def get_current_version():
    &quot;&quot;&quot;Récupère la version actuelle depuis git.&quot;&quot;&quot;
    try:
        result = subprocess.run(
            [&quot;git&quot;, &quot;describe&quot;, &quot;--tags&quot;, &quot;--abbrev=0&quot;],
            capture_output=True,
            text=True,
            check=True
        )
        return result.stdout.strip()
    except subprocess.CalledProcessError:
        return &quot;0.0.0&quot;

def create_version_tag(version, message=None):
    &quot;&quot;&quot;Crée un tag de version.&quot;&quot;&quot;
    if not version.startswith(&#39;v&#39;):
        version = f&#39;v{version}&#39;

    tag_message = message or f&quot;Release {version}&quot;

    subprocess.run([&quot;git&quot;, &quot;tag&quot;, &quot;-a&quot;, version, &quot;-m&quot;, tag_message], check=True)
    print(f&quot;✅ Tag {version} créé&quot;)

    # Push le tag
    subprocess.run([&quot;git&quot;, &quot;push&quot;, &quot;origin&quot;, version], check=True)
    print(f&quot;✅ Tag {version} poussé vers origin&quot;)

if __name__ == &quot;__main__&quot;:
    if len(sys.argv) &amp;lt; 2:
        current = get_current_version()
        print(f&quot;Version actuelle: {current}&quot;)
        print(&quot;Usage: python version.py &amp;lt;new_version&amp;gt; [message]&quot;)
        sys.exit(1)

    new_version = sys.argv[1]
    message = sys.argv[2] if len(sys.argv) &amp;gt; 2 else None

    create_version_tag(new_version, message)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_i̇yi_uygulamalar_ve_öneriler&quot;&gt;İyi Uygulamalar ve Öneriler&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_semantik_versiyonlama&quot;&gt;Semantik Versiyonlama&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Anlamsal sürümleme (SemVer) kullanın:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;MAJOR.MINOR.PATCH&lt;/code&gt; (ex: 1.2.3)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;MAJOR&lt;/code&gt;: uyumsuz değişiklikler&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;MINOR&lt;/code&gt;: uyumlu yeni özellikler&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;PATCH&lt;/code&gt;: uyumlu hata düzeltmeleri&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_branching_stratejisi&quot;&gt;Branching stratejisi&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-text hljs&quot; data-lang=&quot;text&quot;&gt;main          ──●──●──●──●──●────●── (releases stables)
               /       /          /
develop    ──●──●──●──●──●──●──●──●── (développement)
            /     /        /
feature/xxx  ●──●──●──●──●──/ (fonctionnalités)&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_testler_ve_kapsam&quot;&gt;Testler ve Kapsam&lt;/h3&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Minimum kod kapsamlılığı: 85%&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;İş mantığı için birim testleri&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Entegrasyon testleri için adaptörler&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;CLI için uçtan uca testler&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_güvenlik&quot;&gt;Güvenlik&lt;/h3&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Otomatik bağımlılık taraması (Safety)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Statik kod analizi (Bandit)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Kodda hiçbir gizli yok&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Belirli PyPI belirteçlerinin kullanımı&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_i̇zleme_ve_gözlemlenebilirlik&quot;&gt;İzleme ve Gözlemlenebilirlik&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_pipeline_metrikleri&quot;&gt;Pipeline metrikleri&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-yaml hljs&quot; data-lang=&quot;yaml&quot;&gt;# .github/workflows/metrics.yml
name: Pipeline Metrics

on:
  workflow_run:
    workflows: [&quot;CI&quot;, &quot;Release&quot;]
    types: [completed]

jobs:
  metrics:
    runs-on: ubuntu-latest
    steps:
    - name: Collect metrics
      run: |
        echo &quot;Pipeline: ${{ github.event.workflow_run.name }}&quot;
        echo &quot;Status: ${{ github.event.workflow_run.conclusion }}&quot;
        echo &quot;Duration: ${{ github.event.workflow_run.updated_at - github.event.workflow_run.created_at }}&quot;
        # Envoyer vers système de monitoring&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_bildirimler&quot;&gt;Bildirimler&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-yaml hljs&quot; data-lang=&quot;yaml&quot;&gt;# Ajout dans les workflows pour notifications
- name: Notify on failure
  if: failure()
  uses: 8398a7/action-slack@v3
  with:
    status: failure
    text: &quot;❌ Pipeline failed for ${{ github.repository }}&quot;
  env:
    SLACK_WEBHOOK_URL: ${{ secrets.SLACK_WEBHOOK }}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_sonuç&quot;&gt;Sonuç&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Bu tam CI/CD iş hattı Python için şunları sunar:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Tam otomasyon&lt;/strong&gt;: kod doğrulamasından yayınlamaya&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Güvenlik&lt;/strong&gt;: otomatik taramalar ve gizli verilerin güvenli yönetimi&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Kalite&lt;/strong&gt;: çoklu sürüm testleri, lint denetimi ve kod kapsamlılığı&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Güvenilirlik&lt;/strong&gt;: Test PyPI üzerinden aşamalı dağıtım&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;İzlenebilirlik&lt;/strong&gt;: manşe, raporlar ve sürümler GitHub&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Bu uygulamaların benimsenmesi, Python CLI uygulamalarınız için sağlam ve profesyonel bir teslimat süreci sağlar, uzun vadeli olarak projelerinizin bakımını ve gelişimini kolaylaştırır.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
